/* KP: 知识点讲解字典 */
const KP = {
  "算术移位": {"tag":"计算机的运算方法 · 6.3","sub":"带符号数左移/右移时，空位补什么","fig":"fig-shift","cap":"补码负数算术右移补符号位 1，负号不丢","def":"对有符号机器数进行移位以完成 ×2ⁿ / ÷2ⁿ 的运算。左移相当于乘 2，右移相当于除以 2。空位补入的位由机器数类型决定。","fx":["算术左移：低位补 0","算术右移：高位补符号（原码补0，补码负数补1，反码负数补1）","逻辑移位：无论左右，空位一律补 0"],"dv":{"title":"为什么补码负数右移要补 1","steps":["补码负数的符号位是 1，它表示“这个数是负的”","算术右移 = 除以 2，负数除以 2 仍是负数","若右移补 0，符号位会变 0，负号被抹掉，结果就错了","所以右移时把符号位复制到空位（符号位扩展）","结论：补码算术右移 = 负数补 1、正数补 0"]},"key":"左移补 0；右移看码制——原码补 0、补码/反码负数补 1。逻辑移位一律补 0。"},
  "原码一位乘": {"tag":"计算机的运算方法 · 6.3","sub":"符号位单独处理、数值位“加+右移”逐位求积","fig":"fig-mul","cap":"部分积 A 与乘数 Q 联合右移，乘数末位决定加 0 还是加 X","def":"原码乘法中符号位和数值位分开处理：符号位由两数符号异或得到；数值位用“加法—右移”循环 n 次求出。","fx":["符号位 = xs ⊕ ys","循环 n 次 { 看乘数末位 q₀：为1加 X、为0加 0 → A、Q 联合右移一位 }","积的数值位 = 最终 A 与 Q 的拼接"],"dv":{"title":"为什么用“联合右移”逐位求积","steps":["把乘法展开：X·Y = X·(y₁2⁻¹ + y₂2⁻² + … + yₙ2⁻ⁿ)","每算一位，部分积要除以 2（右移一位），相当于把当前累加结果降一个数量级","“乘数一起右移”是为了让每次露出的末位正好是还没用过的下一位 y","n 次之后，部分积高位与移出的乘数位拼起来恰是完整的积","本质：用“移位”代替“逐位配权”，把乘法拆成加法+移位循环"]},"key":"符号位单独异或；数值位 n 次「看末位加 0/X → 联合右移」；顺序是先加后移。"},
  "补码一位乘Booth": {"tag":"计算机的运算方法 · 6.3","sub":"符号位一起算，看 (yₙ,yₙ₊₁) 决定加 X / −X / 0","fig":"fig-booth","cap":"Booth 判定电路：比较乘数末位与附加位，选择 +X / −X / 0","def":"Booth 算法用于补码一位乘法。乘数最低位 yₙ 与附加位 yₙ₊₁（初始 0）组成两位：(0,1) 加 [X]补，(1,0) 加 [−X]补，(0,0)/(1,1) 不加；然后算术右移一位，循环 n 次后再做一次“只加不移”。","fx":["(yₙ,yₙ₊₁) = 0 1 → +[X]补  （1,0 → +[−X]补；00/11 → +0）","每次判定后算术右移一位","n 次循环后末尾再做一次“只加不移”的收尾"],"dv":{"title":"Booth 为什么能减少加法次数","steps":["核心思想：连续的 1 串可以重写成两个边界之差","如 011110 = 100000 − 000010，只需处理“由0变1”和“由1变0”两处","(yₙ,yₙ₊₁)=0,1 表示进入 1 串 → 减 X（加 [−X]补）","(yₙ,yₙ₊₁)=1,0 表示离开 1 串 → 加 X","中间连续的 1（11）不再操作，故 Booth 平均比逐位乘法更快"]},"key":"符号位一起算；附加位初始 0；看 (yₙ,yₙ₊₁)：01 加 X、10 加 −X、00/11 不加；右移是算术右移；末步只加不移。"},
  "加减交替除法": {"tag":"计算机的运算方法 · 6.3","sub":"原码/补码一位除法——用“加减交替”免去恢复余数","fig":"fig-div","cap":"余数左移 → 加减除数 → 上商，循环 n 次","def":"除法是“减出商”。恢复余数法：减除数后若为负需把除数加回；加减交替法利用“负余数下一步改用加除数”，把“恢复+再减”合并成一步，省掉恢复。","fx":["R ≥ 0 → 商上 1，下一步 2R − Y","R < 0 → 商上 0，下一步 2R + Y","循环 n 次，商逐位左移拼接；补码除法末位“恒置 1”修正"],"dv":{"title":"加减交替为什么能省掉“恢复余数”","steps":["恢复余数法：减完为负要把除数加回去（多一次加法）","观察下一步本应算 (R+Y)·2 − Y = 2R + Y，两次并一次","所以余数为负时直接用“2R + Y”，已包含“恢复再加”的效果","正负交替地“该减则减、该加则加”，故称加减交替法","少一次恢复操作，除法更快、硬件更简单"]},"key":"商与余数符号决定下一步加还是减；R≥0 商1 做 2R−Y，R<0 商0 做 2R+Y。"},
  "浮点对阶": {"tag":"计算机的运算方法 · 6.4","sub":"浮点加减第一步：把两数阶码对齐","fig":"fig-float","cap":"浮点加减五步：对阶 → 尾数求和 → 规格化 → 舍入 → 判溢出","def":"浮点加减必须先把两数阶码对齐才能相加。规则是“小阶向大阶看齐”：把小阶的数的尾数右移阶差位，使其阶码与大阶相同，然后再做尾数加减。","fx":["对阶：小阶向大阶看齐，尾数右移 (大阶 − 小阶) 位","尾数求和 → 规格化 → 舍入 → 判溢出","例：0.1101×2⁰¹ 与 −0.1010×2⁰⁰ → 后者右移1位成 −0.0101×2⁰¹"],"dv":{"title":"为什么对阶要“小阶向大阶看齐”","steps":["浮点相加必须阶码相同，尾数才能直接相加","若大阶向小阶看齐，大数尾数要左移，会超出位宽、高位丢失","若小阶向大阶看齐，只把小数尾数右移，损失的是低位最低有效位","丢低位比丢高位影响小得多（大数吃小数）","故规定：小阶向大阶看齐"]},"key":"对阶只能“小阶向大阶看齐”；浮点加减五步：对阶→尾数求和→规格化→舍入→判溢出。"},
  "位置矢量": {"dv":{"title":"为什么用矢量描述位置","steps":["质点的位置既要方向又要距离，标量不足以确定","建立坐标系后，用从原点指向质点的有向线段 r 表示位置","把 r 沿三个坐标轴分解：r = x i + y j + z k","模 |r| = √(x²+y²+z²) 给出到原点的距离","r 随时间变化即 r(t)，消去 t 得轨迹方程"]},"tag":"质点运动学 · 1.1","sub":"描述质点「在哪」的基本量","fig":"fig-vectors","cap":"位置矢量随时间的改变量即为位移","def":"从坐标原点指向质点当前位置的有向线段，记作 <b>r = x i + y j + z k</b>；其模 |r| 表示到原点的距离。运动方程 r = r(t) 完整描述质点的运动。","fx":["r = x i + y j + z k","|r| = √(x² + y² + z²)","运动方程 r = r(t)，消去 t 得轨迹"],"key":"位置矢量是矢量；它的变化量 Δr = r₂ − r₁ 才是位移，只与始末位置有关，与路径无关。"},
  "位移vs路程": {"dv":{"title":"位移与路程的区别","steps":["位移 Δr = r₂ − r₁ 只由始末位置决定，是矢量","无论走哪条路径，只要始末相同，Δr 就相同","路程 Δs 是轨迹累计长度，沿路径积分 Δs = ∫|dr|","由三角不等式，一般 |Δr| ≤ Δs","仅当单向直线运动时取等号 |Δr| = Δs"]},"tag":"质点运动学 · 1.1","sub":"矢量 vs 标量——最易混淆的一对概念","def":"位移 Δr 是矢量，由始点到终点的有向线段，只与始末位置有关，与路径无关；路程 Δs 是标量，是轨迹的累计长度，与路径有关。","fx":["位移 Δr = r₂ − r₁（矢量）","路程 Δs = ∫|dr|（标量）","单向直线运动时 |Δr| = Δs","一般情况 |Δr| ≤ Δs"],"key":"绕操场跑一圈回到原点：位移为 0，路程为周长。判断大小先问「是不是单向直线运动」。"},
  "v=dr/dt": {"tag":"质点运动学 · 1.1","sub":"瞬时速度 = 位置对时间的变化率","def":"平均速度 v̄ = Δr/Δt；令 Δt→0 取极限得瞬时速度 v = dr/dt，方向沿轨迹切线，大小 |v| 即速率。","fx":["平均速度 v̄ = Δr / Δt","瞬时速度 v = lim(Δt→0) Δr/Δt = dr/dt"],"dv":{"title":"为什么瞬时速度方向沿轨迹切线","steps":["Δr 是弦，方向由起点指向终点","当 Δt→0，弦无限接近切线","故 v 的极限方向就是轨迹切线方向","速率 v = |v| 只是大小，不含方向"]},"key":"求导：x(t) 求导得 v(t)，再求导得 a(t)；反向积分则要带初始条件 v₀、r₀。"},
  "匀变速三公式": {"dv":{"title":"匀变速三公式的推导","steps":["由加速度定义 a = dv/dt，分离变量 dv = a dt","两边积分（a 为常量）：∫v₀→v dv = ∫₀→t a dt，得 v = v₀ + a t","再由 v = dx/dt，代入上式：dx = (v₀ + a t) dt","积分得 x = x₀ + v₀ t + ½ a t²","消去 t（由第一式 t = (v−v₀)/a 代入第二式）得 v² − v₀² = 2a(x − x₀)"]},"tag":"质点运动学 · 1.1","sub":"加速度 a 恒定时由积分得到的三大公式","def":"匀变速直线运动中 a 为常量，由 v = dr/dt 与 a = dv/dt 积分可导出三条公式，是解决直线运动问题的「黄金三式」。","anim":"anim-kine","cap":"速度随时间均匀增大，说明 a 为常量","fx":["v = v₀ + a t","x = x₀ + v₀ t + ½ a t²","v² − v₀² = 2 a (x − x₀)"],"key":"三式共用前提是 a 恒定；第三式不含 t，适合「已知位移求速度」的题。"},
  "向心加速度": {"dv":{"title":"向心加速度 aₙ = v²/R 的推导","steps":["圆周运动速度大小可不变，但方向时刻改变","取极短时间 Δt，速度矢量转过的角度 Δθ ≈ v Δt / R","速度增量的大小 |Δv| ≈ v·Δθ = v² Δt / R","取极限 aₙ = lim(Δt→0) Δv/Δt = v²/R","方向沿半径指向圆心，故称向心（法向）加速度"]},"tag":"质点运动学 · 1.2","sub":"改变速度方向的那部分加速度","def":"做圆周运动时速度方向不断改变，由此产生的加速度指向圆心，称法向（向心）加速度 <b>aₙ = v²/R = ω²R</b>；另一切向分量 aₜ = dv/dt 改变速率大小。","anim":"anim-circular","cap":"速度沿切线（方向在变），向心加速度始终指向圆心","fx":["aₙ = v²/R = ω²R","aₜ = dv/dt = Rα","总加速度 a = √(aₜ² + aₙ²)"],"key":"匀速圆周运动 aₜ = 0，但 aₙ ≠ 0——加速度不为零不代表速率在变。"},
  "伽利略变换": {"dv":{"title":"伽利略变换关系的由来","steps":["设 S′ 相对 S 以恒定速度 u 平动，t=0 时两原点重合","同一时刻质点在两系的位矢满足 r = r′ + u t","对时间求导得速度关系 v = v′ + u","再求导，因 u 为常量，得 a = a′","加速度不变，故牛顿定律在一切惯性系中形式相同"]},"tag":"质点运动学 · 1.3","sub":"不同惯性系之间运动量的换算","def":"设 S′ 系相对 S 系以恒定速度 u 平动，则同一质点在两系中的位置与速度满足伽利略变换；加速度在两系中相同。","fx":["位置 r = r′ + r₀","速度 v = v′ + u","加速度 a = a′"],"key":"速度是矢量叠加（可用三角形法则）；因 a 不变，牛顿定律在所有惯性系中形式相同。"},
  "惯性定律": {"dv":{"title":"第一定律的深意","steps":["由大量实验事实归纳：不受力时物体保持静止或匀速直线运动","它指出力不是维持运动的原因，而是改变运动状态的原因","据此定义惯性系——牛顿定律成立的参考系","在非惯性系中第一定律不成立，需引入惯性力","故第一定律是第二定律的前提（定义惯性系），并非其特例"]},"tag":"牛顿运动定律 · 2.1","sub":"第一定律——定义惯性系","def":"一切物体不受外力时保持静止或匀速直线运动状态。它揭示了物体的<b>惯性</b>，并定义了惯性参考系（牛顿定律成立的参考系）。","key":"第一定律不是第二定律的特例（F=0），它的价值在于定义惯性系、否定「力是维持运动的原因」。"},
  "F=ma": {"dv":{"title":"由 F = dp/dt 到 F = ma","steps":["牛顿第二定律原始形式 F = dp/dt","动量 p = m v，代入得 F = d(mv)/dt","按乘积法则展开：F = m dv/dt + v dm/dt","质量不变时 dm/dt = 0，得 F = m dv/dt = m a","变质量问题须保留 v dm/dt 项，不能直接用 F = ma"]},"tag":"牛顿运动定律 · 2.1","sub":"第二定律的常用形式","def":"物体动量对时间的变化率等于合外力：F = dp/dt；当质量不变时化为 <b>F = ma</b>，是动力学解题的核心方程。","fx":["F = dp/dt = m a（质量不变）","分量式：Fₓ = m aₓ ，F_y = m a_y"],"key":"F 是合外力；先受力分析、建坐标，再分方向列 F = ma。"},
  "F=dp/dt": {"dv":{"title":"第二定律的普遍形式","steps":["定义动量 p = m v（矢量）","实验表明合外力等于动量对时间的变化率 F = dp/dt","这是最普遍的形式，对变质量、变速度过程都成立","质量不变时退化为 F = ma","碰撞、火箭等过程要用积分形式 ∫F dt = Δp"]},"tag":"牛顿运动定律 · 2.1","sub":"第二定律的原始普遍形式","def":"F = dp/dt 是牛顿第二定律的原始表述，对变质量、变速度过程都成立，比 F = ma 更普适。","fx":["F = dp/dt = d(mv)/dt"],"key":"变质量问题（火箭、雨滴）必须回到 F = dp/dt，不能直接用 F = ma。"},
  "受力分析四步": {"dv":{"title":"受力分析的标准流程","steps":["①确定研究对象：把要分析的物体单独隔离出来","②按顺序找力：先重力，再弹力（接触面法向），后摩擦力（切向），最后其他外力","③建坐标系：一般沿运动方向与垂直方向为正","④列方程：沿运动方向 ΣFₓ = maₓ，垂直方向 ΣF_y = 0","检查：每个力都要有施力物体，做到不重不漏"]},"tag":"牛顿运动定律 · 2.4","sub":"解动力学题的标准流程","def":"① 选研究对象（整体或隔离）；② 受力分析（重力、弹力、摩擦力、外拉力）；③ 建坐标（沿运动方向为正）；④ 分方向列方程 Fₓ = maₓ、F_y = 0。","key":"摩擦力方向与相对运动（或趋势）相反——这一步最容易出错。"},
  "整体法+隔离法": {"dv":{"title":"整体法与隔离法的配合","steps":["整体法：把系统看作一个物体，内部相互作用力成对抵消不出现","对系统用牛顿第二定律求得整体加速度 a","隔离法：单独取出一物体，暴露它与其他部分的相互作用力","对该物体列 F = ma，即可解出所需内力（绳张力、压力）","固定套路：先整体求 a，再隔离求内力"]},"tag":"牛顿运动定律 · 2.4","sub":"求系统加速度与内部力的两把钥匙","def":"<b>整体法</b>：把整个系统当一个物体，内力不出现，便于求系统加速度；<b>隔离法</b>：隔离单个物体，用于求内部相互作用力（如绳张力、两物块间的弹力）。","key":"先用整体法求加速度，再用隔离法求内力，是连接体题目的固定套路。"},
  "摩擦力方向": {"dv":{"title":"静摩擦与滑动摩擦","steps":["滑动摩擦：方向与相对滑动方向相反，大小 f = μN","静摩擦：方向与相对滑动趋势相反，大小由平衡条件决定","静摩擦范围 0 ≤ f ≤ μ₀N，不能直接写 μN","判断趋势：假设接触面光滑，看物体将往哪滑","法向力 N 由法向平衡决定，斜面上 N = mg cosθ ≠ mg"]},"tag":"牛顿运动定律 · 2.3","sub":"静摩擦与滑动摩擦","def":"静摩擦力 0 ≤ f ≤ μ₀N，方向与相对滑动<b>趋势</b>相反，大小由平衡条件决定；滑动摩擦力 f = μN，方向与相对滑动方向相反。","fx":["静摩擦 0 ≤ f ≤ μ₀ N","滑动摩擦 f = μ N"],"key":"压力不一定等于 mg（斜面、加速系统要重新算 N）；静摩擦力大小不能直接用 μN。"},
  "冲量I=Δp": {"tag":"动量守恒和能量守恒 · 3.1","sub":"动量定理","def":"冲量 I = ∫F dt 是力对时间的累积；合外力的冲量等于动量的变化量。","fx":["I = ∫F dt","I = Δp = m v₂ − m v₁"],"dv":{"title":"由牛顿第二定律导出动量定理","steps":["从 F = dp/dt 出发","两边对时间积分：∫F dt = ∫(dp/dt) dt","左边是冲量 I，右边是动量变化 ∫dp = p₂ − p₁","⟹ I = Δp = m v₂ − m v₁","对变力、变质量均成立，比 F = ma 更普适"]},"key":"求平均力、碰撞冲量类问题首选动量定理：F̄ Δt = Δp。"},
  "动量守恒条件": {"dv":{"title":"由牛顿第三定律导出动量守恒","steps":["对两质点系统，各自动量变化率等于所受外力与内力之和","质点1受质点2的力 F₁₂，质点2受 F₂₁，第三定律给出 F₁₂ = −F₂₁","两式相加，内力成对抵消：d(p₁+p₂)/dt = F外","若合外力 F外 = 0，则 d(总动量)/dt = 0","故总动量守恒；某方向外力分量为零则该方向动量守恒"]},"tag":"动量守恒和能量守恒 · 3.2","sub":"系统总动量保持不变的条件","def":"当质点系所受<b>合外力为零</b>时，系统总动量保持不变：Σmᵢvᵢ = 常矢量。即使合外力不为零，若某方向分量为零，则该方向动量守恒。","fx":["合外力为零 ⟹ Σ mᵢ vᵢ = 常量","分量守恒：某方向 ΣF = 0 则该方向动量守恒"],"key":"碰撞、爆炸等短时过程常满足动量守恒；判断时先看外力能否忽略。"},
  "动能定理": {"tag":"动量守恒和能量守恒 · 3.4","sub":"功与动能变化的关系","def":"合外力做的功等于动能的变化量：W合 = ΔEk。适合只关心始末状态、不关心中间过程的题目。","fx":["W = ∫F·dr （变力要积分）","W合 = ΔEk = ½m v₂² − ½m v₁²"],"dv":{"title":"由 F = ma 导出动能定理","steps":["合外力做功定义 W = ∫F·dr","代入 F = m·dv/dt，并用 dr = v dt","W = ∫ m (dv/dt)·(v dt) = ∫ m v dv","定积分 W = ∫(v₁→v₂) m v dv = ½m v₂² − ½m v₁²","⟹ W = ΔEk"]},"key":"有摩擦、变力做功时用动能定理绕开积分，一步到位。"},
  "势能Ep": {"dv":{"title":"势能的引入","steps":["保守力做功只与始末位置有关，与路径无关","由此可定义一个只与位置有关的函数 Ep，即势能","令保守力做功等于势能的减少：W = −ΔEp","对重力 W = mg(h₁−h₂)，对比得 Ep = mgh","对弹性力 W = ∫kx dx = ½kx₁²−½kx₂²，得 Ep = ½kx²；势能需选零势能点"]},"tag":"动量守恒和能量守恒 · 3.5","sub":"保守力的位置能","def":"只有保守力才能引入势能：重力势能 Ep = mgh，弹性势能 Ep = ½kx²。保守力做功等于势能的减少：W = −ΔEp。","fx":["重力势能 E_p = m g h","弹性势能 E_p = ½ k x²","保守力做功 W = −ΔE_p"],"key":"势能属于系统（如「地球+物体」），且需选定零势能参考点。"},
  "机械能守恒": {"dv":{"title":"功能原理与机械能守恒","steps":["合外力与保守内力做功使动能变化：W外 + W保内 = ΔEk","保守内力做功可用势能表示：W保内 = −ΔEp","移项得 W外 + W非保内 = Δ(Ek+Ep) = ΔE，即功能原理","当 W外 = 0 且 W非保内 = 0 时，ΔE = 0","即机械能守恒 E = Ek + Ep = 常量"]},"tag":"动量守恒和能量守恒 · 3.6","sub":"功能原理的特例","def":"外力与非保守内力做功之和等于机械能的改变：W外 + W非保内 = ΔE。当 W外 = W非保内 = 0 时机械能守恒 E = Ek + Ep = 常量。","fx":["功能原理 W外 + W非保内 = ΔE","守恒条件：W外 = W非保内 = 0 ⟹ E = 常量"],"key":"有摩擦时机械能不守恒，但总能量仍守恒；守恒判断关键看有无非保守力做功。"},
  "碰撞三类型": {"dv":{"title":"碰撞过程的分析","steps":["碰撞时间极短，外力冲量可忽略，故动量守恒","完全弹性碰撞：动能也守恒，需同时用动量与能量方程","完全非弹性碰撞：碰后速度相同（共速），动能损失最大","一般非弹性碰撞：动量守恒，动能部分损失","判据：题目是否给出动能守恒条件，决定用哪种模型"]},"tag":"动量守恒和能量守恒 · 3.7","sub":"动量守恒，机械能未必守恒","def":"碰撞过程系统动量总守恒；按机械能损失程度分为完全弹性、完全非弹性、一般非弹性三类。","fx":["完全弹性：动量、动能都守恒","完全非弹性：动量守恒，动能损失最大（碰后共速）","一般非弹性：动量守恒，动能部分损失"],"key":"除完全弹性碰撞外，机械能都不守恒——千万别默认碰撞动能守恒。"},
  "转动惯量J": {"dv":{"title":"转动惯量的定义与计算","steps":["把刚体分成许多质元，每个质元 mᵢ 离轴距离 rᵢ","类比平动动能 ½mv²，写出转动动能 ½(Σmᵢrᵢ²)ω²","令 J = Σmᵢrᵢ²，即得 Ek = ½Jω²","连续体用积分 J = ∫r² dm","J 与质量分布及转轴位置有关，故不同轴 J 不同"]},"tag":"刚体 · 4.2","sub":"刚体转动的「质量」","def":"转动惯量 J = Σmᵢrᵢ² = ∫r²dm 是刚体转动惯性的度量，取决于质量大小、分布以及转轴位置。","fx":["J = Σ mᵢ rᵢ² = ∫ r² dm","细棒（过中心）J = mL²/12","细棒（过端点）J = mL²/3","圆盘 J = ½ m R²"],"key":"同一个刚体对不同转轴 J 不同，先确认转轴再查表。"},
  "力矩M=Fd": {"dv":{"title":"力矩与力臂","steps":["力使刚体绕轴转动，效果由转轴到力作用线的距离决定","定义力臂 d 为转轴到力作用线的垂直距离","力矩大小 M = F·d","矢量形式 M = r × F，方向由右手螺旋定则确定","沿作用线平移力不改变力臂 d，故不改变力矩"]},"tag":"刚体 · 4.2","sub":"力使刚体转动的效果","def":"力矩 M = F·d，其中 d 是<b>力臂</b>——转轴到力作用线的垂直距离（不是到作用点的距离）。","fx":["M = F · d（d 为力臂）","矢量式 M = r × F"],"key":"力沿作用线平移不改变力矩；力臂用垂直距离是常见易错点。"},
  "M=Jα": {"dv":{"title":"转动定律的推导","steps":["对刚体上第 i 个质元，切向受力 Fᵢₜ = mᵢaᵢₜ = mᵢrᵢα","两端乘 rᵢ 得该质元力矩：Mᵢ = Fᵢₜ rᵢ = mᵢrᵢ²α","对所有质元求和：ΣMᵢ = (Σmᵢrᵢ²)α","内力矩成对抵消，ΣMᵢ 即合外力矩 M","故 M = Jα，与平动 F = ma 一一对应"]},"tag":"刚体 · 4.2","sub":"转动定律——转动的「F=ma」","def":"刚体所受合外力矩等于转动惯量与角加速度的乘积：M = Jα，与平动 F = ma 完全对应。","anim":"anim-rotate","cap":"力矩越大，角加速度 α 越大，M = Jα","fx":["M = J α","与平动类比：力↔力矩、质量↔J、a↔α"],"key":"求角加速度先算合力矩 M 与 J，再用 α = M/J。"},
  "角动量L=Jω": {"dv":{"title":"角动量与角动量守恒","steps":["类比平动量 p = mv，定义定轴转动的角动量 L = Jω","由 M = Jα = J dω/dt = d(Jω)/dt（J 不变时）","得角动量定理 M = dL/dt","当合外力矩 M = 0 时 dL/dt = 0","故 Jω = 常量，即角动量守恒（如花样滑冰收臂）"]},"tag":"刚体 · 4.3","sub":"转动的「动量」","def":"定轴转动刚体的角动量 L = Jω；角动量定理 M = dL/dt。当合外力矩为零时角动量守恒 Jω = 常量。","fx":["L = J ω","M = dL/dt","守恒：M = 0 ⟹ J ω = 常量"],"key":"花样滑冰收臂：J 变小 → ω 变大。角动量守恒常与动量守恒并列考查。"},
  "转动动能": {"dv":{"title":"转动动能与动能定理","steps":["刚体各质元速度 vᵢ = rᵢω，故 Ek = Σ½mᵢvᵢ²","代入 vᵢ：Ek = ½(Σmᵢrᵢ²)ω² = ½Jω²","由 M = Jα 与 dθ = ω dt，得做功 W = ∫M dθ","积分得 W = ½Jω₂² − ½Jω₁²","即转动动能定理，与平动 W = ½mv₂²−½mv₁² 对应"]},"tag":"刚体 · 4.4","sub":"转动的动能与动能定理","def":"刚体绕定轴转动的动能 Ek = ½Jω²；合外力矩做功等于转动动能的改变。","fx":["转动动能 E_k = ½ J ω²","转动动能定理 W = ∫M dθ = ½Jω₂² − ½Jω₁²"],"key":"与平动 ½mv² 一一对应；纯滚动时总动能 = 平动 + 转动。"},
  "平行轴定理": {"dv":{"title":"平行轴定理的推导","steps":["设过质心的轴转动惯量为 Jc，另取与之平行、相距 d 的轴","对新轴，每个质元坐标 rᵢ = rᵢ′ + d（矢量 d 对所有质元相同）","展开 J = Σmᵢ|rᵢ′+d|² = Σmᵢrᵢ′² + 2d·Σmᵢrᵢ′ + Σmᵢd²","质心系中 Σmᵢrᵢ′ = 0（质心定义），故中间项为零","于是 J = Jc + md²"]},"tag":"刚体 · 4.2","sub":"不同转轴间转动惯量的换算","def":"设刚体对过质心轴的转动惯量为 J_C，则对与之平行、相距 d 的轴：J = J_C + md²。","fx":["J = J_C + m d²"],"key":"用于把「过质心」的结论平移到其他平行轴，避免重复积分。"},
  "库仑定律": {"dv":{"title":"库仑定律的建立","steps":["用扭秤实验测出：F 与 q₁q₂ 成正比、与 r² 成反比","写成 F = kq₁q₂/r²，方向沿两电荷连线","用真空电容率表示常数 k = 1/(4πε₀)","得 F = q₁q₂/(4πε₀r²)","同号相斥、异号相吸；多个电荷用矢量叠加"]},"tag":"静电场 · 5.1","sub":"真空中点电荷间的相互作用力","def":"真空中两个静止点电荷间的作用力大小与电荷量乘积成正比、与距离平方成反比，方向沿连线，同号相斥、异号相吸。","fx":["F = (1/4πε₀) · q₁q₂ / r²","k = 1/4πε₀ ≈ 9×10⁹ N·m²/C²"],"key":"库仑力是矢量，多电荷时要用矢量叠加；计算大小时先判断符号再定方向。"},
  "E=F/q₀": {"dv":{"title":"电场强度的定义","steps":["为描述电场，在场中放一检验电荷 q₀","测量它受到的力 F","定义 E = F/q₀（矢量，方向为 q₀ 受力方向）","比值 E 与 q₀ 大小无关，说明它是场本身的性质","对点电荷，由库仑定律代入定义式得 E = q/(4πε₀r²)"]},"tag":"静电场 · 5.2","sub":"电场强度的定义式","def":"电场强度 E = F/q₀，等于单位正电荷在场中受的力，是场自身的属性，与检验电荷 q₀ 无关。","fx":["E = F / q₀ （定义式）","点电荷场 E = (1/4πε₀) q / r²"],"key":"定义式 E = F/q₀ 普遍适用；E 与 q₀ 无关是关键结论。"},
  "电通量": {"dv":{"title":"电通量的定义","steps":["在面上取面积元 dS，其法线方向为 n","通量定义为场强与面积元矢量的点积：dΦ = E·dS","用夹角表示 dΦ = E cosθ dS","整体 Φ = ∫E·dS","闭合曲面约定外法向为正，Φ = ∮E·dS"]},"tag":"静电场 · 5.3","sub":"穿过曲面的电场线数目","def":"通过面积元的电通量 dΦₑ = E·dS；整体 Φₑ = ∫E·dS。闭合曲面电通量 Φₑ = ∮E·dS，只看穿出/穿入的净效果。","fx":["dΦ = E · dS = E cosθ dS","闭合面 Φ = ∮ E · dS"],"key":"电通量是标量；一条场线穿出去、再穿进来对净通量贡献相反。"},
  "高斯定理": {"tag":"静电场 · 5.4","sub":"电通量由面内净电荷决定","def":"通过任意闭合曲面的电通量等于该面所包围的净电荷除以 ε₀，与面外电荷无关。","anim":"anim-gauss","cap":"穿出闭合面的电通量只由面内净电荷决定","fx":["∮ E · dS = Σq内 / ε₀"],"dv":{"title":"由点电荷推广到一般情形","steps":["取以 q 为球心、半径 r 的球面；对称性使 E 沿径向且大小相同","∮E·dS = E·4πr²","代入点电荷场 E = q/(4πε₀r²)，得 ∮E·dS = q/ε₀","由叠加原理推广为 ∮E·dS = Σq内/ε₀","面外电荷进出通量相消，故不贡献"]},"key":"只有高对称（球、柱、面）时才能用它求出 E 的大小。"},
  "环路定理": {"dv":{"title":"静电场是保守场","steps":["取任意闭合路径，把静电力做功分割为微元","静电力是中心力，单段做功与路径无关","沿闭合路径绕一圈，各段做功正负相消","故 ∮E·dl = 0，即场强环流为零","说明静电场是保守场，可引入电势能与电势"]},"tag":"静电场 · 5.5","sub":"静电场是保守场","def":"静电力做功与路径无关，场强沿任意闭合路径的线积分为零，说明静电场是保守场，也是引入电势的依据。","fx":["∮ E · dl = 0"],"key":"环路定理 ⟹ 可定义电势能与电势；这是静电场区别于非保守场的本质。"},
  "电偶极矩": {"dv":{"title":"电偶极矩与外场行为","steps":["电偶极子由 +q 与 −q 相距 l 组成","定义电偶极矩 p = q l，方向由负电荷指向正电荷","在匀强场中两电荷受力等大反向，合力为零但形成力偶矩","由两力力矩叠加得 M = p × E","当 p∥E 时 M = 0、势能最低，故偶极子趋于转向与 E 同向"]},"tag":"静电场 · 5.8","sub":"描述电偶极子的矢量","def":"等量异号电荷 +q、−q 相距 l 组成电偶极子，电偶极矩 p = ql，方向由负电荷指向正电荷。","fx":["p = q l （负→正）","匀强场中受力矩 M = p × E","电势能 W = − p · E"],"key":"外场中电偶极子会转到与 E 同向（能量最低）；此时受力矩而非净力。"},
  "静电平衡": {"dv":{"title":"静电平衡条件的推导","steps":["导体进入电场，自由电荷受力开始移动","电荷重新分布在表面产生附加场，直到内部处处抵消","平衡时导体内 E = 0，否则电荷还会继续移动","由 E = −∇V，内部 E = 0 说明导体内电势处处相等（等势体）","表面处 E 必须垂直于表面，否则切向分量会使电荷继续移动"]},"tag":"静电场中的导体和电介质 · 6.1","sub":"导体放入电场后的稳态","def":"导体放入电场后自由电荷重新分布，直到内部场强处处为零，称静电平衡。此时导体内部 E = 0，表面 E 垂直于表面，整个导体是等势体。","fx":["内部 E = 0","表面 E ⊥ 表面","导体是等势体，电荷只分布在外表面"],"key":"「内部 E = 0」是静电平衡的充要判据，是分析导体问题的出发点。"},
  "静电屏蔽": {"dv":{"title":"静电屏蔽的原理","steps":["静电平衡时导体内部 E = 0，整体是等势体","① 空腔导体罩住内部：外部变化被表面电荷的附加场抵消，腔内 E=0","② 接地空腔导体：腔内电荷的场使外表面感应电荷被地中和，外部 E=0","故空腔导体屏蔽外场，接地空腔导体屏蔽内场","屏蔽效果源于导体表面感应电荷的重新分布"]},"tag":"静电场中的导体和电介质 · 6.1","sub":"空腔导体的隔离作用","def":"空腔导体内部不受外部电场影响；若把空腔导体接地，还能屏蔽腔内电荷对外部场的影响。","key":"两种屏蔽方向不同：屏蔽外场→空腔导体；屏蔽内场→接地空腔导体。"},
  "电位移D": {"dv":{"title":"电位移矢量的引入","steps":["介质极化产生极化电荷 q′，使高斯定理含两类电荷","把 q′ 用极化强度表示：Σq′ = −∮P·dS","代入 ∮E·dS = (Σq₀+Σq′)/ε₀","整理得 ∮(ε₀E+P)·dS = Σq₀","定义 D = ε₀E + P，则 ∮D·dS = Σq₀，只数自由电荷"]},"tag":"静电场中的导体和电介质 · 6.2","sub":"引入介质后的辅助矢量","def":"电介质极化产生极化电荷，使问题复杂。引入电位移矢量 D = ε₀E + P 后，有介质的高斯定理只数自由电荷，形式简洁。","fx":["D = ε₀ E + P","线性介质 D = εE = ε₀ εᵣ E"],"key":"D 是为简化计算引入的辅助量，其通量只与自由电荷有关。"},
  "有介质高斯定理": {"tag":"静电场中的导体和电介质 · 6.2","sub":"只需数自由电荷","def":"在电介质中，穿过闭合曲面的电位移通量等于面内自由电荷的代数和：∮D·dS = Σq₀，比用电场 E 的形式更简便。","fx":["∮ D · dS = Σ q₀ （只数自由电荷）"],"dv":{"title":"为什么只数自由电荷","steps":["一般情形：∮E·dS = (Σq₀ + Σq′)/ε₀（自由电荷 + 极化电荷）","极化电荷可用极化强度表达：Σq′ = −∮P·dS","代入并移项：∮(ε₀E + P)·dS = Σq₀","定义 D = ε₀E + P，即得 ∮D·dS = Σq₀"]},"key":"算 E 用 E 的高斯定理（含束缚电荷），算 D 用 D 的高斯定理（只数自由电荷）。"},
  "电容C": {"tag":"静电场中的导体和电介质 · 6.3","sub":"储存电荷与电能的能力","def":"孤立导体电容 C = Q/V；平行板电容器 C = εS/d（含介质 C = ε₀εᵣS/d）。极板越大、间距越小、介质电容率越大，电容越大。","fig":"fig-capacitor","cap":"平行板间为匀强电场 E = V/d","fx":["孤立导体 C = Q / V","平行板 C = εS/d = ε₀εᵣS/d","串联 1/C = Σ1/Cᵢ ，并联 C = ΣCᵢ"],"dv":{"title":"平行板电容公式的推导","steps":["板间近似匀强电场（忽略边缘效应）","由高斯定理，场强 E = σ/ε = Q/(εS)","电势差 V = E·d = Qd/(εS)","代入定义 C = Q/V = εS/d"]},"key":"电容器串联电容变小、并联变大——与电阻规律正好相反。"},
  "电场能量密度": {"tag":"静电场中的导体和电介质 · 6.4","sub":"能量储存在电场中","def":"带电电容器储存能量 W = ½CV² = ½QV = Q²/2C；单位体积的电场能量（能量密度）w = ½εE²。","fx":["W = ½ C V² = ½ Q V = Q² / 2C","能量密度 w = ½ ε E²","总能量 W = ∫ w dV"],"dv":{"title":"能量密度公式的推导","steps":["充电时把电荷 dq 从一板搬到另一板，克服电压做功 dW = V′ dq","某时刻电量 q，电压 V′ = q/C，积分 W = ∫₀^Q (q/C)dq = Q²/(2C)","由 Q = CV 得 W = ½CV²","用 W/(Sd) 并代入 C = εS/d、E = V/d","得 w = ½ ε E²"]},"key":"能量密度 w = ½εE² 说明能量分布在场中，ε 需含介质。"},
  "存储程序": {"dv":{"title":"存储程序原理的意义","steps":["把程序（指令序列）和数据一起用二进制存入同一存储器","执行时 CPU 自动按地址顺序取指、译码、执行","无需人工改动硬件连线，只需更换存储器中的程序","这一思想使计算机成为通用机","由冯·诺依曼提出，是现代计算机的根本原理"]},"tag":"计算机系统概论 · 第1章","sub":"冯·诺依曼体系的核心思想","def":"把指令和数据都以二进制形式<b>预先存入存储器</b>，机器启动后自动、顺序地取指令并执行，无需人工干预。","fx":["程序与数据同等地位存放","指令 = 操作码 + 地址码","自动、顺序地取指执行"],"key":"这是「通用计算机」的前提：改程序只需改存储器内容，不必改硬件连线。"},
  "五大部件": {"dv":{"title":"五大部件与数据流","steps":["运算器：完成算术与逻辑运算","控制器：发出控制信号，指挥各部件协调工作","存储器：存放程序和数据","输入设备：把外部信息送入主机","输出设备：把结果送出；数据流为 输入→存储器→运算器→存储器→输出"]},"tag":"计算机系统概论 · 第1章","sub":"运算器/控制器/存储器/输入/输出","def":"冯·诺依曼机由五大部件构成，其中运算器与控制器合称中央处理器（CPU）。数据以二进制统一表示，指令与数据一同存于存储器。","fig":"fig-von","cap":"五大部件与数据流向","key":"数据流：输入→存储器→运算器→存储器→输出；控制器负责指挥，运算器负责加工。"},
  "冯·诺依曼": {"dv":{"title":"冯·诺依曼机的特征","steps":["以存储程序为基本思想","指令和数据都用二进制表示，一同存放","由五大部件组成，运算器与控制器合称 CPU","指令由操作码和地址码构成，按地址顺序执行","原始机器以运算器为中心，现代机改以存储器为中心并引入总线"]},"tag":"计算机系统概论 · 第1章","sub":"存储程序式计算机","def":"以「存储程序」为原理的计算机结构，由五大部件组成，指令和数据以二进制统一存放。","key":"原始冯·诺依曼机以运算器为中心；现代机器改以存储器为中心，并引入总线。"},
  "层次结构": {"dv":{"title":"计算机系统的多级层次","steps":["按功能从低到高划分为多级：微程序级→机器语言级→操作系统级→汇编语言级→高级语言级","每一级向上提供更抽象、更易用的接口","下层的实现细节对上层透明","体现软硬件逻辑等价：同一功能可由硬件或软件实现","层次化降低了设计与使用的复杂度"]},"tag":"计算机系统概论 · 第1章","sub":"计算机系统的多级层次","def":"计算机系统可按软硬件分为多级：微程序机器级 → 机器语言级 → 操作系统级 → 汇编语言级 → 高级语言级，自下而上逐层抽象。","fx":["硬件/软件在逻辑上等价","每一层向上提供更易用的接口"],"key":"层次结构体现「软硬件逻辑等价」思想：同一个功能可由硬件或软件实现。"},
  "机器字长": {"dv":{"title":"机器字长的含义","steps":["字长指 CPU 一次能并行处理的二进制位数","它通常等于通用寄存器的位数和数据总线宽度","字长越大，运算精度越高、一次能处理的信息越多","字长也影响寻址，与地址总线共同决定能访问的空间","注意字长不等于存储容量，后者等于单元数×单元位数"]},"tag":"计算机系统概论 · 第1章","sub":"CPU 一次能处理的二进制位数","def":"机器字长是 CPU 一次能并行处理的二进制位数，通常等于通用寄存器与数据总线的宽度。","fx":["机器字长 = CPU 一次处理位数","字长 ↑ → 精度与寻址能力 ↑"],"key":"字长是硬件指标，与「存储容量（单元数×位数）」是两个概念，别混。"},
  "存储容量": {"dv":{"title":"存储容量的计算","steps":["容量 = 存储单元数 × 每个单元的位数","若给出 64K×16位，表示 64×1024 个单元、每单元 16 位","按字节表示须除以 8：64×1024×16b = 128KB","注意 K、M、G 按 1024 进制（1K = 1024）","单位统一是这类计算的关键"]},"tag":"计算机系统概论 · 第1章","sub":"主存可存二进制信息总量","def":"存储容量 = 存储单元数 × 每单元位数，常以字节（B）为单位。","fx":["容量 = 单元数 × 每单元位数","1 B = 8 b","64K×16b = 64×1024×16b = 128KB"],"key":"计算先统一单位（位→字节 ÷8），注意 K = 1024 而非 1000。"},
  "四代计算机": {"dv":{"title":"四代计算机的划分","steps":["第一代：电子管，体积大、功耗高、速度低","第二代：晶体管，可靠性提高、体积减小","第三代：中小规模集成电路，出现操作系统","第四代：大规模/超大规模集成电路，微处理器诞生","划分依据是所用逻辑元件（硬件）的变革"]},"tag":"计算机的发展及应用 · 第2章","sub":"按逻辑元件划分的四代","def":"第一代电子管、第二代晶体管、第三代中小规模集成电路、第四代大规模/超大规模集成电路。每代逻辑元件与软件都发生跃变。","key":"划分依据是逻辑元件（硬件），不是软件或应用领域。"},
  "摩尔定律": {"dv":{"title":"摩尔定律的内容","steps":["观察发现：集成电路上晶体管数目约每 18~24 个月翻一番","由此性能与性价比按指数增长","它是经验规律，不是物理定律","近年来受工艺极限影响，增速已放缓","它解释了计算机硬件快速更新换代的原因"]},"tag":"计算机的发展及应用 · 第2章","sub":"集成电路集成度规律","def":"集成电路上可容纳的晶体管数目约每 18~24 个月翻一番，反映硬件性能快速增长的规律。","key":"摩尔定律是经验规律而非物理定律，近年来增速已放缓。"},
  "应用领域": {"dv":{"title":"计算机的应用领域","steps":["科学计算：最早、最经典的应用（数值求解）","数据处理与信息管理：数据库、办公自动化","过程控制：工业实时控制","CAD/CAM/CAI：计算机辅助设计、制造、教学","人工智能与网络通信：智能算法与互联网"]},"tag":"计算机的发展及应用 · 第2章","sub":"从科学计算到多领域","def":"计算机应用从最初的科学计算，扩展到数据处理、过程控制、计算机辅助设计/制造（CAD/CAM）、人工智能、网络通信等领域。","key":"应用领域与硬件发展相互驱动，是理解「为什么而设计」的背景。"},
  "巨型化/微型化": {"dv":{"title":"计算机的两个发展方向","steps":["巨型化：追求高速度、大容量、大规模并行，用于气象、科研","微型化：追求体积小、功耗低、成本低，渗透到生活各处","二者并不矛盾，是不同需求的并行发展","此外还有多媒体化、网络化趋势","共同刻画了计算机发展的整体方向"]},"tag":"计算机的发展及应用 · 第2章","sub":"两个发展方向","def":"计算机朝两个方向发展：巨型化（高速度、大容量、大规模并行，用于科研与气象）与微型化（体积小、功耗低，渗透到生活各方面）。","key":"同时还有网络化与多媒体化趋势，共同刻画发展方向。"},
  "智能化": {"dv":{"title":"智能化的发展趋势","steps":["让计算机模拟人的智能行为","包括机器学习、模式识别、自然语言处理、专家系统等","是当前发展最活跃的方向","与人工智能技术紧密相关","代表从计算向认知的演进"]},"tag":"计算机的发展及应用 · 第2章","sub":"向人工智能方向演进","def":"计算机向模拟人类智能的方向发展，如机器学习、模式识别、自然语言处理，即「智能化」趋势。","key":"智能化是当前最活跃的发展方向，与人工智能紧密相关。"},
  "数据/地址/控制总线": {"dv":{"title":"三类总线的功能","steps":["数据总线：传送数据，双向，宽度决定一次能传多少位","地址总线：传送地址，单向（CPU 发出），宽度 n 决定寻址空间 2ⁿ","控制总线：传送控制与状态信号，有出有入","三者在同一总线上按时分复用协调工作","总线是连接各部件的信息传输线"]},"tag":"系统总线 · 第3章","sub":"按功能划分的三类总线","def":"总线按传输信息类型分为：数据总线（传数据，双向）、地址总线（传地址，单向，决定寻址空间）、控制总线（传控制信号，双向/单向）。","fig":"fig-bus","cap":"三总线结构与信息流向","key":"地址总线宽度 n 决定最大寻址空间 2ⁿ；数据总线宽度决定一次能传多少位。"},
  "总线带宽": {"dv":{"title":"总线带宽的计算","steps":["带宽指单位时间传输的数据量","每个时钟周期传送若干字节，乘以频率即每秒字节数","带宽 = 工作频率 × 每周期传输字节数","例：66MHz × 4B = 264MB/s","带宽由频率与数据线宽度共同决定"]},"tag":"系统总线 · 第3章","sub":"单位时间传输的数据量","def":"总线带宽 = 总线工作频率 × 每个时钟周期传输的字节数，单位 B/s，衡量总线数据传输能力。","fx":["带宽 = 工作频率 × 每周期传输字节数","例：66MHz × 4B = 264MB/s"],"key":"带宽取决于频率和数据线宽度，二者缺一不可。"},
  "寻址空间2ⁿ": {"dv":{"title":"寻址空间的计算","steps":["地址总线有 n 根，每根可取 0 或 1","n 根线可组合出 2ⁿ 个不同的地址编码","每个编码对应一个存储单元","故最大寻址单元数 = 2ⁿ","例：n=20 时 2²⁰ = 1M 个单元；与数据线宽度无关"]},"tag":"系统总线 · 第3章","sub":"地址总线宽度决定寻址范围","def":"若地址总线有 n 根，则最多可编码 2ⁿ 个不同地址，即最大寻址空间为 2ⁿ 个存储单元。","fx":["寻址单元数 = 2ⁿ（n 为地址线数）","例：n=20 → 1M 个单元"],"key":"寻址空间只由地址线宽度决定，与数据线宽度无关。"},
  "总线仲裁": {"dv":{"title":"总线仲裁的必要性","steps":["多个主设备（CPU、DMA、协处理器）都可能请求总线","同一时刻只能有一个主设备占用，否则发生冲突","需由仲裁机构判定请求优先级并授权占用","集中式：链式查询、计数器定时查询、独立请求","分布式：各设备自行协商；核心是决定谁先用总线"]},"tag":"系统总线 · 第3章","sub":"多个主设备争用总线的裁决","def":"当多个主设备（CPU、DMA 等）同时请求占用总线时，需由总线仲裁决定谁先使用，常见集中式（链式查询、计数器定时、独立请求）与分布式两类。","key":"仲裁解决「谁先用总线」，是总线共享的核心机制。"},
  "同步vs异步": {"dv":{"title":"同步与异步通信","steps":["同步通信：所有设备由统一时钟节拍控制，按固定周期传送","优点：协议简单、速度快；缺点：必须迁就最慢的设备","异步通信：采用请求—应答（握手）方式，无统一时钟","优点：不同速度设备都能兼容；缺点：协议开销大、速度受限","设备速度差异大时选异步，速度相近时选同步"]},"tag":"系统总线 · 第3章","sub":"两种通信（定时）方式","def":"同步通信由统一时钟节拍控制，速度快、依赖最慢设备；异步通信采用应答（握手）方式，不同速度设备可兼容，但协议开销大。","key":"同步靠时钟、异步靠握手；设备速度差异大时选异步。"},
  "局部性原理": {"dv":{"title":"程序访问的局部性","steps":["时间局部性：刚访问过的信息很可能很快又会被访问","空间局部性：某地址被访问后，其邻近地址很可能被访问","原因：程序多为顺序执行、循环与数组访问","局部性使「Cache + 主存」层次结构高效","它是 Cache 存在的理论基础"]},"tag":"存储器 · 第4章","sub":"Cache 存在的理论基础","def":"程序访问存储时在时间和空间上具有局部性：时间局部性指刚被访问的信息很可能再次被访问；空间局部性指邻近地址的信息很可能将被访问。","key":"正是局部性使「高速小容量 Cache + 低速大容量主存」的层次结构高效。"},
  "SRAM/DRAM": {"dv":{"title":"SRAM 与 DRAM 的区别","steps":["SRAM 用触发器（双稳态电路）存储，只要供电数据就不丢","因此速度快、不需刷新，但单元大、集成度低、成本高","DRAM 用电容存电荷表示信息","电容会漏电，需定时刷新，故速度慢，但单元小、集成度高","所以 SRAM 作 Cache，DRAM 作主存"]},"tag":"存储器 · 第4章","sub":"两种半导体存储器","def":"SRAM 用触发器存储、速度快、功耗大、集成度低，用作 Cache；DRAM 用电容存储、需定时刷新、速度慢、集成度高，用作主存。","fx":["SRAM：触发器，快、贵、不需刷新","DRAM：电容，慢、廉、需刷新"],"key":"DRAM 需要刷新是因为电容会漏电，这是它区别于 SRAM 的关键。"},
  "Cache映射": {"dv":{"title":"三种地址映射方式","steps":["直接映射：主存块只能放入固定的 Cache 行，硬件简单但冲突多","全相联：主存块可放任意行，灵活但需与所有行比较，成本高","组相联：把 Cache 分组，块映射到固定组、组内任意，折中","组相联兼顾速度与命中率，实际系统最常用","映射方式决定地址如何划分（标记、组号、块内地址）"]},"tag":"存储器 · 第4章","sub":"主存块如何放入 Cache","def":"地址映射有三种：直接映射（一个主存块只能放固定行，简单但冲突多）、全相联（可放任意行，灵活但比较器多）、组相联（折中，最常用）。","fig":"fig-cache","cap":"存储层次与命中/未命中","key":"组相联是直接映射与全相联的折中，实际系统最常用。"},
  "LRU": {"dv":{"title":"LRU 替换算法","steps":["当 Cache 满且未命中时，需选择一行淘汰","LRU 选择最久未被访问的行淘汰","依据是时间局部性：很久没用的信息大概率不会再马上用","需要记录各行的访问历史，硬件实现较复杂","相比 FIFO（淘汰最早进入的），LRU 命中率通常更高"]},"tag":"存储器 · 第4章","sub":"最近最少使用替换算法","def":"LRU（Least Recently Used）每次淘汰最久未被访问的行，符合时间局部性，命中率较高但需要记录访问历史，硬件实现较复杂。","fx":["LRU：淘汰最久未用的块","对比 FIFO：淘汰最先进入的块"],"key":"LRU 依据时间局部性；FIFO 可能淘汰常用块，故 LRU 通常更优。"},
  "磁盘容量": {"dv":{"title":"磁盘容量的计算","steps":["盘面按磁道划分，磁道再分为扇区","容量 = 盘面数 × 每面磁道数 × 每道扇区数 × 每扇区字节数","格式化会占用部分空间，格式化容量约为非格式化容量的 80%","存取时间 = 寻道时间 + 旋转等待时间 + 传输时间","其中寻道时间通常最长，是主要瓶颈"]},"tag":"存储器 · 第4章","sub":"磁盘的存储总量","def":"非格式化容量 = 面数 × 每面磁道数 × 每道扇区数 × 每扇区字节数；格式化容量约为非格式化容量的 80%。","fx":["容量 = 盘面数 × 道数 × 扇区数 × 扇区字节数","存取时间 = 寻道时间 + 旋转等待 + 传输时间"],"key":"存取时间的三段中，寻道时间通常最长，是性能瓶颈。"},
  "I/O接口": {"dv":{"title":"I/O 接口的作用","steps":["外设与主机在速度、数据格式、电平等方面差异巨大","接口完成数据缓冲，解决速度不匹配","完成数据格式转换与电平匹配","完成地址译码，选中相应外设","传递控制命令与状态信息，并支持中断/DMA 联络"]},"tag":"输入输出系统 · 第5章","sub":"主机与外设之间的桥梁","def":"I/O 接口用来连接主机与外部设备，实现数据缓冲、格式转换、地址译码、状态与命令传递，是两者之间速度与格式的协调器。","fx":["接口功能：缓冲、转换、译码、联络、中断"],"key":"接口存在的根本原因是外设与主机在速度、格式上差异巨大。"},
  "程序查询": {"dv":{"title":"程序查询方式","steps":["CPU 通过循环读取外设状态寄存器判断是否就绪","若未就绪则继续查询，就绪后传送数据","外设与 CPU 串行工作，CPU 大量时间在空等","实现最简单，不需额外硬件","效率最低，只适合外设速度接近 CPU 的场合"]},"tag":"输入输出系统 · 第5章","sub":"最简单的 I/O 方式","def":"CPU 不断查询外设状态寄存器，直到外设就绪才传送数据。实现简单，但 CPU 长时间空等、效率极低。","key":"程序查询的最大缺点是 CPU 与外设串行工作，白等时间多。"},
  "中断方式": {"dv":{"title":"中断方式的工作过程","steps":["外设准备好后主动向 CPU 发中断请求","CPU 在一条指令执行完、且允许中断时响应","暂停当前程序，保护现场（保存 PC 和寄存器）","转去执行中断服务程序完成数据传送","服务完毕恢复现场并返回原程序；实现 CPU 与外设并行"]},"tag":"输入输出系统 · 第5章","sub":"外设主动通知 CPU","def":"外设准备好后向 CPU 发中断请求，CPU 暂停当前程序，转去执行中断服务程序传数据，之后返回。实现 CPU 与外设并行工作。","fx":["中断响应条件：有请求 + 允许中断 + 一条指令结束"],"key":"中断实现了 CPU 与外设并行，效率高于程序查询；核心是保护现场与恢复现场。"},
  "DMA": {"dv":{"title":"DMA 方式的特点","steps":["数据直接在内存与外设之间传送，不经过 CPU","传送前 CPU 设置好起始地址、数据长度和传送方向","DMA 控制器接管总线完成整块数据传送","传送结束时以中断通知 CPU","适合高速、大批量数据传送，如磁盘、显卡"]},"tag":"输入输出系统 · 第5章","sub":"直接存储器存取","def":"DMA 方式下数据直接在内存与外设间传送，不经过 CPU，CPU 只在传送开始和结束时介入，适合高速大批量数据传送。","fx":["数据不经过 CPU，直接 外设 ↔ 内存"],"key":"DMA 与中断配合：DMA 处理数据块传送，中断报告块传送结束。"},
  "周期挪用": {"dv":{"title":"周期挪用（周期窃取）","steps":["DMA 与 CPU 都要访问存储器，需要协调","方案之一：DMA 申请占用一个（或几个）存储周期","CPU 暂停一个周期、让出总线给 DMA 使用","传送一个数据后 CPU 继续访存","对 CPU 影响较小，是常见的折中方案"]},"tag":"输入输出系统 · 第5章","sub":"DMA 抢占存储周期的方式","def":"DMA 与 CPU 争用存储器时，常采用周期挪用：DMA 申请占用一个存储周期，CPU 暂停一个周期让出总线。这种方式对 CPU 影响较小。","key":"周期挪用是 DMA 与 CPU 共享内存的典型策略，另有停止 CPU 访存、交替访存等。"},
  "原码反码补码": {"dv":{"title":"三种机器数的关系","steps":["原码：最高位为符号位，其余为真值绝对值","反码：正数同原码；负数除符号位外按位取反","补码：正数同原码；负数在反码基础上末位加一","补码把减法统一成加法，符号位可直接参与运算","故现代计算机用补码表示带符号整数"]},"tag":"计算机的运算方法 · 第6章","sub":"带符号数的三种机器数","def":"原码：符号位 + 绝对值；反码：负数按位取反（符号位除外）；补码：负数按位取反再加一（正数与原码相同）。计算机用补码做加减。","fx":["原码：符号位 + 真值绝对值","反码：负数除符号位外取反","补码：负数取反加一；正数同原码"],"key":"补码把减法统一为加法，简化了运算器设计，是现代计算机的标准表示。"},
  "移码": {"dv":{"title":"移码的用途与求法","steps":["移码 = 真值 + 偏移量（常取 2ⁿ⁻¹）","也可以在补码基础上把符号位取反得到移码","这样按无符号比较两数大小，就等于比较真值大小","便于浮点数阶码的大小比较","IEEE 754 的阶码即采用移码"]},"tag":"计算机的运算方法 · 第6章","sub":"用于比较大小的表示","def":"移码 = 真值 + 偏移量（常取 2ⁿ⁻¹），其符号位与数值大小一致，便于用无符号加法器比较两个数的大小。常用于浮点数的阶码。","fx":["移码 = 补码的符号位取反","[x]移 = x + 2^(n-1)"],"key":"IEEE 754 的阶码用移码，好处是比较阶码大小只需按无符号比较。"},
  "取反加一": {"tag":"计算机的运算方法 · 第6章","sub":"负数补码的求法","def":"求负数补码：把该数绝对值按位取反，再在最低位加一，即得补码。","fig":"fig-adder","cap":"补码加减：符号位参与运算，末位进位舍去","dv":{"title":"为什么「取反加一」能得到补码","steps":["对 n 位数，补码定义为 [x]补 = 2ⁿ + x（x 为负数）","2ⁿ 写成 n 位就是 1 后跟 n 个 0","2ⁿ + x = (2ⁿ − 1) + x + 1","2ⁿ − 1 是 n 个 1，等于对 x 各位取反","所以「取反加一」就是 2ⁿ + x，即补码"]},"key":"「取反加一」是补码的快速算法，本质是 2ⁿ 加负数。"},
  "IEEE754": {"dv":{"title":"IEEE 754 单精度格式","steps":["32 位分为：1 位符号 S、8 位阶码 E、23 位尾数 M","真值 = (−1)^S × 1.M × 2^(E−127)","阶码用移码，偏置为 127","尾数把最高位 1 隐去（隐含 1），故实际多一位精度","这解释了为什么尾数只存小数部分"]},"tag":"计算机的运算方法 · 第6章","sub":"浮点数的国际标准","def":"IEEE 754 中 32 位单精度浮点数格式：1 位符号位 S + 8 位阶码 E（移码，偏置 127）+ 23 位尾数 M（隐含最高位 1）。","fx":["值 = (−1)^S × 1.M × 2^(E−127)","阶码偏置 = 127（单精度）"],"key":"尾数隐含最高位 1，可多存一位精度；阶码用移码便于比较。"},
  "双符号位溢出": {"dv":{"title":"用两位符号位判溢出","steps":["用两位符号位表示：00 为正、11 为负（变形补码）","两个同号数相加，结果符号位可能出现 01 或 10","01 表示正溢出（结果超过最大正数）","10 表示负溢出","若两位符号位仍相同则无溢出；此法比单看最后进位更可靠"]},"tag":"计算机的运算方法 · 第6章","sub":"判断溢出的方法","def":"用两位符号位（变形补码）表示数：00 为正、11 为负。运算后若两位符号位为 01 表示正溢，10 表示负溢。","fx":["00 正 / 11 负（正常）","01 正溢；10 负溢"],"key":"进位与溢出不是一回事：最高位进位不一定溢出，要看两位符号位是否相同。"},
  "先行进位": {"dv":{"title":"先行进位的原理","steps":["并行加法器的瓶颈在于进位需从低位逐级传递","对第 i 位定义生成 Gᵢ = AᵢBᵢ、传递 Pᵢ = Aᵢ⊕Bᵢ","本位产生进位的条件是：本位两数都为 1（生成），或本位和为 1 且低位有进位（传递）","故 Cᵢ₊₁ = Gᵢ + PᵢCᵢ","由 P、G 可直接算出各级进位，不必逐级等待，从而提速（空间换时间）"]},"tag":"计算机的运算方法 · 第6章","sub":"加快加法器速度","def":"并行加法器的进位延迟是瓶颈。先行进位（CLA）通过进位生成函数 G 与传递函数 P 直接算出各级进位，无需逐级传递，大幅提速。","fx":["生成 G = A·B ，传递 P = A⊕B","C(i+1) = G(i) + P(i)·C(i)"],"key":"先行进位用「空间换时间」，是高速加法器的核心思想。"},
  "操作码+地址码": {"dv":{"title":"指令的基本格式","steps":["一条指令由操作码和地址码两部分组成","操作码 OP 指明要执行的操作","地址码 A 指明操作数或操作数的地址","操作码位数决定指令种类：n 位最多 2ⁿ 种操作","地址码位数决定直接寻址的范围"]},"tag":"指令系统 · 第7章","sub":"指令的基本格式","def":"一条指令由操作码和地址码组成：操作码指明做什么操作，地址码指明操作数（或其地址）在哪里。","fx":["指令 = 操作码 OP + 地址码 A"],"key":"操作码位数决定指令种类数（n 位最多 2ⁿ 种），地址码位数决定寻址范围。"},
  "扩展操作码": {"dv":{"title":"扩展操作码的编码","steps":["指令字长固定，要在其中安排尽可能多的指令","常用指令给较长地址码，不常用指令缩短地址码","操作码长度随地址码个数的减少而增加","如 4 位操作码可表示 15 条三地址指令，剩余编码再扩展","关键是编码不冲突：短操作码不能是长操作码的前缀"]},"tag":"指令系统 · 第7章","sub":"在有限位数内安排更多指令","def":"为在固定字长内既保证常用指令有长地址码、又增加指令条数，采用扩展操作码：操作码随地址码数量变化而变长/变短。","key":"关键是各条指令的编码不能冲突：短操作码不能是长操作码的前缀。"},
  "寻址方式": {"dv":{"title":"寻址方式概览","steps":["寻址方式解决「操作数在哪里」","立即：操作数在指令中；直接：地址码即操作数地址","间接：地址码指向的是操作数地址的地址","寄存器：操作数在寄存器中；基址/变址 EA = 寄存器 + 形式地址","核心差别是访存次数与寻址范围"]},"tag":"指令系统 · 第7章","sub":"确定操作数地址的方法","def":"寻址方式指指令如何得到操作数的有效地址，常见有立即、直接、间接、寄存器、基址、变址、相对等，不同方式影响访存次数与寻址范围。","fig":"fig-addressing","cap":"不同寻址方式的操作数位置与访存次数","key":"寻址方式的核心差别是「操作数在哪」和「要访存几次」。"},
  "立即/直接/间接": {"dv":{"title":"三种寻址的访存次数","steps":["立即寻址：操作数直接写在指令中，取指即取到操作数，访存 0 次","直接寻址：指令给出操作数地址，需访存取数，访存 1 次","间接寻址：指令给出的地址所存放的仍是地址，需两次访存","故访存次数：立即 0 < 直接 1 < 间接 2","访存越多越慢，但间接寻址的范围更大"]},"tag":"指令系统 · 第7章","sub":"三种基础寻址方式","def":"立即寻址：操作数直接写在指令中，访存 0 次；直接寻址：地址码给出操作数地址，访存 1 次；间接寻址：地址码给出的是操作数地址的地址，访存 2 次。","fx":["立即：访存 0 次","直接：访存 1 次","间接：访存 2 次"],"key":"访存次数越多速度越慢，但寻址范围和灵活性通常更大。"},
  "基址变址": {"dv":{"title":"基址与变址寻址","steps":["基址寻址：EA = (基址寄存器) + 形式地址 A","基址寄存器内容由操作系统设定，用于程序整体重定位","变址寻址：EA = (变址寄存器) + 形式地址 A","变址寄存器内容可由用户改变，用于数组元素遍历","两者结合即基址变址：EA = (基址) + (变址) + A"]},"tag":"指令系统 · 第7章","sub":"面向数组与程序的寻址","def":"基址寻址：有效地址 = 基址寄存器 + 形式地址，便于程序重定位；变址寻址：有效地址 = 变址寄存器 + 形式地址，便于数组遍历。两者结合即基址变址寻址。","fx":["基址：EA = (基址寄存器) + A","变址：EA = (变址寄存器) + A"],"key":"基址面向「整个程序搬移」，变址面向「数组逐个访问」，用途不同。"},
  "RISC/CISC": {"dv":{"title":"RISC 与 CISC 对比","steps":["CISC：指令多且复杂，一条指令完成较多功能，变长编码","CISC 寻址方式多，控制复杂，难以流水","RISC：指令少而规整、定长、寻址方式少","RISC 采用 Load/Store 结构，只有取数/存数访存，便于流水线","用「简单指令 + 流水线」换取高主频与高吞吐，是主流方向"]},"tag":"指令系统 · 第7章","sub":"两种指令系统风格","def":"CISC（复杂指令集）指令多而复杂、一条指令可完成较多工作；RISC（精简指令集）指令少而规整、定长、多寄存器、便于流水线。","fx":["CISC：指令多、变长、寻址方式多","RISC：指令少、定长、Load/Store、易流水"],"key":"RISC 用「简单指令 + 流水线」换取高主频与高吞吐，是现代主流方向。"},
  "逻辑结构": {"dv":{"title":"四种逻辑结构","steps":["逻辑结构指数据元素之间的抽象关系，与存储无关","集合：元素之间除同属一个集合外无其他关系","线性结构：一对一（如线性表、栈、队列）","树形结构：一对多（如树、二叉树）","图状结构：多对多（如网、图）"]},"tag":"绪论 · 第1章","sub":"数据元素之间的逻辑关系","def":"逻辑结构描述数据元素之间的抽象关系，独立于计算机，分为集合、线性、树形、图状四类。","key":"逻辑结构与存储无关；同一逻辑结构可用不同存储结构实现。"},
  "存储结构": {"dv":{"title":"两种存储结构","steps":["存储结构是逻辑结构在计算机中的表示（物理结构）","顺序存储：用一组连续单元存放，靠存储位置表示关系","链式存储：用指针表示元素间关系，结点可分片存放","顺序存储支持随机存取，但插入删除需移动元素","链式存储插入删除方便，但需额外指针空间"]},"tag":"绪论 · 第1章","sub":"逻辑结构在计算机中的表示","def":"存储结构（物理结构）是逻辑结构在计算机中的实现，主要有顺序存储和链式存储两种。","fx":["顺序存储：用一组连续单元，靠位置关系","链式存储：用指针表示关系，靠指针"],"key":"存储结构决定算法的时间与空间效率；顺序与链式各有取舍。"},
  "ADT": {"dv":{"title":"抽象数据类型的含义","steps":["ADT = 一个数学模型 + 定义在该模型上的一组操作","只规定做什么（操作的功能与约束）","不规定怎么做（具体实现）","体现接口与实现分离的原则","便于数据封装与复用，是数据结构设计的基础"]},"tag":"绪论 · 第1章","sub":"抽象数据类型","def":"ADT（Abstract Data Type）指一个数学模型及定义在其上的一组操作，只关心「做什么」，不关心「怎么做」。","key":"ADT 强调接口与实现分离，是数据结构设计的基本思想。"},
  "时间复杂度": {"dv":{"title":"时间复杂度的分析","steps":["统计算法中基本操作的执行次数，表示为规模 n 的函数 T(n)","只关注随 n 增长的量级，忽略常数因子和低阶项","用渐进记号 O 表示其数量级","与具体机器无关，是衡量算法效率的标准","分析时抓最深层循环或递归的次数"]},"tag":"绪论 · 第1章","sub":"算法执行时间随规模的增长","def":"时间复杂度分析算法执行时间随问题规模 n 的增长趋势，是衡量算法效率的核心指标，与机器无关。","fx":["关注基本操作的执行次数","以 n 的增长率衡量，忽略常数与低阶项"],"key":"只抓「随 n 增长的量级」，这才是算法优劣的本质。"},
  "大O记号": {"dv":{"title":"O 记号的定义","steps":["渐进上界：若存在正常数 c 和 n₀，使 n ≥ n₀ 时恒有 T(n) ≤ c·f(n)","则记 T(n) = O(f(n))","它刻画 n 充分大时 T(n) 的增长不超过 f(n) 的常数倍","常见量级：O(1) < O(log n) < O(n) < O(n log n) < O(n²) < O(2ⁿ)","比较算法优劣即比较其量级"]},"tag":"绪论 · 第1章","sub":"渐进上界的记号","def":"O 记号表示渐进上界：若存在常数 c、n₀ 使当 n ≥ n₀ 时 T(n) ≤ c·f(n)，则记 T(n) = O(f(n))。","fx":["常用量级：O(1) < O(log n) < O(n) < O(n log n) < O(n²) < O(2ⁿ)"],"key":"常见量级要背下来，比较算法快慢时直接看它落在哪一档。"},
  "线性表": {"dv":{"title":"线性表的定义","steps":["线性表是 n 个数据元素的有限序列","除首尾外，每个元素有且仅有一个直接前驱和一个直接后继","元素之间是一对一的线性关系","两种实现：顺序表（数组）与链表","选择实现取决于插入删除与查找的频度"]},"tag":"线性表 · 第2章","sub":"最基础的线性结构","def":"线性表是 n 个数据元素的有限序列，元素之间是一对一的线性关系，有唯一的首元素和尾元素。","key":"线性表有两种实现：顺序表（数组）和链表，性质与代价不同。"},
  "顺序表O(1)": {"dv":{"title":"顺序表随机存取的由来","steps":["顺序表元素连续存放，设起始地址为 L、元素大小为 c","第 i 个元素的地址 = L + (i−1)c","由下标经一次乘法加法即可算出地址，故按位访问 O(1)","插入需把后面的元素整体后移，平均移动 n/2 个，O(n)","删除同理需前移，故「查快改慢」"]},"tag":"线性表 · 第2章","sub":"随机存取的数组实现","def":"顺序表用一组连续单元依次存放元素，地址连续；因此按下标访问是 O(1)，即随机存取。","fx":["按位查找 O(1)","插入/删除平均需移动 n/2 个元素，O(n)"],"key":"顺序表「查得快、插入删除慢」，因为要保持物理连续。"},
  "单链表": {"dv":{"title":"单链表的存取特点","steps":["每个结点含数据域和指针域，指针指向后继结点","结点物理上不连续，逻辑相邻靠指针连接","要访问第 i 个元素必须从头逐个走，故按位查找 O(n)","已知某结点的前驱指针时，插入/删除只需改指针，O(1)","故「查慢改快」"]},"tag":"线性表 · 第2章","sub":"用指针链接的线性表","def":"单链表每个结点含数据域和指针域，指针指向后继结点。逻辑上相邻的元素物理上不一定相邻。","fx":["按位查找 O(n)（顺序查找）","已知前驱时插入/删除 O(1)"],"key":"链表「插入删除快、查找慢」，适合频繁插入删除的场景。"},
  "头结点": {"dv":{"title":"头结点的作用","steps":["头结点是附在首元素前的额外结点，不存有效数据","它的存在使空表和非空表的处理统一","插入/删除首元素时，其前驱就是头结点","无需对操作第一个结点单独判断，简化边界处理","也统一了插入删除的指针修改逻辑"]},"tag":"线性表 · 第2章","sub":"简化链表操作的哨兵","def":"头结点是附设在链表首元素之前的额外结点，其数据域通常不存数据。引入头结点后，对首元素的操作与对一般结点一致，简化了插入删除的边界处理。","key":"头结点让「在表头插入/删除」无需特判，是链表实现的常用技巧。"},
  "链表反转": {"dv":{"title":"三指针反转的流程","steps":["设 prev=NULL、cur=head","循环：先保存 next=cur->next，防止断链","令 cur->next=prev，完成当前结点反向","prev=cur，cur=next，前移两个指针","当 cur=NULL 时结束，prev 即新表头；时间 O(n)，空间 O(1)"]},"tag":"线性表 · 第2章","sub":"就地反转单链表","def":"用三个指针 prev、cur、next 依次遍历，把每个结点的指针反向，直到 cur 为空，最后 prev 即为新表头。","anim":"anim-list","cap":"三指针逐步把箭头反向","fx":["时间 O(n)，空间 O(1)（就地）"],"key":"核心是保存 next 再改指针，避免断链；这是链表指针操作的经典练习。"},
  "LIFO": {"dv":{"title":"栈的后进先出","steps":["栈只能在栈顶一端插入和删除","最后入栈的元素最先出栈（LIFO）","用栈顶指针 top 指示栈顶位置","顺序栈判满 top==M−1，链栈则动态分配","函数调用、表达式求值、递归都用栈"]},"tag":"栈和队列 · 第3章","sub":"栈的后进先出特性","def":"栈是只允许在一端（栈顶）插入和删除的线性表，遵循后进先出（Last In First Out）。","fx":["push 入栈、pop 出栈均在栈顶","顺序栈/链栈均可实现"],"key":"栈的应用极广：函数调用、表达式求值、括号匹配、递归、回溯。"},
  "FIFO": {"dv":{"title":"队列的先进先出","steps":["队列一端（队尾）插入、另一端（队头）删除","最先入队的元素最先出队（FIFO）","用队头指针 front 和队尾指针 rear 管理","顺序队列存在假溢出，需用循环队列解决","BFS、任务调度、缓冲区都用队列"]},"tag":"栈和队列 · 第3章","sub":"队列的先进先出特性","def":"队列只允许在一端（队尾）插入、另一端（队头）删除，遵循先进先出（First In First Out）。","fx":["入队 enqueue 在队尾","出队 dequeue 在队头"],"key":"队列用于需要保持先后顺序的场景：BFS、任务调度、缓冲区。"},
  "循环队列": {"dv":{"title":"循环队列的判空与判满","steps":["把存储区首尾相连：下标对 M 取模","front 出队后前移、rear 入队后前移，均取模","若 rear == front 表示队空","若 (rear+1)%M == front 表示队满（牺牲一个单元区分空与满）","元素个数 = (rear − front + M) % M"]},"tag":"栈和队列 · 第3章","sub":"解决假溢出","def":"顺序队列用取模把存储区首尾相连成环，使出队后腾出的空间可被重新利用，避免「假溢出」。","fx":["队满判据：(rear+1)%M == front","元素个数：(rear − front + M) % M"],"key":"循环队列牺牲一个单元来区分队空与队满，这是常见约定。"},
  "括号匹配": {"dv":{"title":"括号匹配的算法","steps":["从左到右扫描表达式","遇到左括号就压入栈","遇到右括号则与栈顶比较：匹配则弹出，不匹配则失败","若遇右括号时栈已空，说明右括号多余，失败","扫描结束栈空则全部匹配，否则左括号多余"]},"tag":"栈和队列 · 第3章","sub":"栈的经典应用","def":"从左到右扫描表达式，遇左括号入栈，遇右括号则与栈顶匹配并出栈；扫描结束栈空且全程匹配则合法。","key":"括号匹配是「栈」最直观的应用，体现了 LIFO 与嵌套结构的天然契合。"},
  "两栈实现队列": {"dv":{"title":"用两个栈模拟队列","steps":["设入队栈 in、出队栈 out","入队：直接压入 in","出队：若 out 非空则直接弹出 out 栈顶","若 out 为空，则把 in 中元素全部弹出并压入 out，再弹出 out 栈顶","元素被倒入两次顺序翻转，正好实现 FIFO；均摊每操作 O(1)"]},"tag":"栈和队列 · 第3章","sub":"用两个栈模拟队列","def":"用栈 in 负责入队、栈 out 负责出队；出队时若 out 为空，则把 in 中元素全部倒入 out，再弹出栈顶。均摊每操作 O(1)。","key":"核心是「倒入」时元素顺序被反转两次，正好实现 FIFO。"},
  "串": {"dv":{"title":"串的概念","steps":["串是由零个或多个字符组成的有限序列","它是数据元素为字符的线性表","空串长度为零；空格串由空格组成，二者不同","子串是串中连续的一段字符","串的主要操作是求子串与模式匹配"]},"tag":"串、数组和广义表 · 第4章","sub":"特殊的线性表","def":"串是由零个或多个字符组成的有限序列，是数据元素为字符的线性表，关注子串、模式匹配等操作。","key":"串的操作以「子串」为核心，模式匹配是最重要的一类。"},
  "模式匹配": {"dv":{"title":"朴素模式匹配","steps":["在主串 S 中查找子串 T 首次出现的位置","从 S 的某位置起，逐字符与 T 比较","若全部匹配则成功，返回该位置","若中途失配，主串指针回退到起始位置的下一位重新比较","最坏情况下每次都比到末尾，复杂度 O(m×n)"]},"tag":"串、数组和广义表 · 第4章","sub":"在主串中查找子串","def":"模式匹配指在主串 S 中查找子串 T 第一次出现的位置。朴素算法逐位比较，最坏 O(m×n)。","fx":["朴素匹配最坏 O(m×n)","KMP 改进为 O(m+n)"],"key":"朴素算法在失配后主串指针要回退，是低效的根源。"},
  "KMP": {"dv":{"title":"KMP 的核心思想","steps":["朴素算法失配后主串指针要回退，做了重复比较","观察到：已匹配的部分本身含有信息（前后缀相等）","预处理模式串得到 next 数组，记录失配时应回退的位置","失配时主串指针不回退，只把模式串右移到 next 指示的位置","预处理 O(m)，匹配 O(n)，总计 O(m+n)"]},"tag":"串、数组和广义表 · 第4章","sub":"利用已匹配信息跳过比较","def":"KMP 算法预先求出模式串的 next 数组，失配时主串指针不回退，只移动模式串，从而把匹配复杂度降到 O(m+n)。","fx":["预处理 next 数组 O(m)","匹配过程 O(n)"],"key":"KMP 的精髓是「主串指针不回退」，靠 next 数组记录模式串的自匹配信息。"},
  "next数组": {"dv":{"title":"next 数组的含义","steps":["next[j] 表示模式串第 j 个字符失配时，模式串应回退到的下标","其值等于子串 P[0..j−1] 的最长相等前后缀长度","例如 P=abab，前缀 ab 与后缀 ab 相等，长度为 2","它反映模式串自身的重复结构","next 只与模式串有关，可预先算好"]},"tag":"串、数组和广义表 · 第4章","sub":"模式串的自匹配信息","def":"next[j] 表示模式串第 j 个字符失配时，模式串应回退到的位置，本质是最长相等前后缀的长度。","fx":["next[j] = 子串 P[0..j−1] 的最长相等前后缀长度"],"key":"next 数组只与模式串有关，与主串无关，可预先计算。"},
  "压缩存储": {"dv":{"title":"对称矩阵的压缩存储","steps":["对称矩阵满足 aᵢⱼ = aⱼᵢ，有大量重复元素","只需存下三角（含对角线）共 n(n+1)/2 个元素","按行优先把下标 (i,j) 映射到一维下标 k","当 i ≥ j 时 k = i(i−1)/2 + j","当 i < j 时用对称性取 k = j(j−1)/2 + i，实现随机存取"]},"tag":"串、数组和广义表 · 第4章","sub":"对特殊矩阵的存储优化","def":"对对称矩阵、三角矩阵、对角矩阵等，只存储其中的非零/有效元素，用公式把二维下标映射到一维空间，节省空间。","fx":["对称矩阵：只存上（下）三角，约 n(n+1)/2 个"],"key":"压缩存储的关键是找到下标映射公式，实现随机存取。"},
  "广义表": {"dv":{"title":"广义表的基本概念","steps":["广义表是 n 个元素（原子或子表）的有限序列","允许元素本身又是广义表，形成递归嵌套","表头 GetHead 取第一个元素（可为原子或子表）","表尾 GetTail 取除表头外其余元素组成的表","长度 = 顶层元素个数，深度 = 括号嵌套的最大层数"]},"tag":"串、数组和广义表 · 第4章","sub":"可以嵌套的线性表","def":"广义表是 n 个元素（可以是原子或子表）的有限序列，允许递归嵌套，如 L = (a, (b, c))。","fx":["表头 GetHead、表尾 GetTail","长度 = 顶层元素个数，深度 = 括号嵌套层数"],"key":"广义表是线性表的推广，可用于表示嵌套结构（如多项式、树）。"},
  "二叉树性质": {"dv":{"title":"二叉树基本性质的推导","steps":["第 i 层至多 2^(i−1) 个结点：每结点至多两个孩子","深度为 k 的二叉树至多 2^k − 1 个结点（等比数列求和）","设度为 0、1、2 的结点数为 n0、n1、n2","结点数 n = n0+n1+n2，分支数 B = n−1 = n1+2n2","联立解得 n0 = n2 + 1"]},"tag":"树和二叉树 · 第6章","sub":"二叉树的基本性质","def":"二叉树每个结点至多两个孩子，且有左右之分。第 i 层至多 2^(i−1) 个结点，深度为 k 的二叉树至多 2^k − 1 个结点。","fig":"fig-tree","cap":"二叉树结点计数关系","fx":["第 i 层最多 2^(i−1) 个结点","深度 k 最多 2^k − 1 个结点","n0 = n2 + 1"],"key":"这些性质是判断、构造二叉树题目的基础，务必记牢。"},
  "n0=n2+1": {"tag":"树和二叉树 · 第6章","sub":"叶子结点与双分支结点的关系","def":"任何二叉树中，叶子结点数等于度为 2 的结点数加一：n0 = n2 + 1。","dv":{"title":"推导：n0 = n2 + 1","steps":["设结点总数 n = n0 + n1 + n2","设分支（边）数 B：除根外每结点有一条入边，故 B = n − 1","又每个分支由一结点发出，度为 2 贡献 2 条、度为 1 贡献 1 条：B = n1 + 2 n2","于是 n0 + n1 + n2 − 1 = n1 + 2 n2","化简得 n0 = n2 + 1"]},"key":"这是最常考的二叉树结论，用「结点数 = 边数 + 1」即可快速证明。"},
  "先中后序遍历": {"dv":{"title":"三种遍历的递归定义","steps":["先序：访问根 → 递归左子树 → 递归右子树（NLR）","中序：递归左子树 → 访问根 → 递归右子树（LNR）","后序：递归左子树 → 递归右子树 → 访问根（LRN）","三者差别仅在访问根的时机","已知中序 + 先序（或中序 + 后序）可唯一重构二叉树"]},"tag":"树和二叉树 · 第6章","sub":"三种深度优先遍历","def":"先序：根→左→右；中序：左→根→右；后序：左→右→根。三者都是递归定义，可用递归或栈实现。","fx":["先序 NLR / 中序 LNR / 后序 LRN","已知中序 + 先序（或后序）可唯一确定一棵二叉树"],"key":"中序序列是唯一能区分左右子树的遍历，重构二叉树时离不开它。"},
  "层次遍历": {"dv":{"title":"层次遍历的实现","steps":["从根结点开始，按从上到下、从左到右的顺序访问","借助队列：先把根结点入队","循环：出队一个结点并访问","把它的左右孩子依次入队","队列为空时遍历结束；这是图的 BFS 在二叉树上的特例"]},"tag":"树和二叉树 · 第6章","sub":"按层访问（BFS）","def":"层次遍历从根开始，按从上到下、从左到右的顺序访问结点，借助队列实现。","key":"层次遍历用队列，深度优先遍历用栈——队列与栈分别对应 BFS 与 DFS。"},
  "哈夫曼树": {"dv":{"title":"哈夫曼树的构造","steps":["带权路径长度 WPL = Σ wᵢ lᵢ（wᵢ 为权，lᵢ 为路径长度）","要使其最小，应让权大的结点离根近","构造：每次取权值最小的两棵树合并为新树，新权为二者之和","重复直到只剩一棵树","由此得到最优前缀编码，高频字符码短"]},"tag":"树和二叉树 · 第6章","sub":"带权路径长度最小的树","def":"哈夫曼树是 WPL（带权路径长度）最小的二叉树，构造时每次合并权值最小的两棵树，用于最优前缀编码（哈夫曼编码）。","fx":["WPL = Σ wᵢ × lᵢ","构造：每次取最小的两个权值合并"],"key":"哈夫曼编码使高频字符用短码，是压缩的核心思想。"},
  "线索二叉树": {"dv":{"title":"线索化的原理","steps":["n 个结点的二叉树有 n+1 个空指针域，浪费","把空左指针改为指向前驱、空右指针改为指向后继","这种指针称为线索，加标志位区分线索与孩子指针","线索化后遍历无需栈，可直接找前驱/后继","本质是空间换时间，利用闲置空指针"]},"tag":"树和二叉树 · 第6章","sub":"利用空指针加速遍历","def":"把空的左右指针改为指向前驱/后继（线索），使二叉树无需栈即可完成遍历，方便找前驱后继。","fx":["左空指针 → 前驱线索","右空指针 → 后继线索"],"key":"线索化把闲置的空指针利用起来，是「空间换时间」的思想。"},
  "邻接矩阵vs邻接表": {"dv":{"title":"两种图的存储结构","steps":["邻接矩阵：n×n 数组，matrix[i][j] 表示边 (i,j) 是否存在","判断两点是否相邻 O(1)，但空间 O(n²)","邻接表：每个顶点一个链表，存其所有邻接点","空间 O(n+e)，适合稀疏图，但判断两点是否相邻需查链表","稠密图用矩阵、稀疏图用邻接表"]},"tag":"图 · 第7章","sub":"图的两种存储结构","def":"邻接矩阵用二维数组表示边，适合稠密图，判断两点是否有边 O(1)；邻接表用链表数组存邻接点，适合稀疏图，省空间。","fx":["邻接矩阵：空间 O(n²)","邻接表：空间 O(n + e)"],"key":"稠密图用矩阵、稀疏图用邻接表——选择依据是边数 e 与 n² 的关系。"},
  "DFS/BFS": {"dv":{"title":"图的两种遍历","steps":["DFS：从起点出发沿一条路走到底，走不动再回溯","DFS 用栈（或递归）实现，类似树的先序遍历","BFS：从起点逐层向外扩展，先近后远","BFS 用队列实现，类似树的层次遍历","邻接表下两者均为 O(n+e)；BFS 可求无权图最短路"]},"tag":"图 · 第7章","sub":"图的两种遍历","def":"深度优先搜索（DFS）沿一条路走到底再回溯，用栈/递归实现；广度优先搜索（BFS）逐层扩展，用队列实现。","fx":["DFS：栈/递归，类似树的先序","BFS：队列，类似树的层次遍历"],"key":"二者时间复杂度相同（邻接表 O(n+e)），但用途不同：BFS 求最短路径（无权图），DFS 求连通性、拓扑。"},
  "Prim/Kruskal": {"dv":{"title":"最小生成树的两种算法","steps":["最小生成树是连通网中边权和最小的生成树，含 n−1 条边","Prim：从一个顶点开始，每次把连接「已选集合」与「未选集合」的最小权边加入","Prim 复杂度 O(n²)，适合稠密图","Kruskal：把边按权升序排序，依次选不构成回路的边","Kruskal 用并查集判环，复杂度 O(e log e)，适合稀疏图"]},"tag":"图 · 第7章","sub":"求最小生成树的两种算法","def":"Prim 从一个顶点出发不断把最近的顶点加入集合，适合稠密图；Kruskal 按边权从小到大选边、用并查集避免成环，适合稀疏图。","fx":["Prim：O(n²)，稠密图优","Kruskal：O(e log e)，稀疏图优"],"key":"两者都贪心地求最小生成树，选择取决于图的稠密程度。"},
  "Dijkstra/Floyd": {"dv":{"title":"最短路径算法","steps":["Dijkstra：求单源到其余各点的最短路径","它贪心地每次选出当前距离最小的未确定点，再松弛其邻居","要求边权非负，复杂度 O(n²)","Floyd：求任意两点间最短路径","Floyd 用三重循环做动态规划，枚举中间点，O(n³)，允许负权（无负环）"]},"tag":"图 · 第7章","sub":"最短路径算法","def":"Dijkstra 求单源最短路径，贪心逐点确定，不能处理负权边；Floyd 求任意两点间最短路径，用三重循环动态规划，可处理负权。","fx":["Dijkstra：单源，O(n²)","Floyd：多源，O(n³)"],"key":"单源用 Dijkstra、多源用 Floyd；Dijkstra 遇到负权会失效。"},
  "负权限制": {"dv":{"title":"为何 Dijkstra 不能有负权","steps":["Dijkstra 依赖贪心前提：已确定点的最短距离不会再变小","若存在负权边，后确定的点可能通过负边使已确定路径变短","贪心前提被破坏，算法可能给出错误结果","故有负权时要改用 Bellman-Ford 或 SPFA","无负权（或有向无负环）才能安全使用 Dijkstra"]},"tag":"图 · 第7章","sub":"为什么 Dijkstra 不能处理负权","def":"Dijkstra 基于「已确定点最短距离不会再变」的贪心前提；一旦存在负权边，后加入的点可能使已确定的最短路径变短，前提被破坏，算法失效。","key":"有负权时改用 Bellman-Ford / SPFA；无负权才能放心用 Dijkstra。"},
  "磁感应强度": {"tag":"恒定磁场 · 7.1","def":"描述磁场强弱与方向的物理量，定义式 B = F/(qv)（运动电荷）或 B = F/(IL)（电流元），方向为该点小磁针 N 极指向。单位特斯拉 T，1 T = 1 N/(A·m)。","fx":["B = F_max/(qv)","dF = Idl×B 中 B 的大小即 F⊥/(Idl)"],"key":"磁感应强度是磁场的「场强」角色，地位相当于电场的 E。"},
  "毕奥–萨伐尔定律": {"tag":"恒定磁场 · 7.1","def":"电流元 Idl 在场点产生的元磁场，是计算任意载流导线磁场的基本定律，地位类似电场中的库仑定律。","fx":["dB = (μ₀/4π)·Idl×r̂/r²","大小 dB = (μ₀/4π)·Idl·sinθ/r²","叠加：B = ∫dB"],"key":"应用三件套：取电流元 → 写 dB 分解 → 对称性化简后积分。"},
  "磁场高斯定理": {"tag":"恒定磁场 · 7.2","def":"穿过任意闭合曲面的磁通量恒为零。物理含义：磁场是无源场，磁感线是闭合曲线，不存在磁单极。","fx":["∮B·dS = 0","Φ = ∫B·dS（磁通量，单位 Wb）"],"key":"对比电场高斯定理 ∮E·dS = q/ε₀：电场有源、磁场无源。"},
  "安培环路定理": {"tag":"恒定磁场 · 7.3","def":"磁感应强度沿任意闭合回路的线积分，等于穿过该回路的电流代数和的 μ₀ 倍。用于高度对称情形（无限长直导线、螺线管、螺绕环）求 B。","fx":["∮B·dl = μ₀ΣI","无限长直导线：B = μ₀I/(2πr)","长直螺线管内：B = μ₀nI"],"key":"取环路三原则：过场点、顺对称、B 在环上为常量或分段常量。"},
  "安培力": {"tag":"恒定磁场 · 7.4","def":"载流导线在磁场中受的力，本质是导线中定向运动电荷受洛伦兹力的宏观表现。方向由左手定则判定。","fx":["dF = Idl×B","直导线匀强场：F = BIL·sinθ","θ = 90° 时 F = BIL 最大"],"key":"闭合线圈在匀强磁场中合力为零，只受力矩 M = m×B（m = NIS 磁矩）。"},
  "洛伦兹力": {"tag":"恒定磁场 · 7.4","def":"运动电荷在磁场中受的力。始终垂直于速度方向，故洛伦兹力永不做功，只改变速度方向、不改变速率。","fx":["F = qv×B","大小 F = qvB·sinθ","v ∥ B 时 F = 0"],"key":"「永不做功」是最高频考点：带电粒子在纯磁场中动能不变。"},
  "回旋半径": {"tag":"恒定磁场 · 7.4","def":"带电粒子垂直射入匀强磁场做匀速圆周运动，洛伦兹力提供向心力。","fx":["qvB = mv²/R → R = mv/(qB)","周期 T = 2πm/(qB)（与速度无关！）","v 与 B 有夹角时：螺旋线，半径用 v⊥，螺距 h = v∥T"],"key":"周期与速率无关是回旋加速器的原理基础。"},
  "磁介质": {"tag":"恒定磁场 · 7.5","def":"放入磁场中会被磁化的物质。按磁化效果分为顺磁质（μᵣ 略>1）、抗磁质（μᵣ 略<1）、铁磁质（μᵣ ≫1，有磁滞回线）。","fx":["B = μ₀μᵣH = μH","磁化强度 M = χ_m H"],"key":"铁磁质有剩磁与磁滞现象，居里点以上退化为顺磁质。"},
  "磁场强度 H": {"tag":"恒定磁场 · 7.5","def":"为便于处理有磁介质时的磁场而引入的辅助矢量，只由传导电流决定。","fx":["H = B/μ₀ − M","∮H·dl = ΣI₀（H 的环路定理）","B = μH = μ₀μᵣH"],"key":"先由 ∮H·dl = I₀ 求 H，再乘 μ 得 B——有介质时的标准两步法。"},
  "法拉第定律": {"tag":"电磁感应 · 8.1","def":"回路中感应电动势的大小等于穿过回路的磁通量变化率的负值。负号体现楞次定律的方向要求。","fx":["ℰ = −dΦ/dt","N 匝：ℰ = −N·dΦ/dt","Φ = ∫B·dS"],"key":"求电动势两大类：磁通变化（法拉第）或导体切割（动生 Blv）。"},
  "楞次定律": {"tag":"电磁感应 · 8.1","def":"感应电流的方向，总是使它产生的磁场去阻碍引起感应的磁通量变化。「增反减同、来拒去留」。","fx":["B 通量增大 → 感应磁场与原磁场反向","B 通量减小 → 感应磁场与原磁场同向"],"key":"楞次定律是能量守恒在电磁感应中的体现——阻碍的是「变化」，不是磁场本身。"},
  "动生电动势": {"tag":"电磁感应 · 8.2","def":"导体在磁场中运动切割磁感线产生的电动势，非静电力是洛伦兹力。","fx":["ℰ = ∫(v×B)·dl","直导体匀强场垂直切割：ℰ = Blv","转动棒（角速度 ω）：ℰ = ½Bωl²"],"key":"右手定则判方向；洛伦兹力沿棒的分力搬运电荷建立电势差。"},
  "感生电动势": {"tag":"电磁感应 · 8.2","def":"导体不动、磁场随时间变化时产生的电动势，非静电力是涡旋电场力。","fx":["ℰ = ∮E_k·dl = −∫(∂B/∂t)·dS","长直螺线管内（r≤R）：E_k = −(r/2)·dB/dt","管外（r≥R）：E_k = −(R²/2r)·dB/dt"],"key":"动生 vs 感生：看非静电力——洛伦兹力还是涡旋电场力。"},
  "涡旋电场": {"tag":"电磁感应 · 8.2","def":"变化的磁场在空间激发的电场，电场线是闭合曲线，不是保守场，不能引入电势概念。","fx":["∮E_k·dl = −dΦ/dt","对比静电场：∮E·dl = 0（保守场）"],"key":"涡旋电场与静电场的唯一共同点是对电荷都有作用力 F = qE。"},
  "自感": {"tag":"电磁感应 · 8.3","def":"线圈自身电流变化在自身回路中产生感应电动势的现象。自感系数 L 只由线圈几何与介质决定。","fx":["ℰ_L = −L·dI/dt","L = NΦ/I","长直螺线管 L = μn²V"],"key":"L 是电磁惯性：电流不能突变（电感「通直流、阻交流」）。"},
  "互感": {"tag":"电磁感应 · 8.3","def":"一个线圈电流变化，在邻近线圈中产生感应电动势的现象。互感系数 M₁₂ = M₂₁ = M。","fx":["ℰ₂₁ = −M·dI₁/dt","M = Ψ₂₁/I₁","两线圈串联：L = L₁+L₂±2M"],"key":"顺接加 2M、反接减 2M——变压器与感应线圈的工作原理。"},
  "磁场能量": {"tag":"电磁感应 · 8.4","def":"磁场储存的能量。建立电流过程中电源反抗自感电动势做的功转化为磁场能。","fx":["自感储能 W_m = ½LI²","能量密度 w_m = B²/(2μ) = ½BH","W_m = ∫w_m dV"],"key":"对比电场能量密度 w_e = ½εE²，形式完全对称。"},
  "位移电流": {"tag":"电磁感应 · 8.4","def":"麦克斯韦假设：变化的电场等效于一种电流（位移电流），也能激发磁场，使安培环路定理适用于非恒定情形。","fx":["I_d = dΦ_D/dt = ε·dΦ_E/dt","全电流 = 传导电流 + 位移电流","∮H·dl = I₀ + dΦ_D/dt"],"key":"位移电流不产生焦耳热、不对应电荷移动，唯一作用是「变化电场激发磁场」。"},
  "麦克斯韦方程组": {"tag":"电磁感应 · 8.4","def":"电磁场的四个基本方程，概括全部电磁现象并预言电磁波存在。","fx":["∮E·dS = q/ε₀（电场有源）","∮B·dS = 0（磁场无源）","∮E·dl = −dΦ_B/dt（变化磁场激发电场）","∮H·dl = I₀ + dΦ_D/dt（电流与变化电场激发磁场）"],"key":"记忆框架：两个通量定理（源）+ 两个环流定理（旋）。"},
  "回复力": {"tag":"振动 · 9.1","def":"使振动物体回到平衡位置的力，大小与位移成正比、方向与位移相反。满足 F = −kx 或力矩 M = −kθ 的振动必为简谐振动。","fx":["F = −kx","判据：d²x/dt² + ω²x = 0"],"key":"证明简谐振动的标准步骤：找回复力 → 写 F = −kx 形式 → 读出 ω² = k/m。"},
  "振幅": {"tag":"振动 · 9.1","def":"振动物体离开平衡位置的最大位移的绝对值，反映振动强弱。由初始条件决定。","fx":["A = √(x₀² + v₀²/ω²)","能量 E = ½kA² ∝ A²"],"key":"振幅由能量（初始条件）定，周期由系统固有参数定——两者相互独立。"},
  "角频率": {"tag":"振动 · 9.1","def":"描述振动快慢的物理量，ω = 2π/T = 2πν，由振动系统自身性质决定，故称固有角频率。","fx":["弹簧振子 ω = √(k/m)","单摆 ω = √(g/l)","复摆 ω = √(mgh/J)"],"key":"ω 与初始条件无关——同一个弹簧振子，无论怎么拉开，频率都一样。"},
  "初相": {"tag":"振动 · 9.1","def":"t = 0 时刻的相位，决定振动物体的初始状态（位置与运动方向）。","fx":["tanφ = −v₀/(ωx₀)","象限由 x₀、v₀ 正负共同确定"],"key":"定初相两步走：先由 tanφ 算值，再由 x₀ 或 v₀ 的符号确定象限。"},
  "旋转矢量法": {"tag":"振动 · 9.1","def":"用匀角速旋转矢量在 x 轴上的投影表示简谐振动的几何方法：矢量长 = A，角速度 = ω，t=0 时与 x 轴夹角 = φ。","fx":["x = A·cos(ωt+φ) ↔ 投影","v 对应切向速度的投影"],"key":"求相位、合成振动、画振动曲线时比代数法直观得多，考试首选。"},
  "相位差": {"tag":"振动 · 9.1","def":"两个振动在同一时刻的相位之差 Δφ = (ω₂t+φ₂) − (ω₁t+φ₁)。同频率时为常数 φ₂−φ₁。","fx":["Δφ = 2kπ：同相（振动步调一致）","Δφ = (2k+1)π：反相","「x 比 y 超前 Δφ」指 x 先到达最大位移"],"key":"超前与滞后看相位：相位大的先到达某一状态。"},
  "振动能量": {"tag":"振动 · 9.1","def":"简谐振动中动能与势能相互转化、总量守恒。","fx":["E = ½kA²（常量）","Ek = ½kA²sin²(ωt+φ)","Ep = ½kA²cos²(ωt+φ)"],"key":"平衡位置动能最大势能最小；最大位移处反之。Ek、Ep 的变化频率是振动频率的 2 倍。"},
  "振动合成": {"tag":"振动 · 9.2","def":"同方向同频率两简谐振动的合振动仍是同频率简谐振动，用旋转矢量合成的余弦定理求合振幅。","fx":["A² = A₁²+A₂²+2A₁A₂cosΔφ","Δφ = 2kπ：A = A₁+A₂ 加强","Δφ = (2k+1)π：A = |A₁−A₂| 减弱"],"key":"垂直方向同频率振动的合成轨迹由 Δφ 决定：0/π 为直线，π/2 为正椭圆。"},
  "拍": {"tag":"振动 · 9.2","def":"两个频率相近（|ν₁−ν₂| ≪ ν₁）的同方向简谐振动合成时，合振幅周期性强弱变化的现象。","fx":["拍频 ν_拍 = |ν₁−ν₂|","合振幅在 0 与 2A 间缓慢变化"],"key":"拍频 = 两频率之差（不是之和），用于乐器调音与测频率。"},
  "阻尼振动": {"tag":"振动 · 9.3","def":"振动系统在阻力作用下振幅随时间减小的振动。按阻力大小分欠阻尼、临界阻尼、过阻尼三种。","fx":["欠阻尼：A = A₀e^(−βt)，仍振动","临界阻尼：最快回到平衡不往复","过阻尼：缓慢爬回平衡"],"key":"欠阻尼振动的周期比固有周期略长，振幅按指数包络衰减。"},
  "受迫振动": {"tag":"振动 · 9.3","def":"系统在周期性驱动力作用下做的振动。稳定后以<b>驱动力的频率</b>振动，与系统固有频率无关。","fx":["稳态：x = A·cos(ω_驱 t + φ)","A 随 ω_驱 变化，ω_驱→ω₀ 时最大"],"key":"稳定受迫振动的频率 = 驱动力频率，这是与自由振动的本质区别。"},
  "共振": {"tag":"振动 · 9.3","def":"受迫振动中驱动力频率接近系统固有频率时，振幅达到极大的现象。","fx":["ω_驱 = √(ω₀² − 2β²) 时位移共振","阻尼 β 越小，共振峰越高越尖锐"],"key":"共振有利（乐器共鸣、核磁共振）有弊（桥梁、机器），考点是条件：驱动力频率 ≈ 固有频率。"},
  "横波与纵波": {"tag":"波动 · 10.1","def":"按质点振动方向与波传播方向的关系分类：垂直为横波（如绳波、电磁波），平行为纵波（如声波）。","fx":["横波只能在固体中传播（需切变弹性）","纵波固液气中均可传播"],"key":"液体表面波是横纵混合。判定只看「振动方向 ⊥ 还是 ∥ 传播方向」。"},
  "波长": {"tag":"波动 · 10.1","def":"同一波线上相位差为 2π 的两个相邻质点间的距离，即波在一个周期内传播的距离。","fx":["λ = uT = u/ν","相邻同相点间距 = λ"],"key":"波长由波源（ν）和介质（u）共同决定：ν 由波源定，u 由介质定。"},
  "波速": {"tag":"波动 · 10.1","def":"相位（振动状态）传播的速度，只由介质的弹性和惯性决定，与波源无关。","fx":["u = λν = λ/T","绳上横波 u = √(F/μ)","固体纵波 u = √(E/ρ)"],"key":"「波速由介质定」是核心考点：波从一种介质进入另一种介质，u、λ 变，ν 不变。"},
  "波函数": {"tag":"量子物理 · 15.5","def":"描述微观粒子状态的函数，本身不可测；其模方 |ψ|² 表示粒子出现的概率密度（玻恩统计解释）。","fx":["|ψ|² = 概率密度","归一化 ∫|ψ|²dV = 1","一维无限深势阱 ψ_n = √(2/L)·sin(nπx/L)"],"key":"合格波函数三条件：单值、连续、有限（平方可积）。归一化求系数是高频计算题。"},
  "相位落后": {"tag":"波动 · 10.1","def":"波沿传播方向，下游质点的振动相位比上游质点落后。相距 Δx 的两点相位差 Δφ = 2πΔx/λ。","fx":["Δφ = ω·Δx/u = 2πΔx/λ","相差 λ 的两点同相"],"key":"「下游总是重复上游的历史」——x 处 t 时刻的相位 = 波源 t−x/u 时刻的相位。"},
  "波的能量密度": {"tag":"波动 · 10.2","def":"介质单位体积内波的能量。波动中质元的动能与势能<b>同相</b>同时最大、同时为零（与孤立振子不同！）。","fx":["w = ρA²ω²sin²[ω(t−x/u)+φ]","平均能量密度 w̄ = ½ρA²ω²"],"key":"波动质元能量不守恒（随时间变化），因为它在与相邻质元交换能量——这正是能量传播的方式。"},
  "波强": {"tag":"波动 · 10.2","def":"单位时间通过垂直于传播方向单位面积的平均能量（平均能流密度）。","fx":["I = w̄·u = ½ρA²ω²u","点波源各向同性：I ∝ 1/r²，A ∝ 1/r"],"key":"波强 ∝ A²ω²：振幅加倍强度四倍，这是声强、光强计算的通用形式。"},
  "惠更斯原理": {"tag":"波动 · 10.3","def":"波前上的每一点都可看作发射子波的新波源，下一时刻的波前是这些子波的包络面。","fx":["可解释：直线传播、反射、折射、衍射","折射定律：sin i/sin r = u₁/u₂ = n₂/n₁"],"key":"惠更斯原理是几何方法，定量计算仍需用相位与波程差。"},
  "相干条件": {"tag":"波动 · 10.3","def":"两列波能产生稳定干涉必须满足：频率相同、振动方向相同（或有平行分量）、相位差恒定。","fx":["干涉加强：Δφ = 2kπ","干涉减弱：Δφ = (2k+1)π","光程差版：δ = kλ 加强，δ = (2k+1)λ/2 减弱"],"key":"普通光源不满足相位差恒定 → 分波阵面（双缝）或分振幅（薄膜）获得相干光。"},
  "波程差": {"tag":"波动 · 10.3","def":"两列波到达相遇点所经路程之差，决定该点的干涉结果。","fx":["δ = r₂ − r₁","δ = kλ → 加强（振幅 A₁+A₂）","δ = (2k+1)λ/2 → 减弱"],"key":"从波程差 δ 到相位差：Δφ = 2πδ/λ（注意加上波源的初相差）。"},
  "驻波": {"tag":"波动 · 10.4","def":"两列振幅相同的相干波沿相反方向传播叠加形成的特殊干涉：波形不移动，各点振幅随位置固定分布。","fx":["y = 2A·cos(2πx/λ)·cos(ωt)","波腹 x = kλ/2（振幅 2A）","波节 x = (2k+1)λ/4（振幅 0）"],"key":"驻波不传播能量；相邻波节间各点同相，波节两侧反相。"},
  "波节波腹": {"tag":"波动 · 10.4","def":"驻波中振幅恒为零的点叫波节，振幅最大（2A）的点叫波腹。","fx":["相邻波节（或波腹）间距 = λ/2","波节与相邻波腹间距 = λ/4"],"key":"弦的固有频率条件：L = nλ/2（两端固定）——由「两端必须是波节」直接读出。"},
  "半波损失": {"tag":"波动 · 10.4","def":"波从波疏介质射向波密介质的反射点，反射波发生 π 的相位突变，相当于多走（或少走）半个波长。","fx":["波疏→波密 反射：有半波损失（相位突变 π）","波密→波疏 反射：无半波损失","等效：反射点波程附加 ±λ/2"],"key":"判断口诀「疏到密，丢半波」。固定端反射有半波损失（成波节），自由端无（成波腹）。"},
  "多普勒效应": {"tag":"波动 · 10.5","def":"波源与观察者相对运动时，接收频率不同于波源频率的现象。靠近变高、远离变低。","fx":["观察者动：ν′ = (u±v₀)/u · ν","波源动：ν′ = u/(u∓vₛ) · ν","两者都动：ν′ = (u±v₀)/(u∓vₛ) · ν"],"key":"符号规则：相互靠近取使频率升高的符号（分子加、分母减）。波源运动改变波长，观察者运动改变相对波速——物理机制不同。"},
  "光程": {"tag":"波动光学 · 11.1","def":"光在介质中传播的几何路程与介质折射率的乘积 L = nr，把介质中的路程折算成真空中等效路程。","fx":["光程差 δ = n₂r₂ − n₁r₁","相位差 Δφ = 2πδ/λ（λ 为真空波长）"],"key":"透镜不引起附加光程差；比较相位一律用光程差而不是几何程差。"},
  "相干光": {"tag":"波动光学 · 11.1","def":"满足相干条件（同频率、同振动方向、相位差恒定）的光。普通光源原子发光随机，必须人为制造相干光。","fx":["分波阵面法：双缝、劳埃德镜","分振幅法：薄膜、劈尖、牛顿环"],"key":"两盏相同的灯也看不到干涉——独立光源相位差不恒定。"},
  "双缝干涉": {"tag":"波动光学 · 11.1","def":"杨氏实验：单色光经双缝分成两束相干光，在屏上形成等间距明暗条纹。","fx":["明纹 x = ±kDλ/d（k = 0,1,2…）","暗纹 x = ±(2k+1)Dλ/(2d)","条纹间距 Δx = Dλ/d"],"key":"白光入射：中央白纹，两侧彩色条纹内紫外红（紫 λ 短间距小）。缝放介质 n 中：条纹整体平移。"},
  "条纹间距": {"tag":"波动光学 · 11.1","def":"双缝干涉相邻明纹（或暗纹）中心的距离。","fx":["Δx = Dλ/d","劈尖相邻条纹间距 l = λ/(2nθ）","牛顿环相邻环间距不等（内疏外密）"],"key":"间距 ∝ λ：红光条纹比紫光宽。判断条纹移动方向：盯住零光程差点。"},
  "增透膜": {"tag":"波动光学 · 11.2","def":"在光学元件表面镀的薄膜，利用上下表面反射光干涉相消来减弱反射、增强透射。","fx":["反射相消条件：2ne = (2k+1)λ/2","最小膜厚 e = λ/(4n)（n 满足 1<n<n_玻璃，上下均有半波损失）","增反膜条件相反：2ne = kλ"],"key":"有无半波损失各算一次：膜两侧反射光若都（或都不）发生半波损失，则附加光程差为 0；只一侧发生则附加 λ/2。"},
  "牛顿环": {"tag":"波动光学 · 11.2","def":"平凸透镜与平板玻璃间的空气薄膜产生的等厚干涉，条纹为同心圆环。","fx":["暗环半径 r_k = √(kRλ)（k = 0,1,2…）","明环半径 r_k = √((2k−1)Rλ/2)","中心处 e = 0，考虑半波损失为暗斑"],"key":"环纹内疏外密（r ∝ √k）；透镜上移时条纹向中心收缩（等厚线内移）。"},
  "单缝衍射": {"tag":"波动光学 · 11.3","def":"光通过单缝时的夫琅禾费衍射，用半波带法分析：缝面波阵面分成偶数个半波带时两两抵消成暗纹。","fx":["暗纹：a·sinθ = ±kλ（k = 1,2,3…）","中央明纹半角宽 Δθ₀ = λ/a","中央明纹线宽 Δx₀ = 2fλ/a（其余明纹宽度的一半的 2 倍关系：中央是其他的两倍）"],"key":"k=0 不是暗纹是中央明纹！中央明纹宽度是其他明纹的 2 倍，亮度占绝大部分。"},
  "艾里斑": {"tag":"波动光学 · 11.3","def":"圆孔衍射图样的中央亮斑，集中约 84% 的光能量。","fx":["半角宽 θ₀ ≈ 1.22λ/D（D 为圆孔直径）","艾里斑半径 r₀ = 1.22λf/D"],"key":"与单缝的 λ/a 形式类似，圆孔多一个 1.22 系数。"},
  "瑞利判据": {"tag":"波动光学 · 11.3","def":"两个点光源恰能分辨的标准：一个的衍射图样中央极大恰落在另一个的第一暗纹处。","fx":["最小分辨角 θ₀ = 1.22λ/D","分辨本领 R = 1/θ₀ = D/(1.22λ)"],"key":"提高分辨率两条路：增大孔径 D（望远镜做更大）、减小波长 λ（电子显微镜）。"},
  "光栅方程": {"tag":"波动光学 · 11.4","def":"光栅（大量等宽等间距狭缝）衍射主极大的位置条件。","fx":["d·sinθ = ±kλ（k = 0,1,2…）","d = a + b 为光栅常数","相邻主极大间有 N−1 个极小、N−2 个次极大"],"key":"光栅条纹特点：细、亮、间距大——主极大位置由光栅方程定，宽度随缝数 N 增大变窄。"},
  "缺级": {"tag":"波动光学 · 11.4","def":"光栅中某级主极大同时满足单缝衍射暗纹条件时，该级条纹消失的现象。","fx":["光栅明纹：d·sinθ = kλ","单缝暗纹：a·sinθ = k′λ","缺级级次 k = (d/a)·k′（k′ = 1,2,3…）"],"key":"例：d/a = 3 时 k = 3, 6, 9… 级主极大缺失——考「实际能看到哪几级」必用。"},
  "马吕斯定律": {"tag":"波动光学 · 11.5","def":"线偏振光通过偏振片后，透射光强随偏振方向夹角变化的规律。","fx":["I = I₀·cos²α","α 为入射偏振方向与偏振片透振方向夹角","自然光通过偏振片后 I = I₀/2"],"key":"连续通过多个偏振片逐次乘 cos²α；自然光先减半再按马吕斯定律。"},
  "布儒斯特角": {"tag":"波动光学 · 11.5","def":"自然光以特定角入射介质界面时，反射光为完全线偏振光，此时反射线与折射线互相垂直。","fx":["tan i₀ = n₂/n₁","i₀ + r = 90°"],"key":"玻璃（n=1.5）到空气：i₀ ≈ 56.3°。布儒斯特角入射时折射光仍为部分偏振光（只反射光全偏振）。"},
  "理想气体状态方程": {"tag":"气体动理论 · 12.1","def":"平衡态下理想气体压强、体积、温度满足的关系式，是宏观描述与微观理论的桥梁。","fx":["pV = (M/μ)RT = νRT","分子数形式：p = nkT","R = 8.31 J/(mol·K)，k = R/N_A = 1.38×10⁻²³ J/K"],"key":"三种形式等价：摩尔形式、p=nkT、pV/T = 常量（一定质量）。"},
  "玻尔兹曼常数": {"tag":"气体动理论 · 12.2","def":"联系宏观温度与微观分子能量的普适常量，数值等于普适气体常量除以阿伏伽德罗常数。","fx":["k = R/N_A ≈ 1.38×10⁻²³ J/K","分子平均平动动能 ε̄ = (3/2)kT"],"key":"见到「单个分子」的能量用 k，见到「一摩尔」用 R——两者只差一个 N_A。"},
  "压强微观本质": {"tag":"气体动理论 · 12.2","def":"气体压强是大量分子对器壁持续碰撞的平均冲力效果，是统计平均量。","fx":["p = ⅓nm·v̄²","p = ⅔nε̄（ε̄ 为平均平动动能）"],"key":"压强公式的推导链：撞一次动量改变 2mv_x → 碰壁频率 v_x/2l → 求和取平均 → 各向同性 v̄_x² = v̄²/3。"},
  "温度统计意义": {"tag":"气体动理论 · 12.2","def":"温度是分子热运动平均平动动能的量度，只描述大量分子的集体行为。","fx":["ε̄ = (3/2)kT","v̄² = 3kT/m = 3RT/μ"],"key":"对单个分子谈温度没有意义；同温度下不同气体的平均平动动能相同，但速率不同（质量不同）。"},
  "自由度": {"tag":"数理统计 · 6.2","def":"统计量中能够自由取值的变量个数；约束条件会吃掉自由度。","fx":["样本方差含约束 Σ(Xᵢ−X̄)=0 → n−1","χ²(n) 中 n 即自由度"],"key":"记住三个常用自由度：(n−1)S²/σ² 是 n−1；t 检验是 n−1；F 检验是 (n₁−1, n₂−1)。"},
  "能量均分定理": {"tag":"气体动理论 · 12.3","def":"平衡态下，分子每个自由度的平均动能都等于 ½kT——能量按自由度均匀分配。","fx":["每个自由度 ½kT","i 自由度分子平均总动能 = (i/2)kT","振动每个自由度含动能+势能共 kT"],"key":"均分定理是经典统计结果，低温下因量子效应失效（自由度冻结）。"},
  "内能": {"tag":"气体动理论 · 12.3","def":"系统内所有分子热运动动能与分子间势能的总和。理想气体忽略分子间势能，内能只是温度的函数。","fx":["理想气体 E = ν·(i/2)·RT","ΔE = ν·(i/2)·R·ΔT"],"key":"内能是状态量：ΔE 只看初末态温度差，与过程无关——算 ΔE 永远用最省事的等容过程。"},
  "麦克斯韦速率分布": {"tag":"气体动理论 · 12.4","def":"平衡态下气体分子速率按确定统计规律分布：速率很大和很小的分子都少，中等速率的分子最多。","fx":["f(v)dv = dN/N（速率 v~v+dv 内分子占比）","曲线总面积 = 1（归一化）","T 升高：峰右移、变矮变宽"],"key":"温度升高时「最概然速率变大、峰值变矮、面积不变」三个特征常考。"},
  "最概然速率": {"tag":"气体动理论 · 12.4","def":"速率分布函数取最大值处的速率，即出现概率最大的速率。","fx":["v_p = √(2kT/m) = √(2RT/μ) ≈ 1.41√(RT/μ)"],"key":"三种速率排序：v_p < v̄ < √(v̄²) 即 1.41 : 1.60 : 1.73（单位 √(RT/μ)）。"},
  "方均根速率": {"tag":"气体动理论 · 12.4","def":"分子速率平方平均值的平方根，与平均平动动能直接联系。","fx":["√(v̄²) = √(3kT/m) = √(3RT/μ) ≈ 1.73√(RT/μ)","平均速率 v̄ = √(8kT/πm) ≈ 1.60√(RT/μ)"],"key":"求动能用方均根速率，求碰撞频率/输运用平均速率——用途不同别混用。"},
  "平均自由程": {"tag":"气体动理论 · 12.5","def":"分子在两次连续碰撞之间自由通过的平均路程。","fx":["λ̄ = 1/(√2·πd²·n)","结合 p = nkT：λ̄ = kT/(√2·πd²·p)","平均碰撞频率 z̄ = v̄/λ̄ = √2·πd²·n·v̄"],"key":"温度不变时 λ̄ ∝ 1/p：压强减半，自由程加倍。"},
  "功": {"tag":"热力学 · 13.1","def":"气体体积变化时对外做的功，是过程量（与路径有关）。","fx":["元功 dA = p·dV","A = ∫p dV = p-V 图上过程曲线下面积","膨胀 A > 0，压缩 A < 0"],"key":"p-V 图上同一对初末态、不同路径面积不同 → 功是过程量的几何证据。"},
  "热量": {"tag":"热力学 · 13.1","def":"通过温差传递的能量，也是过程量。","fx":["Q = νC·ΔT","C_V = (i/2)R，C_p = (i+2)R/2","γ = C_p/C_V = (i+2)/i"],"key":"Q 与 A 都是过程量，但它们的组合 ΔE = Q − A 是状态量——热一律的深刻之处。"},
  "热力学第一定律": {"tag":"热力学 · 13.1","def":"能量守恒在热学中的形式：系统吸收的热量 = 内能增量 + 对外做功。","fx":["Q = ΔE + A","微分形式 dQ = dE + p·dV","循环过程 ΔE = 0 → Q_净 = A_净"],"key":"符号约定：吸热 Q>0、对外做功 A>0。各过程套同一个式子，只是 Q、ΔE、A 各有特殊值。"},
  "等容过程": {"tag":"热力学 · 13.2","def":"体积不变的过程。","fx":["A = 0","Q = ΔE = νC_V·ΔT","p/T = 常量"],"key":"等容过程「吸多少热全变内能」——这是用等容过程算 ΔE 的依据。"},
  "等压过程": {"tag":"热力学 · 13.2","def":"压强不变的过程。","fx":["A = p·ΔV = νR·ΔT","Q = νC_p·ΔT","ΔE = νC_V·ΔT（仍成立！）"],"key":"等压吸热分两份：(i/2) 份变内能、1 份变做功——比值固定。"},
  "等温过程": {"tag":"热力学 · 13.2","def":"温度不变的过程。","fx":["ΔE = 0 → Q = A","A = νRT·ln(V₂/V₁) = νRT·ln(p₁/p₂)","pV = 常量"],"key":"等温过程「吸多少热全变成功」；记住 ln(V₂/V₁) 用体积比。"},
  "绝热过程": {"tag":"热力学 · 13.2","def":"与外界无热交换的过程。","fx":["Q = 0 → A = −ΔE = −νC_V·ΔT","pV^γ = 常量，TV^(γ−1) = 常量","A = (p₁V₁ − p₂V₂)/(γ−1)"],"key":"绝热膨胀靠消耗内能对外做功 → 温度必降；绝热线比等温线陡（斜率大 γ 倍）。"},
  "循环效率": {"tag":"热力学 · 13.3","def":"热机循环一次，对外做的净功与从高温热源吸收的热量之比。","fx":["η = A_净/Q_吸 = 1 − Q_放/Q_吸","注意 Q_吸 只算吸热过程之和","制冷系数 w = Q₂/A"],"key":"易错：η 的分母是「总吸热」不是「净热」。p-V 图上净功 = 循环包围面积。"},
  "卡诺循环": {"tag":"热力学 · 13.3","def":"由两个等温过程和两个绝热过程组成的理想循环，是效率最高的可逆循环。","fx":["η_卡 = 1 − T₂/T₁","卡诺制冷系数 w_卡 = T₂/(T₁−T₂)"],"key":"卡诺定理：同温热源间一切可逆机效率都等于卡诺效率，不可逆机效率必小于它。"},
  "热力学第二定律": {"tag":"热力学 · 13.4","def":"指明自然过程方向性的定律，两种等价表述。","fx":["开尔文表述：不可能从单一热源吸热全部变功而不引起其他变化","克劳修斯表述：热量不可能自发从低温传到高温","本质：与热现象有关的宏观过程不可逆"],"key":"「自发」二字是关键：制冷机能使热量从低温到高温，但要外界做功（引起了其他变化）。"},
  "熵": {"tag":"热力学 · 13.4","def":"描述系统混乱程度的状态函数，用可逆过程的热温比积分定义其变化。","fx":["dS = dQ_可逆/T","ΔS = ∫(dQ_可逆/T)（与路径无关）","理想气体 ΔS = νC_V·ln(T₂/T₁) + νR·ln(V₂/V₁)"],"key":"熵是状态量：算不可逆过程的 ΔS，人为设计一条同初末态的可逆路径来计算。"},
  "熵增加原理": {"tag":"热力学 · 13.4","def":"孤立系统内发生的过程，熵永不减少：可逆过程熵不变，不可逆过程熵增加。","fx":["ΔS_孤立 ≥ 0","热传导 ΔS = Q(1/T_冷 − 1/T_热) > 0"],"key":"熵增是过程方向的判据——第二定律的定量表述；「熵」统计意义：Ω（微观态数）越大熵越大。"},
  "相对性原理": {"tag":"狭义相对论 · 14.1","def":"物理定律在一切惯性系中形式相同——力学相对性原理推广到全部物理（包括电磁学）。","fx":["一切惯性系平权","无法用惯性系内的实验测出自身的绝对运动"],"key":"相对性原理否定「以太」这个特殊参考系，是狭义相对论两条基本假设之一。"},
  "光速不变": {"tag":"狭义相对论 · 14.1","def":"真空中光速在所有惯性系中都等于 c，与光源和观察者的运动无关。","fx":["c ≈ 3×10⁸ m/s","与伽利略速度合成 v′ = v − u 直接冲突"],"key":"光速不变迫使时空观变革：时间膨胀、长度收缩都是它的逻辑后果。"},
  "洛伦兹变换": {"tag":"狭义相对论 · 14.2","def":"同一事件在两个惯性系中的时空坐标变换关系，取代伽利略变换。","fx":["x′ = γ(x − ut)","t′ = γ(t − ux/c²)","y′ = y，z′ = z"],"key":"低速极限 γ→1 时退化为伽利略变换——新理论必须包含旧理论作为极限情形。"},
  "洛伦兹因子": {"tag":"狭义相对论 · 14.2","def":"相对论中反复出现的膨胀因子，随速度增大而增大。","fx":["γ = 1/√(1 − u²/c²) ≥ 1","u = 0.6c 时 γ = 1.25；u = 0.8c 时 γ ≈ 1.67"],"key":"u≪c 时 γ≈1，一切相对论效应消失；u→c 时 γ→∞，所以实物不能达到光速。"},
  "同时的相对性": {"tag":"狭义相对论 · 14.3","def":"一个惯性系中同时（不同地）发生的两事件，在另一惯性系中看一般不同时。","fx":["由 t′ = γ(t − ux/c²)：Δt = 0 但 Δx ≠ 0 → Δt′ = −γuΔx/c² ≠ 0"],"key":"同地同时才是绝对的；「同时」本身依赖于参考系——这是与日常经验冲突最大的结论。"},
  "时间膨胀": {"tag":"狭义相对论 · 14.3","def":"运动的钟变慢：发生在某惯性系同一地点的两事件时间间隔（固有时）最短。","fx":["Δt = γΔt₀","Δt₀ 为固有时（同地事件间隔）"],"key":"固有时必须「同地」。双生子佯谬、μ 子寿命延长都是时间膨胀的验证。"},
  "长度收缩": {"tag":"狭义相对论 · 14.3","def":"沿运动方向的长度缩短：静止系中的长度（固有长度）最长。","fx":["l = l₀/γ = l₀√(1−u²/c²)","垂直于运动方向长度不变"],"key":"测运动杆长度必须两端「同时」读数——同时的相对性导致长度收缩。"},
  "固有时": {"tag":"狭义相对论 · 14.3","def":"在事件发生地同一地点用同一只钟测出的时间间隔，是所有惯性系中最短的。","fx":["Δt₀ ≤ Δt（任何其他惯性系）","判断：两事件是否发生在同一空间位置"],"key":"做题第一步永远是问：哪个系测的是固有时？谁的钟只走一个数？"},
  "固有长度": {"tag":"狭义相对论 · 14.3","def":"在与物体相对静止的参考系中测得的长度，是所有参考系中最长的。","fx":["l₀ ≥ l（任何运动系）","l = l₀√(1−u²/c²)"],"key":"「谁跟物体一起静止，谁测的就是固有长度」——飞船乘客测飞船是原长。"},
  "相对论质量": {"tag":"狭义相对论 · 14.4","def":"质量随速度增大：m = γm₀。由此动量形式修正为 p = γm₀v。","fx":["m = m₀/√(1−v²/c²)","p = mv = γm₀v"],"key":"v→c 时 m→∞，需要的力无穷大——有静质量的物体无法加速到光速。"},
  "质能关系": {"tag":"狭义相对论 · 14.4","def":"质量与能量等价：任何能量变化都对应质量变化。","fx":["E = mc²","E₀ = m₀c²（静能）","Ek = mc² − m₀c² = (γ−1)m₀c²"],"key":"核反应 ΔE = Δm·c²：质量亏损释放能量，1 g 质量 ≈ 9×10¹³ J。"},
  "静能": {"tag":"狭义相对论 · 14.4","def":"物体静止时就具有的能量，是相对论揭示的全新能量形式。","fx":["E₀ = m₀c²","总能 E = E₀ + Ek","能量动量关系 E² = p²c² + m₀²c⁴"],"key":"光子 m₀ = 0 → E = pc；这条关系是处理光子问题（康普顿散射等）的钥匙。"},
  "黑体辐射": {"tag":"量子物理 · 15.1","def":"能完全吸收一切入射电磁波的物体（黑体）的热辐射，其能谱分布只与温度有关。经典理论在高频段发散（紫外灾难）。","fx":["斯忒藩定律 M = σT⁴","普朗克公式拟合全部实验曲线"],"key":"黑体不是「不发光的黑东西」——它是最好的吸收体也是最好的辐射体（如太阳可近似为黑体）。"},
  "维恩位移定律": {"tag":"量子物理 · 15.1","def":"黑体辐射能谱峰值对应的波长与温度成反比：温度越高，峰值波长越短。","fx":["λ_m·T = b ≈ 2.898×10⁻³ m·K"],"key":"应用：由太阳光谱峰值 λ_m ≈ 500 nm 估算太阳表面温度约 5800 K；铁水颜色由红变白即此律。"},
  "能量子": {"tag":"量子物理 · 15.1","def":"普朗克为解释黑体辐射提出的假设：振子能量只能取最小单位 ε₀ 的整数倍，能量不连续。","fx":["ε₀ = hν","E = n·hν（n = 0,1,2…）"],"key":"「能量一份一份地交换」是量子论的起点——普朗克常数 h 从此登场。"},
  "普朗克常数": {"tag":"量子物理 · 15.1","def":"量子世界的基本常量，能量子与频率的比例系数。","fx":["h ≈ 6.63×10⁻³⁴ J·s","常用组合 hc ≈ 1240 eV·nm","ħ = h/2π"],"key":"记 hc = 1240 eV·nm 可秒算光子能量：500 nm 绿光 ≈ 2.48 eV。"},
  "光电效应": {"tag":"量子物理 · 15.2","def":"光照射金属表面逸出电子的现象。其实验规律（截止频率、瞬时性、光电子数正比光强）只有光子说能解释。","fx":["hν = W + ½mv_m²","ν₀ = W/h（红限频率）"],"key":"三大经典困难：存在红限、瞬时性、最大初动能只与频率有关——全部指向「光是一份一份的」。"},
  "红限频率": {"tag":"量子物理 · 15.2","def":"恰好能产生光电效应的最低入射光频率，由金属逸出功决定。","fx":["ν₀ = W/h","对应红限波长 λ₀ = hc/W"],"key":"ν < ν₀ 时，无论光多强、照多久都没有光电子——波动说无法解释这一点。"},
  "逸出功": {"tag":"量子物理 · 15.2","def":"电子从金属表面逸出所需的最小能量，是金属材料的固有属性。","fx":["W = hν₀","常见金属 W 约 2~5 eV"],"key":"同一金属逸出功固定；不同金属红限不同。查表题直接给 W 或给 ν₀ 换算。"},
  "遏止电压": {"tag":"量子物理 · 15.2","def":"使光电流恰好减为零的反向电压，用于测量光电子最大初动能。","fx":["eU_a = ½mv_m² = hν − W","U_a 与 ν 成线性关系，斜率 h/e"],"key":"U_a-ν 图线斜率测普朗克常数（密立根实验）；光强只影响饱和电流、不影响遏止电压。"},
  "康普顿散射": {"tag":"量子物理 · 15.2","def":"X 射线被物质散射后波长变长的现象，用光子与自由电子弹性碰撞解释。","fx":["Δλ = λ_c(1 − cosθ) = 2λ_c·sin²(θ/2)","λ_c = h/(m₀c) ≈ 0.00243 nm","θ = 180° 时 Δλ 最大 = 2λ_c"],"key":"Δλ 只随散射角变、与材料无关——光子具有动量 p = h/λ 的直接证据。"},
  "玻尔能级": {"tag":"量子物理 · 15.3","def":"玻尔氢原子理论：电子只能在一系列分立轨道上运动，能量取分立值；跃迁时吸收或辐射光子。","fx":["E_n = −13.6/n² eV","hν = E_m − E_n","r_n = n²a₀，a₀ = 0.529 Å"],"key":"三条假设：定态、量子化条件（mvr = nħ）、跃迁频率条件。氢光谱线系全部由此导出。"},
  "德布罗意波": {"tag":"量子物理 · 15.4","def":"实物粒子也有波动性（物质波）：运动粒子的波长与动量成反比。","fx":["λ = h/p = h/(mv)","E_k 加速电子：λ = h/√(2m₀eU) ≈ 1.225/√U nm"],"key":"戴维孙-革末电子衍射实验证实；微观粒子「测不准」的根源正是波粒二象性。"},
  "不确定关系": {"tag":"量子物理 · 15.4","def":"微观粒子的位置与动量不能同时精确确定，是波粒二象性的必然结果，与测量技术无关。","fx":["Δx·Δp_x ≥ ħ/2","能量时间版 ΔE·Δt ≥ ħ/2"],"key":"不是「仪器不够好」——是微观粒子的固有属性；估算题常取 Δx·Δp ≈ h 或 ħ 量级。"},
  "薛定谔方程": {"tag":"量子物理 · 15.5","def":"波函数满足的波动方程，地位相当于量子力学中的牛顿第二定律。","fx":["定态形式：Ĥψ = Eψ","一维：−(ħ²/2m)·d²ψ/dx² + Vψ = Eψ","无限深势阱解出 E_n = n²h²/(8mL²)"],"key":"给定势能 V(x) 解方程 → 能量自动分立（量子化是「解出来的」不是「假设的」）。"},
  "BF": {"tag":"串 · 4.3","def":"Brute-Force 朴素模式匹配算法：主串指针 i 与模式串指针 j 同步比较，失配时 i 回退、j 归零重来。","fx":["最好 O(n+m)（首字符就失配）","最坏 O(n×m)（如主串 aaa…a 配 aab）"],"key":"失配时主串指针回退是 BF 低效根源；KMP 的改进点就是「主串 i 永不回退」。"},
  "nextval": {"tag":"串 · 4.3","def":"KMP 算法的优化 next 数组：失配时若模式串 j 位字符等于 next[j] 位字符，则继续往前跳，避免无效比较。","fx":["nextval[1] = 0","若 p[j] == p[next[j]]：nextval[j] = nextval[next[j]]","否则 nextval[j] = next[j]"],"key":"考法固定：先算 next（最长相等前后缀长度+1），再按规则修正成 nextval——注意 1 号位特殊记 0。"},
  "数组同构": {"tag":"数组和广义表 · 5.1","def":"数组中所有数据元素类型相同、结构固定，这是数组区别于广义表的本质特征。","fx":["元素类型一致","维数与每维长度一经定义不可改变"],"key":"数组只有存取和修改两种基本操作——不能插入删除，因为结构固定。"},
  "行序为主序": {"tag":"数组和广义表 · 5.3","def":"多维数组按行优先存储：先存第 1 行所有元素，再存第 2 行……C 语言采用。","fx":["二维 Loc(a_ij) = Loc(a_11) + [(i−1)×m + (j−1)]×L","三维推广：先乘高位维数"],"key":"口诀「行主序，行优先；下标越靠右变得越快」——C 语言默认行主序。"},
  "列序为主序": {"tag":"数组和广义表 · 5.3","def":"多维数组按列优先存储：先存第 1 列所有元素，再存第 2 列……FORTRAN/MATLAB 采用。","fx":["二维 Loc(a_ij) = Loc(a_11) + [(j−1)×n + (i−1)]×L"],"key":"与行主序对照记忆：把 i 和 j 的角色互换即可。题目给「按列存储」时务必换公式。"},
  "对称矩阵压缩": {"tag":"数组和广义表 · 5.4","def":"n 阶对称矩阵只存下三角（含对角线）元素，用一维数组存放。","fx":["存储单元数 = n(n+1)/2","下三角 i ≥ j：k = i(i−1)/2 + j − 1（下标从 1 起）","上三角 i < j：先交换 i、j 再用下式"],"key":"对称矩阵 a_ij = a_ji：访问上三角时先换成对称的下三角位置再查表。"},
  "三角矩阵": {"tag":"数组和广义表 · 5.4","def":"上（下）三角区域以外全是同一常数的矩阵，压缩存储 = 三角区元素 + 1 个常数单元。","fx":["存储单元数 = n(n+1)/2 + 1","下三角阵 i ≥ j：k = i(i−1)/2 + j − 1","i < j（常数区）：k = n(n+1)/2（最后一格）"],"key":"比对、称矩阵多一个常数存储位；判定 i、j 关系选公式是易错点。"},
  "三对角矩阵": {"tag":"数组和广义表 · 5.4","def":"非零元素集中在主对角线及其上下各一条对角线上的矩阵（|i−j| ≤ 1）。","fx":["k = 2(i−1) + (j−1)（下标从 1 起）","非零元总数 3n − 2"],"key":"推导思路：第 i 行之前有 3(i−1)−1 个元素 + 行内偏移 j−i+1，合并即公式。"},
  "稀疏矩阵": {"tag":"数组和广义表 · 5.4","def":"非零元个数远少于总元素且分布无规律的矩阵，为节省空间只存非零元。","fx":["稀疏因子 δ = t/(m×n)，通常 δ ≤ 0.05 视为稀疏"],"key":"压缩存储两大阵营：三元组顺序表（含行逻辑链接）与十字链表。"},
  "三元组表": {"tag":"数组和广义表 · 5.4","def":"用 (行号, 列号, 值) 三元组的顺序表存储稀疏矩阵，三元组按行序排列。","fx":["结点 (i, j, e)","另存总行数、总列数、非零元个数","所需单元 3(t+1)"],"key":"优点省空间、缺点难随机访问——找某行元素要顺序扫描，于是引出 rpos 辅助数组。"},
  "rpos": {"tag":"数组和广义表 · 5.4","def":"行逻辑链接顺序表中的辅助数组：rpos[r] 指示第 r 行第一个非零元在三元组表中的位置。","fx":["rpos[1] = 1（或 0，看下标约定）","rpos[r] = rpos[r−1] + 第 r−1 行非零元个数"],"key":"有了 rpos，访问任意一行非零元从 O(t) 降到 O(该行非零元数)——矩阵乘法效率大增。"},
  "十字链表": {"tag":"数组和广义表 · 5.4","def":"稀疏矩阵的链式存储：每个非零元结点同时挂在行链表和列链表上，两链正交如十字。","fx":["结点五域：row, col, val, right, down","right 指向同行下一个，down 指向同列下一个"],"key":"适合矩阵元素频繁增删的场景（如图的关联矩阵运算），比三元组灵活但每结点开销大。"},
  "快速转置": {"tag":"数组和广义表 · 5.5","def":"稀疏矩阵三元组转置的高效算法：预先算出转置后每一行（原矩阵每一列）第一个元素的目标位置，一趟扫描直接落位。","fx":["num[col] = 原矩阵第 col 列非零元个数","cpot[1] = 1；cpot[col] = cpot[col−1] + num[col−1]","时间 O(n + t)，空间 O(n)"],"key":"对比普通转置 O(n×t)：快在「目标位置一次算准」，不再逐列扫描——num/cpot 两个辅助数组是核心。"},
  "cpot": {"tag":"数组和广义表 · 5.5","def":"快速转置中的列位置数组：cpot[col] 指示原矩阵第 col 列第一个非零元在转置三元组表中应放的位置，放一个就自增。","fx":["cpot[col] = cpot[col−1] + num[col−1]","转置放置：b.data[cpot[j]] ← 该元；cpot[j]++"],"key":"cpot 本质是「各列元素在新表中的写入游标」——前缀和 + 就地自增是经典套路。"},
  "长度与深度": {"tag":"数组和广义表 · 5.6","def":"广义表的两个度量：长度 = 最外层元素个数；深度 = 括号嵌套的最大层数。","fx":["L = (a, (b, c), ()) 长度 3、深度 2","空表 () 长度 0、深度 1"],"key":"数长度只看最外层逗号；数深度看括号层数——() 本身占一层。"},
  "head/tail": {"tag":"数组和广义表 · 5.6","def":"广义表两个基本操作：head 取第一个元素（可能是原子或子表），tail 取除去首元素后剩余元素组成的表（一定是表）。","fx":["Head((a,(b,c))) = a","Tail((a,(b,c))) = ((b,c))","Head/Tail 组合可取任意深度元素"],"key":"tail 的结果永远是广义表（带括号），head 可以是原子——连续取深层元素要交替使用。"},
  "异构元素": {"tag":"数组和广义表 · 5.7","def":"广义表允许不同元素类型不同：可以是原子也可以是子表，这与数组的「同构」形成对照。","fx":["L = (1, (2,3), \"a\") 混合数值、子表、字符串","实现上靠引用类型（指针/对象）统一大小"],"key":"语言层面：C#/Java 用引用类型装异构元素，值类型装箱后进容器。"},
  "切比雪夫不等式": {"tag":"大数定律 · 5.1","def":"只凭期望与方差就能给出概率的粗略上界，不依赖分布形式。","fx":["P(|X−E X| ≥ ε) ≤ D(X)/ε²","等价式 P(|X−E(X)| < ε) ≥ 1 − D(X)/ε²"],"key":"用途是「估计界」与证明大数定律；ε 换成 kσ 形式：P(|X−μ| ≥ kσ) ≤ 1/k²。"},
  "依概率收敛": {"tag":"大数定律 · 5.1","def":"随机变量序列的取值越来越「几乎肯定」地贴近某个常数。","fx":["对任意 ε>0：P(|Xₙ−a| < ε) → 1（n→∞）","记作 Xₙ --P--> a"],"key":"与微积分收敛不同：允许「偶尔偏出去」，只要求偏出去的概率趋于 0。"},
  "切比雪夫大数定律": {"tag":"大数定律 · 5.1","def":"独立随机变量序列（方差有公共上界）的算术平均值依概率收敛到期望的平均值。","fx":["(1/n)ΣXᵢ --P--> (1/n)ΣE(Xᵢ)"],"key":"三条大数定律中条件最一般：只要求方差一致有界，不要求同分布。"},
  "伯努利大数定律": {"tag":"大数定律 · 5.1","def":"n 重伯努利试验中事件发生的频率依概率收敛到该事件的概率。","fx":["fₙ(A) = n_A/n --P--> p"],"key":"「频率稳定于概率」的理论证明——概率的统计定义由此有了根据。"},
  "辛钦大数定律": {"tag":"大数定律 · 5.1","def":"独立同分布、期望存在（不要求方差存在）的序列，样本均值依概率收敛到总体期望。","fx":["X̄ --P--> μ"],"key":"三个大数定律对比：切比雪夫（独立+方差有界）、伯努利（特例）、辛钦（同分布+期望存在）——辛钦条件最贴合「测量平均」直觉。"},
  "中心极限定理": {"tag":"大数定律 · 5.2","def":"大量独立随机因素的影响之和近似服从正态分布——正态分布普适性的理论根源。","fx":["ΣXᵢ 近似 N(nμ, nσ²)","标准化：(ΣXᵢ − nμ)/(σ√n) 近似 N(0,1)"],"key":"解题套路：求 E、D → 标准化 → 查 Φ 表；关键词「近似」「至少/至多」。"},
  "林德伯格–列维": {"tag":"大数定律 · 5.2","def":"独立同分布中心极限定理（林德伯格-列维定理）：独立同分布、方差存在的序列，其和标准化后极限分布为标准正态。","fx":["(ΣXᵢ − nμ)/(σ√n) --d--> N(0,1)"],"key":"用得最多的一个中心极限定理，条件就两条：独立同分布 + 方差存在。"},
  "棣莫弗–拉普拉斯": {"tag":"大数定律 · 5.2","def":"二项分布的正态逼近：n 很大时 B(n,p) 近似 N(np, npq)。","fx":["X ~ B(n,p) ≈ N(np, np(1−p))","P(a<X≤b) ≈ Φ((b−np)/√npq) − Φ((a−np)/√npq)"],"key":"是中心极限定理在二项分布上的特例；n 大、p 不极端时效果好。"},
  "连续性修正": {"tag":"大数定律 · 5.2","def":"用连续的正态分布逼近离散的二项分布时，整数端点向外扩半个单位以提高精度。","fx":["P(X = k) ≈ Φ((k+0.5−np)/σ) − Φ((k−0.5−np)/√npq)","P(X ≤ k) ≈ Φ((k+0.5−np)/√npq)"],"key":"点概率必须 ±0.5 修正；区间概率是否修正看题目精度要求。"},
  "总体": {"tag":"数理统计 · 6.1","def":"研究对象的某个数量指标 X 的全体取值的集合，把总体看作随机变量 X。","fx":["总体 = 随机变量 X 的分布"],"key":"统计学里「总体」不是一堆实物，而是一个分布——抽样的目的是推断这个分布。"},
  "样本": {"tag":"数理统计 · 6.1","def":"从总体中抽取的 n 个个体 X₁,…,Xₙ，要求相互独立且与总体同分布（简单随机样本）。","fx":["独立同分布：f(x₁,…,xₙ) = ∏f(xᵢ)"],"key":"「样本」在抽之前是随机变量、抽完之后是一组具体数（样本值）——上下文要分清。"},
  "统计量": {"tag":"数理统计 · 6.1","def":"不含任何未知参数的样本函数，是加工样本数据的工具。","fx":["g(X₁,…,Xₙ) 且不含未知参数","X̄、S² 是统计量；含 μ、σ² 的式子不是"],"key":"判断口诀：式子里出现未知参数（μ、σ、θ）就不是统计量。"},
  "样本均值": {"tag":"数理统计 · 6.1","def":"样本的算术平均，是最常用的统计量，用来估计总体期望。","fx":["X̄ = (1/n)ΣXᵢ","E(X̄) = μ，D(X̄) = σ²/n","正态总体下 X̄ ~ N(μ, σ²/n)"],"key":"方差除以 n——样本均值比单个观测「稳」n 倍，这是用平均代替单次测量的数学理由。"},
  "样本方差": {"tag":"数理统计 · 6.1","def":"样本偏离其均值程度的度量，注意分母是 n−1 而不是 n。","fx":["S² = 1/(n−1)·Σ(Xᵢ−X̄)²","计算式 S² = 1/(n−1)·[ΣXᵢ² − nX̄²]"],"key":"分母取 n−1 才使 E(S²) = σ²（无偏）；用 n 会系统性低估方差。"},
  "无偏性": {"tag":"数理统计 · 6.1","def":"估计量的期望等于被估参数——多次抽样平均来看不偏高也不偏低。","fx":["E(θ̂) = θ","E(X̄) = μ ✓，E(S²) = σ² ✓（这就是 n−1 的来历）"],"key":"证明无偏性就是算期望；样本二阶中心矩（分母 n）不是 σ² 的无偏估计。"},
  "χ²分布": {"tag":"数理统计 · 6.2","def":"n 个独立标准正态变量的平方和的分布，用于方差推断。","fx":["χ² = X₁²+…+Xₙ² ~ χ²(n)","E = n，D = 2n","可加性：χ²(m)+χ²(n) = χ²(m+n)"],"key":"构造套路：见「正态平方和」想 χ²；样本方差统计量 (n−1)S²/σ² ~ χ²(n−1)。"},
  "t分布": {"tag":"数理统计 · 6.2","def":"标准正态与 χ² 分布（除自由度）平方根的比，用于小样本均值推断。","fx":["T = Z/√(χ²(n)/n) ~ t(n)","X̄ 标准化但 σ 未知：(X̄−μ)/(S/√n) ~ t(n−1)"],"key":"t 分布是「σ 未知用 S 顶替」的产物；n→∞ 时趋于标准正态。"},
  "F分布": {"tag":"数理统计 · 6.2","def":"两个独立 χ² 变量各除自由度后的比，用于两总体方差比较与方差分析。","fx":["F = (χ²(m)/m)/(χ²(n)/n) ~ F(m,n)","1/F ~ F(n,m)","两正态总体：S₁²/σ₁² ÷ S₂²/σ₂² ~ F(n₁−1, n₂−1)"],"key":"倒数性质 F_{1−α}(m,n) = 1/F_α(n,m) 查表必备。"},
  "抽样分布定理": {"tag":"数理统计 · 6.2","def":"正态总体下样本均值与样本方差的分布结论，是参数估计与假设检验的地基。","fx":["X̄ ~ N(μ, σ²/n)","(n−1)S²/σ² ~ χ²(n−1)","X̄ 与 S² 相互独立（正态总体特有！）"],"key":"「X̄ 与 S² 独立」只对正态总体成立——t 统计量的构造恰好依赖这条。"},
  "矩估计": {"tag":"参数估计 · 7.1","def":"用样本矩替换总体矩，解出参数的估计方法：几个未知参数就列几个矩方程。","fx":["一阶矩：X̄ = E(X)","二阶矩：(1/n)ΣXᵢ² = E(X²)","常用：E(X²) = D(X)+[E(X)]²"],"key":"步骤：写总体矩（含 θ）→ 用样本矩替换 → 解方程得 θ̂。"},
  "极大似然估计": {"tag":"参数估计 · 7.1","def":"选使样本出现概率（似然函数）最大的参数值作为估计——「最像产生这批数据的参数」。","fx":["L(θ) = ∏f(xᵢ;θ)","取对数 ln L → 求导 = 0 → 解出 θ̂","导数无解时按单调性取边界（如均匀分布 θ̂ = max xᵢ）"],"key":"标准四步：写 L → 取 ln → 求导置零 → 检验；均匀分布这类「参数出现在区间端点」的题不能求导，直接看 L 单调性。"},
  "似然函数": {"tag":"参数估计 · 7.1","def":"把样本联合密度/分布律看作参数的函数——固定样本、变动参数。","fx":["连续型 L(θ) = ∏f(xᵢ;θ)","离散型 L(θ) = ∏P(X=xᵢ;θ)"],"key":"似然函数与联合概率密度「数值相同、视角不同」：自变量从样本变成了参数。"},
  "有效性": {"tag":"参数估计 · 7.2","def":"比较两个无偏估计量：方差更小者更有效（估计更集中）。","fx":["若 D(θ̂₁) < D(θ̂₂) 则 θ̂₁ 更有效"],"key":"有效性比较的前提是两个都是无偏估计——先验证无偏再比方差。"},
  "一致性": {"tag":"参数估计 · 7.2","def":"样本量趋于无穷时估计量依概率收敛到真参数——样本越多越好。","fx":["θ̂ --P--> θ（n→∞）"],"key":"大数定律保证样本矩是一致估计；证明一致性常用切比雪夫不等式。"},
  "置信区间": {"tag":"参数估计 · 7.3","def":"以给定置信水平 1−α 包含真参数的随机区间，区间估计的最终产物。","fx":["P(θ₁ < θ < θ₂) = 1 − α","σ 已知均值区间：X̄ ± z_{α/2}·σ/√n","σ 未知：X̄ ± t_{α/2}(n−1)·S/√n"],"key":"置信水平含义：反复抽样构造的区间中约 1−α 比例盖住真参数，不是「参数落在该区间的概率」。"},
  "置信水平": {"tag":"参数估计 · 7.2","def":"置信区间盖住真参数的概率 1−α，常取 0.95、0.99。","fx":["α 越小 → 区间越宽","n 越大 → 区间越窄"],"key":"水平与精度是矛盾体：同样本下「更可信」必然「更宽」，要两者兼得只能加大样本量。"},
  "枢轴量": {"tag":"参数估计 · 7.3","def":"构造置信区间的核心工具：含待估参数与样本、但分布与参数无关的量。","fx":["σ 已知：Z = (X̄−μ)/(σ/√n) ~ N(0,1)","σ 未知：T = (X̄−μ)/(S/√n) ~ t(n−1)","方差：χ² = (n−1)S²/σ² ~ χ²(n−1)"],"key":"区间估计三步：选枢轴量 → 写出双侧分位区间 → 反解出参数范围。"},
  "t分布临界值": {"tag":"参数估计 · 7.3","def":"t 分布双侧分位数 t_{α/2}(n)，用于 σ 未知的均值区间与 t 检验。","fx":["P(|T| > t_{α/2}(n)) = α","0.95 置信水平：查 t_{0.025}(n−1)"],"key":"查表时自由度看清：单样本均值问题永远是 n−1，两样本方差相等时是 n₁+n₂−2。"},
  "原假设": {"tag":"假设检验 · 8.1","def":"被检验、且受「不轻易否定」保护的假设 H₀；拒绝它需要足够强的样本证据。","fx":["H₀：μ = μ₀（通常把「无差异/维持现状」设为 H₀）"],"key":"设 H₀ 的经验法则：把「想推翻的结论」设为备择假设，等号永远放在 H₀ 里。"},
  "备择假设": {"tag":"假设检验 · 8.1","def":"与原假设相对立、研究者希望获得支持的假设 H₁，决定检验的单双侧。","fx":["H₁: μ ≠ μ₀ → 双侧检验","H₁: μ > μ₀ → 右侧检验","H₁: μ < μ₀ → 左侧检验"],"key":"单双侧由 H₁ 的不等号方向决定，拒绝域的形状随之不同。"},
  "检验统计量": {"tag":"假设检验 · 8.1","def":"由样本构造、在 H₀ 为真时分布已知的量，是检验的计算核心。","fx":["σ 已知：U = (X̄−μ₀)/(σ/√n) ~ N(0,1)","σ 未知：T = (X̄−μ₀)/(S/√n) ~ t(n−1)","方差：χ² = (n−1)S²/σ₀² ~ χ²(n−1)"],"key":"与区间估计的枢轴量一一对应——检验就是「区间估计的对偶」。"},
  "显著性水平": {"tag":"假设检验 · 8.1","def":"犯第一类错误（弃真）的最大允许概率 α，检验前人为给定。","fx":["P(拒绝H₀ | H₀真) ≤ α","常用 α = 0.05、0.01"],"key":"α 小 → 拒绝域小 → 更难拒绝 H₀；「显著」就是「在 α 水平下拒绝 H₀」。"},
  "拒绝域": {"tag":"假设检验 · 8.1","def":"检验统计量落入其中就拒绝 H₀ 的区域，由 H₁ 的方向和 α 共同决定。","fx":["双侧：|U| > z_{α/2}","右侧：U > z_α","左侧：U < −z_α"],"key":"双侧用 α/2 分位、单侧用 α 分位——最常考的分位数选择点。"},
  "第一类错误": {"tag":"假设检验 · 8.1","def":"H₀ 为真却被拒绝的错误（弃真），其概率由显著性水平控制。","fx":["P(第一类错误) = α"],"key":"「冤枉好人」：产品明明合格却判不合格。"},
  "第二类错误": {"tag":"假设检验 · 8.1","def":"H₀ 为假却被接受的错误（取伪），概率记 β。","fx":["P(第二类错误) = β","n 固定时 α 小则 β 大，两者此消彼长"],"key":"「放过坏人」；只有增大样本量才能同时压缩 α 与 β。"},
  "U检验": {"tag":"假设检验 · 8.2","def":"正态总体方差已知时检验均值的检验，统计量服从标准正态。","fx":["U = (X̄−μ₀)/(σ/√n) ~ N(0,1)","双侧拒绝域 |U| > z_{α/2}"],"key":"见到「正态 + σ 已知 + 检验 μ」直接上 U 统计量。"},
  "t检验": {"tag":"假设检验 · 8.2","def":"正态总体方差未知时检验均值，用 S 顶替 σ，统计量服从 t 分布。","fx":["T = (X̄−μ₀)/(S/√n) ~ t(n−1)","双侧拒绝域 |T| > t_{α/2}(n−1)"],"key":"与 U 检验的唯一区别：σ 换成 S、正态表换成 t 表（自由度 n−1）。"},
  "χ²检验": {"tag":"假设检验 · 8.2","def":"正态总体检验方差 σ²（均值未知）的检验。","fx":["χ² = (n−1)S²/σ₀² ~ χ²(n−1)","双侧拒绝域：χ² < χ²_{1−α/2} 或 χ² > χ²_{α/2}"],"key":"χ² 分布不对称，双侧检验要查两个分位点——别像正态那样对称写。"},
  "F检验": {"tag":"假设检验 · 8.2","def":"比较两正态总体方差是否相等的检验，是两样本 t 检验的前置步骤。","fx":["F = S₁²/S₂² ~ F(n₁−1, n₂−1)（H₀: σ₁² = σ₂²）","双侧拒绝域 F < F_{1−α/2} 或 F > F_{α/2}"],"key":"习惯把较大的样本方差放分子，配合 F 表只查右尾；方差齐性通过后才做两样本 t 检验。"},
  "单因素方差分析": {"tag":"方差分析 · 9.1","def":"检验一个因素的不同水平对指标均值有无显著影响，本质是多个正态总体均值相等的检验。","fx":["H₀: μ₁ = μ₂ = … = μ_r","总平方和 S_T = S_A（组间）+ S_E（组内）","F = S_A/(r−1) ÷ S_E/(n−r) ~ F(r−1, n−r)"],"key":"思想：若各水平无差异，组间变异应与组内变异「差不多大」；F 明显大于 1 则拒绝。"},
  "组间平方和": {"tag":"方差分析 · 9.1","def":"各组均值与总均值的偏差平方和，反映因素不同水平造成的变异。","fx":["S_A = Σn_j(X̄_j − X̄)²","自由度 r−1（r 为水平数）"],"key":"组间平方和÷自由度 = 组间均方 MSA，是 F 统计量的分子。"},
  "组内平方和": {"tag":"方差分析 · 9.1","def":"每个观测与本组均值偏差平方和的总和，反映随机误差造成的变异。","fx":["S_E = ΣΣ(X_ij − X̄_j)²","自由度 n−r"],"key":"S_E 是纯随机噪音的度量，做分母；S_T = S_A + S_E 的分解恒等式是整张方差分析表的骨架。"},
  "均方": {"tag":"方差分析 · 9.1","def":"平方和除以其自由度，使组间与组内变异可比较。","fx":["MS_A = S_A/(r−1)","MS_E = S_E/(n−r)","F = MS_A/MS_E"],"key":"为什么要除自由度：平方和随项数自然增大，除掉自由度才是「平均每个自由度的变异」。"},
  "交互作用": {"tag":"方差分析 · 9.1","def":"双因素试验中，两因素联合作用超出各自单独作用之和的部分。","fx":["总平方和分解 S_T = S_A + S_B + S_{A×B} + S_E","检验交互作用需重复试验（否则无误差项可分）"],"key":"有交互作用时不能孤立谈某因素的主效应——先看 A×B 是否显著，再分析主效应。"},
  "最小二乘法": {"tag":"回归分析 · 9.2","def":"选择参数使残差平方和最小的参数估计方法，一元线性回归求系数的标准做法。","fx":["Q = Σ(yᵢ − a − bxᵢ)² 最小","b̂ = L_xy/L_xx = Σ(xᵢ−x̄)(yᵢ−ȳ)/Σ(xᵢ−x̄)²","â = ȳ − b̂x̄（回归直线必过 (x̄,ȳ)）"],"key":"对 a、b 求偏导置零即得正规方程；「直线过均值点」是快速检验计算正确性的办法。"},
  "回归系数": {"tag":"回归分析 · 9.2","def":"回归方程 ŷ = a + bx 中的斜率 b，表示 x 每增加一个单位 y 平均变化 b。","fx":["b̂ = L_xy/L_xx","符号与相关系数 r 相同"],"key":"b 的符号直接反映正/负相关；显著性检验通过之前，b 只是数字游戏。"},
  "相关系数": {"tag":"回归分析 · 9.2","def":"度量两个变量线性相关密切程度的量。","fx":["r = L_xy/√(L_xx·L_yy)","|r| ≤ 1；|r|→1 线性关系越强","r 与回归系数关系：b̂ = r·√(L_yy/L_xx)"],"key":"r = 0 只说明没有线性关系，不代表没有关系（可能有曲线关系）——「不相关 ≠ 独立」对一般变量成立。"},
  "回归显著性检验": {"tag":"回归分析 · 9.2","def":"检验回归方程整体是否有意义：H₀: b = 0（x 对 y 无线性影响）。","fx":["F = U/Q·(n−2) ~ F(1, n−2)，U = 回归平方和，Q = 剩余平方和","也可用 t 检验或相关系数检验：|r| > r_α(n−2)"],"key":"一元回归中 F 检验、t 检验、r 检验三者等价——过任意一个即回归显著。"},
  "R 语言": {"tag":"R 软件 · 10.1","def":"面向统计计算与绘图的开源语言环境，统计课实验的标配工具。","fx":["赋值用 <- 或 =","一切皆向量：标量是长度 1 的向量","c() 拼接，seq()/rep() 生成序列"],"key":"R 的索引从 1 开始（与 Python 的 0 起始相反）——初学最容易踩的坑。"},
  "向量": {"tag":"R 软件 · 10.1","def":"R 中最基本的数据结构：同一类型元素的有序集合。","fx":["x <- c(1, 3, 5, 7)","逻辑下标：x[x > 3] 取出满足条件的元素","向量化运算：x*2 + 1 对每个元素同时运算"],"key":"R 的灵魂是向量化：尽量不用循环，统计函数直接吃整个向量。"},
  "mean": {"tag":"R 软件 · 10.2","def":"求样本均值的函数。","fx":["mean(x)","mean(x, trim = 0.1) 截尾均值（去两端各 10%）","mean(x, na.rm = TRUE) 忽略缺失值"],"key":"数据含 NA 时 mean 直接返回 NA——加 na.rm=TRUE 是常态操作。"},
  "sd": {"tag":"R 软件 · 10.2","def":"求样本标准差的函数，分母为 n−1（无偏版本）。","fx":["sd(x) 输出 S","注意与「除以 n 的二阶中心矩」不同","sd(x)² == var(x)"],"key":"R 的 sd/var 都用 n−1——与教材定义的样本方差一致，手算对比时别用错分母。"},
  "var": {"tag":"R 软件 · 10.2","def":"求样本方差的函数，分母 n−1；两个向量时算协方差。","fx":["var(x)","var(x, y) 或 cov(x, y) 算协方差","var(cbind(x,y)) 得协方差矩阵"],"key":"var(x) = sd(x)²；区分「总体方差公式」与「样本方差公式」时再谈 n 还是 n−1。"},
  "hist": {"tag":"R 软件 · 10.2","def":"画直方图：观察数据分布形状的第一选择。","fx":["hist(x)","hist(x, breaks = 20, freq = FALSE) 密度刻度","叠加曲线：lines(density(x))"],"key":"直方图看三件事：对称性、峰数、离群点；freq=FALSE 才能和密度曲线叠加。"},
  "boxplot": {"tag":"R 软件 · 10.2","def":"画箱线图：中位数、四分位数与离群点一图看全。","fx":["boxplot(x)","boxplot(y ~ group) 按因子分组比较","箱体 = IQR，须线默认 1.5×IQR"],"key":"箱外点即疑似离群值；多组并列箱线图是方差分析前的标准探查步骤。"},
  "qqnorm": {"tag":"R 软件 · 10.2","def":"画正态 Q-Q 图：检验数据是否近似正态的图形方法。","fx":["qqnorm(x); qqline(x)","点近似落在直线上 → 正态性可接受","S 形提示厚尾/薄尾，弯弓形提示偏态"],"key":"图法直观但主观，正式检验配合 shapiro.test——「图粗筛、检验定案」。"},
  "t.test": {"tag":"R 软件 · 10.3","def":"t 检验与均值的 t 置信区间，一个函数全包。","fx":["t.test(x, mu = 5) 单样本","t.test(x, y, var.equal = TRUE) 两独立样本","t.test(x, y, paired = TRUE) 配对样本"],"key":"输出看两样：p 值（< α 则拒绝 H₀）与 95% 置信区间（含 μ₀ 则不拒绝）——两者结论必然一致。"},
  "var.test": {"tag":"R 软件 · 10.3","def":"两正态总体方差相等性的 F 检验。","fx":["var.test(x, y)","H₀：两总体方差相等","做两样本 t 检验前先用它决定是否 var.equal = TRUE"],"key":"workflow：var.test 判方差齐性 → 决定 t.test 的 var.equal 参数——顺序不能反。"},
  "shapiro.test": {"tag":"R 软件 · 10.3","def":"Shapiro-Wilk 正态性检验，小样本（n ≤ 50 或 5000 内）最常用。","fx":["shapiro.test(x)","H₀：总体服从正态分布","p > α 时「不拒绝正态假设」"],"key":"注意假设方向反直觉：p 值大才是「好消息」（接受正态）——这是正态性检验的共同设定。"},
  "aov": {"tag":"R 软件 · 10.4","def":"方差分析函数，输出方差分析表。","fx":["aov(y ~ A) 单因素","aov(y ~ A * B) 双因素含交互","summary(fit) 查看 F 值与 p 值"],"key":"公式里 ~ 右边写因子；A*B 展开成 A+B+A:B——交互作用显著时先解释交互。"},
  "lm": {"tag":"R 软件 · 10.4","def":"线性模型函数：回归分析的核心，拟合、检验、预测一体。","fx":["fit <- lm(y ~ x)","summary(fit) 看系数与检验","predict(fit, newdata) 做预测"],"key":"summary 输出重点读：系数表（Estimate、p 值）、R²、F 检验——回归是否显著看最后一行。"},
  "p 值": {"tag":"R 软件 · 10.3","def":"在 H₀ 为真时得到「当前样本或更极端结果」的概率，是现代统计软件的检验输出标准。","fx":["p ≤ α → 拒绝 H₀（结果显著）","p > α → 不拒绝 H₀","双侧 p 值 = 两侧尾部概率之和"],"key":"p 值不是「H₀ 为真的概率」；与拒绝域法完全等价：p ≤ α ⇔ 统计量落入拒绝域。"},
  "CPU结构": {"tag":"CPU的结构和功能 · 8.1","def":"CPU 由运算器（ALU、寄存器）和控制器（CU、时序电路）组成，负责取指、译码、执行、处理中断。","fx":["四大功能：指令控制、操作控制、时间控制、数据加工"],"key":"现代 CPU 还含有 Cache 与总线接口；考试画 CPU 内部结构图时先摆 ALU、CU、寄存器组三件套。"},
  "PC": {"tag":"CPU的结构和功能 · 8.1","def":"程序计数器，存放下一条要执行指令的地址。","fx":["取指后自动 +1（或加指令字长）","转移指令直接改写 PC 实现跳转"],"key":"PC 的变化规律是区分顺序/转移指令的标志；中断响应时第一件事就是把 PC 压栈保存。"},
  "IR": {"tag":"CPU的结构和功能 · 8.1","def":"指令寄存器，存放当前正在执行的指令。","fx":["取指：M(MAR)→MDR→IR","操作码 OP(IR)→CU 译码","地址码 Ad(IR) 送 MAR 或参与寻址计算"],"key":"IR 与 MDR 易混：MDR 是数据/指令进出的缓冲站，IR 只装「当前这条指令」。"},
  "MAR": {"tag":"CPU的结构和功能 · 8.1","def":"存储器地址寄存器，存放要访问的存储单元地址，位数决定可寻址空间。","fx":["MAR 位数 = 地址线条数","16 位 MAR → 可寻址 64K 单元"],"key":"「MAR 与地址总线相连、MDR 与数据总线相连」——连线关系常考。"},
  "MDR": {"tag":"CPU的结构和功能 · 8.1","def":"存储器数据寄存器，暂存从主存读出或要写入主存的数据/指令。","fx":["MDR 位数 = 数据线条数 = 存储字长","读：M(MAR)→MDR；写：MDR→M(MAR)"],"key":"主存与 CPU 之间的一切数据交换都经过 MDR——它是主存侧唯一的数据窗口。"},
  "指令周期": {"tag":"CPU的结构和功能 · 8.2","def":"CPU 取出并执行一条指令所需的全部时间，通常包含取指、间址、执行、中断四个机器周期。","fx":["指令周期 = 若干个机器周期","取指周期 + 执行周期是必备，间址/中断视需要"],"key":"不同指令指令周期不同：直接寻址访存 2 次，间接寻址访存 3 次。"},
  "机器周期": {"tag":"CPU的结构和功能 · 8.2","def":"指令周期中完成一个基本操作阶段（如取指）所需的时间，也叫 CPU 周期。","fx":["常以一次访存时间为基准","机器周期 = 若干个时钟周期（节拍）"],"key":"层级关系记牢：指令周期 ⊃ 机器周期 ⊃ 时钟周期（节拍）。"},
  "流水线": {"tag":"CPU的结构和功能 · 8.4","def":"把指令执行分成若干段，多条指令像流水一样重叠执行，提高吞吐率。","fx":["k 段流水执行 n 条指令：T = (k + n − 1)Δt","理想加速比 = k（段数）"],"key":"流水线的考点三件套：画时空图、算吞吐率/加速比、识别三种冲突（结构/数据/控制）。"},
  "吞吐率": {"tag":"CPU的结构和功能 · 8.4","def":"单位时间内流水线完成的指令条数。","fx":["TP = n/((k+n−1)Δt)","极限吞吐率 TP_max = 1/Δt","Δt 取最长段的时间"],"key":"瓶颈段决定 Δt：流水线提速先优化最慢的那段，其余段再快也没用。"},
  "加速比": {"tag":"CPU的结构和功能 · 8.4","def":"不用流水与用流水完成同样任务的耗时之比。","fx":["S = kn/(k+n−1)","n→∞ 时 S → k"],"key":"n 越大加速比越接近段数 k——流水线适合大批量同构指令流。"},
  "内中断": {"tag":"CPU的结构和功能 · 8.3","def":"由 CPU 内部事件引发的中断（异常）：指令执行出错或程序自陷。","fx":["来源：除零、溢出、缺页、非法指令、软中断 INT","特点：与当前指令同步、不可屏蔽"],"key":"内中断「不可屏蔽」是判分点；外中断可被 IF 标志屏蔽（NMI 除外）。"},
  "外中断": {"tag":"CPU的结构和功能 · 8.3","def":"由 CPU 外部设备发出的中断请求：I/O 完成、定时器到点等。","fx":["来源：INTR（可屏蔽）、NMI（不可屏蔽）","特点：随机发生、与当前指令异步"],"key":"内外中断的根本区别在「请求源位置」；判题时先问：这个事件是 CPU 内部产生的吗？"},
  "中断判优": {"tag":"CPU的结构和功能 · 8.3","def":"多个中断源同时请求时按优先级决定先响应谁。","fx":["硬件排队器：链式/计数器定时查询","软件查询：按查询顺序定优先级","一般规律：故障 > DMA > I/O；高速设备优先于低速"],"key":"判优发生在响应阶段；屏蔽字改变的是响应优先级的实际效果，可考「屏蔽字重排服务次序」。"},
  "中断隐指令": {"tag":"CPU的结构和功能 · 8.3","def":"CPU 响应中断时硬件自动完成的一组操作，如同执行了一条不在程序中的指令。","fx":["三步：关中断 → 保存断点（PC 压栈）→ 引出中断服务程序","全部由硬件完成，不占指令"],"key":"「隐指令」三动作必背；之后软件负责保护现场、服务、恢复现场、开中断返回。"},
  "微操作": {"tag":"控制单元的功能 · 9.1","def":"计算机中最基本的、不可再分的操作，如寄存器间的数据传送、ALU 一次运算。","fx":["例：PC→MAR、M(MAR)→MDR、(PC)+1→PC","一条指令的执行 = 一串有序微操作"],"key":"层级：程序 ⊃ 指令 ⊃ 微程序 ⊃ 微指令 ⊃ 微操作——记熟链条即可秒答层次题。"},
  "微命令": {"tag":"控制单元的功能 · 9.1","def":"控制单元发出的、直接打开某个数据通路门的控制信号，一个微命令对应一个微操作。","fx":["相容微命令：可同时发出（如两个不同寄存器输出）","互斥微命令：不能同时发出（如同一总线的两个输入源）"],"key":"相容/互斥是字段编码的依据：互斥的放同一字段译码省位数。"},
  "控制单元": {"tag":"控制单元的功能 · 9.1","def":"产生全部微命令序列的部件，即 CPU 的「指挥中心」。","fx":["输入：指令操作码、时序信号、状态标志、中断信号","输出：全部控制信号（微命令）"],"key":"两种实现：硬布线（快而难改）与微程序（慢但灵活）——对应 g10 两种设计。"},
  "外特性": {"tag":"控制单元的功能 · 9.2","def":"控制单元从外部看到的输入输出信号集合，是设计 CU 的出发点。","fx":["输入：时钟、IR 操作码、标志位（如零标志）、总线/中断请求","输出：CPU 内各控制信号 + 总线控制信号"],"key":"考「画 CU 外特性框图」：左边输入（指令、时序、标志、请求），右边输出控制信号。"},
  "同步控制": {"tag":"控制单元的功能 · 9.3","def":"所有微操作由统一时钟节拍控制，每个动作占用固定节拍数。","fx":["时钟周期固定，按最慢操作设计","优点：电路简单；缺点：快的操作被拖慢"],"key":"「以最慢微操作定节拍」是同步控制的固有缺点——这正是异步控制要解决的问题。"},
  "异步控制": {"tag":"控制单元的功能 · 9.3","def":"微操作完成时间由操作本身决定，采用「应答」方式衔接下一步。","fx":["无统一节拍，用握手信号联络","优点：时间利用率高；缺点：控制复杂"],"key":"主存与 CPU 间常局部异步：发读命令后等「存储器完成」信号再取数。"},
  "联合控制": {"tag":"控制单元的功能 · 9.3","def":"同步与异步结合：CPU 内部微操作同步进行，与主存/外设交换信息时异步应答。","fx":["大部分微操作按节拍","访存等操作按应答"],"key":"实际机器几乎都采用联合控制——「中央同步、局部异步」八个字。"},
  "时序": {"tag":"控制单元的功能 · 9.3","def":"微操作在时间上的先后顺序安排，由节拍发生器产生。","fx":["一个机器周期含若干节拍 T₀、T₁、T₂…","时序图：横轴节拍、纵轴控制信号"],"key":"画时序题先问机器周期几个节拍、每个节拍发哪些微命令——按取指/执行分阶段列。"},
  "组合逻辑设计": {"tag":"控制单元的设计 · 10.1","def":"用门电路和触发器直接实现微命令发生器：把指令、节拍、状态译码组合出每个控制信号。","fx":["控制信号 = Σ（机器周期 × 节拍 × 指令）组合","设计步骤：列微操作时间表 → 写逻辑式 → 化简 → 画电路"],"key":"硬布线的本质是「把所有指令的时序需求翻译成一张布尔函数表」。"},
  "硬布线": {"tag":"控制单元的设计 · 10.1","def":"即组合逻辑控制方式：控制逻辑全部由硬件电路固定实现。","fx":["优点：速度快（RISC 采用）","缺点：指令系统改动就要重布电路"],"key":"与微程序对照记：硬布线「快、硬、适合精简指令」；微程序「慢、软、适合复杂指令（CISC）」。"},
  "微程序": {"tag":"控制单元的设计 · 10.2","def":"把每条机器指令的执行过程写成一段微程序存进控存，执行指令 = 逐条执行对应微指令。","fx":["微程序 = 微指令序列","取指微程序是公共入口，按操作码散转"],"key":"微程序概念三件套：微命令 → 微指令 → 微程序；微程序存在控存不在主存。"},
  "控制存储器": {"tag":"控制单元的设计 · 10.2","def":"存放微程序的专用存储器，位于 CPU 内部。","fx":["通常用 ROM（微程序固定）","容量 = 微指令条数 × 微指令字长"],"key":"控存 CM ≠ 主存：CM 存微指令、面向 CPU 内部；主存存机器指令、面向程序员。"},
  "CM": {"tag":"控制单元的设计 · 10.2","def":"控制存储器（Control Memory）的缩写，见「控制存储器」。","fx":["CMAR：微地址寄存器","CMDR/μIR：微指令寄存器"],"key":"控存也有自己的地址/数据寄存器 CMAR、CMDR——与主存的 MAR、MDR 对应记忆。"},
  "微指令": {"tag":"控制单元的设计 · 10.2","def":"一个节拍内并行发出的一组微命令的编码，外加顺序控制字段。","fx":["两大字段：操作控制字段 + 顺序控制字段","微指令字长 = 两字段位数之和"],"key":"算微指令字长是高频计算题：控制字段位数 + 下址字段位数（含判别位）。"},
  "直接编码": {"tag":"控制单元的设计 · 10.2","def":"微指令操作控制字段中每一位直接对应一个微命令，1 发 0 不发。","fx":["控制字段位数 = 微命令总数","优点：最快、无需译码；缺点：字太长"],"key":"直接编码位数 = 微命令个数——位数最多但速度最快。"},
  "字段编码": {"tag":"控制单元的设计 · 10.2","def":"把互斥微命令编入同一字段、经译码器输出，压缩微指令长度。","fx":["n 位字段可表示 2ⁿ − 1 个互斥微命令（留一个全 0 表示不发）","相容微命令必须放不同字段"],"key":"两条铁律：互斥才能同字段；每字段留一个「空操作」码——所以是 2ⁿ − 1 而非 2ⁿ。"},
  "微地址": {"tag":"控制单元的设计 · 10.2","def":"微指令在控存中的地址，下一条微指令的地址由顺序控制字段决定。","fx":["形成方式：下址字段直接给出 / 增量计数器 / 按操作码散转","取指后按 OP 散转到各指令微程序入口"],"key":"「散转」是按机器指令操作码形成微程序入口地址——微程序与指令系统的接口。"},
  "中断服务顺序": {"tag":"综合应用 · 11","def":"中断响应后硬件与软件分工完成服务的完整流程。","fx":["隐指令（硬件）：关中断、存断点、转服务程序","软件：保护现场 → 服务 → 恢复现场 → 开中断 → 返回"],"key":"答题模板「三硬四软」；关中断是为了可重入地保存现场，服务完再开中断。"},
  "浮点数范围": {"tag":"综合应用 · 11","def":"由阶码位数决定浮点数可表示的范围，阶码越大范围越宽。","fx":["阶码位数 p 决定范围，尾数位数 m 决定精度","最大正数 = 最大尾数 × 2^(最大阶码)"],"key":"「阶码管范围、尾数管精度」——比较两种浮点格式先拆阶码和尾数位数。"},
  "指数极值": {"tag":"综合应用 · 11","def":"浮点格式中阶码能取的最大/最小值，由阶码位数与码制决定。","fx":["补码 p+1 位阶码：−2^p ~ 2^p − 1","移码 p+1 位：同上范围，编码全 0 最小"],"key":"算范围先写阶码极值：p 位移码/补码的指数区间就是 ±2^p 附近。"},
  "尾数极值": {"tag":"综合应用 · 11","def":"规格化浮点数尾数能取的最大/最小值，决定有效数字精度。","fx":["补码规格化尾数：最大 1 − 2⁻ⁿ，最小正数 1/2","规格化要求：符号位与最高数值位相异"],"key":"规格化保证精度充分利用；补码规格化的判据「符号位 ⊕ 最高位 = 1」常考。"},
  "芯片扩展": {"tag":"综合应用 · 11","def":"用若干小容量芯片拼出大容量存储器，分位扩展、字扩展、字位同时扩展。","fx":["位扩展：并联地址线，数据线各管几位（扩字长）","字扩展：片选译码区分芯片（扩字数）","片数 = 目标容量 ÷ 单片容量"],"key":"算片数先看「位差几倍 × 字差几倍」；画连接图先分三组线：地址、数据、片选。"},
  "位扩展": {"tag":"综合应用 · 11","def":"只扩数据位数的扩展：几片芯片地址完全相同、各输出一部分数据位。","fx":["1K×4 → 1K×8：2 片位扩展","地址线并接、片选并接、数据线分开"],"key":"位扩展的芯片「同生共死」——同一个地址同时选中所有片。"},
  "字扩展": {"tag":"综合应用 · 11","def":"只扩地址空间的扩展：用高位地址译码产生片选，轮流选中不同芯片。","fx":["1K×8 → 4K×8：4 片，高 2 位地址经译码器产生 4 个片选","数据线并接、低位地址并接"],"key":"字扩展的芯片「轮流上岗」——任一时刻只有一片被选中。"},
  "RISC": {"tag":"综合应用 · 11","def":"精简指令集计算机：只保留少量常用简单指令，硬布线控制，靠编译器组合实现复杂功能。","fx":["特征：指令少、定长、Load/Store 结构、硬布线、大量通用寄存器","对比 CISC：指令多而复杂、微程序控制"],"key":"判断 RISC 特征抓四点：定长指令、硬布线、Load/Store 结构、寄存器多。"},
  "总线标准": {"tag":"综合应用 · 11","def":"总线接口的机械、电气、功能与时序规范，使不同厂商设备可互连。","fx":["常见：ISA、PCI、PCIe、USB、SATA","带宽 = 位宽 × 频率 × 每周期传输次数"],"key":"总线标准题一般考「带宽计算」或「哪种标准用于什么场景」——位宽×频率是万能式。"},
  "模型机": {"tag":"模型机 · 12","def":"教学用的简化 CPU 模型：有限的寄存器、简化的指令格式，用来演示指令执行全过程。","fx":["组成：PC、MAR、MDR、IR、AC、通用寄存器、ALU、CU","数据总线连接各部件"],"key":"模型机是第 8-10 章知识的「组装车间」：把时序、微操作、微程序全部串起来。"},
  "数据通路": {"tag":"模型机 · 12","def":"数据在各寄存器与运算器之间流动的物理路径，由总线和门控信号构成。","fx":["单总线结构：所有部件挂一条总线，同一时刻只允许一个输出","ALU 输入常配暂存器 X、Y"],"key":"看数据通路图先找总线条数：单总线最简单但最慢，多总线并行度高。"},
  "PC/MAR/MDR/IR": {"tag":"模型机 · 12","def":"模型机的四个访存-取指核心寄存器，构成取指流水线。","fx":["PC→MAR→主存→MDR→IR→CU","每个箭头都是一个微操作"],"key":"取指序列背这条链即可；执行期地址再走「IR 地址码 → MAR」这条路。"},
  "AC 与通用寄存器": {"tag":"模型机 · 12","def":"AC 是累加器，参与运算并暂存结果；通用寄存器组 R₀~Rₙ 提供多个高速暂存位。","fx":["单累加器结构：运算必有一操作数在 AC","通用寄存器结构：任意两寄存器可直接运算"],"key":"累加器结构指令短但瓶颈在 AC；通用寄存器结构灵活——模型机常用后者演示。"},
  "取指微程序": {"tag":"模型机 · 12","def":"所有指令共用的第一段微程序，完成取指并按操作码散转。","fx":["PC→MAR、读、MDR→IR、PC+1、按 OP 散转","存放在控存固定入口（常是 0 号单元）"],"key":"取指微程序只有一段；每条机器指令对应各自执行微程序——「一段公共入口 + N 段各指令」。"},
  "硬布线 vs 微程序": {"tag":"模型机 · 12","def":"两种控制器实现方案的对比，模型机两种方案都可演示。","fx":["硬布线：门电路译码出控制信号，快、不可改","微程序：读控存执行微指令，慢、可改","RISC 用硬布线，CISC 用微程序"],"key":"对比维度：速度、灵活性、成本、适用指令集——四格表是标准答案。"},
  "控存 CM": {"tag":"模型机 · 12","def":"控制存储器（Control Memory），位于 CPU 内部、专门存放微程序的存储器，通常用 ROM。","fx":["容量 = 微指令条数 × 微指令字长","配套寄存器：CMAR（微地址）、CMDR/μIR（微指令）"],"key":"控存 ≠ 主存：控存存微指令、面向 CPU 内部；主存存机器指令、面向程序员——「谁存微指令」是高频辨析点。"},
  "缩进": {"tag":"第1章 初识Python","sub":"Python 唯一的代码块标记","def":"Python 用行首的空白（缩进）来表示代码的层次关系。<b>1 个缩进 = 4 个空格</b>（用 Tab 也可以，但一个文件里必须统一）。C/Java 用 <code>{ }</code> 划代码块，Python 没有这对大括号，缩进就是唯一的块标记——缩进的深浅直接决定哪几行属于同一个 if 分支或循环体。缩进错了程序要么报 <code>IndentationError</code>，要么逻辑悄悄跑偏。","fx":["if x > 0:","····print(\"正数\")    ← 4 个空格缩进，属于 if 的块","print(\"结束\")          ← 无缩进，if 之外"],"key":"缩进不是排版，是语法：少一个空格，程序就换了意思。"},
  "注释": {"tag":"第1章 初识Python","sub":"写给人和未来的自己看","def":"注释不参与执行，解释器读到就跳过。<b>单行注释</b>用 <code>#</code>，从 # 到行尾都是注释；<b>多行注释</b>用三个单引号或三个双引号成对包裹。注释的价值在于让人读懂（也让你三个月后读懂自己），是零成本的工程习惯。","fx":["# 单行注释","''' 多行注释，可跨行","    第二行 '''","# print(\"这行被注释掉了，不会执行\")"],"key":"注释只有一个缺点：懒得写。"},
  "标识符命名": {"tag":"第1章 初识Python","sub":"变量和函数的名字规则","def":"标识符是给变量、函数、类起的名字。可用<b>字母、数字、下划线、汉字</b>及其组合，但<b>首字符不能是数字</b>，中间不能有空格，长度不限，<b>大小写敏感</b>（python 和 Python 是两个名字）。不能与保留字重名。工程习惯：变量用小写下划线（<code>temp_str</code>），类名首字母大写（<code>Student</code>），常量全大写。","fx":["合法：TempStr  _count  a1  温度  myName","非法：1a（数字开头）  my name（含空格）  if（保留字）"],"key":"见名知义：名字是给读者的第一手文档。"},
  "保留字": {"tag":"第1章 初识Python","sub":"语言内部占用的关键字","def":"保留字（关键字）是被 Python 语法内部占用、不能拿来当变量名的标识符。Python 3.x 共 <b>33 个</b>：<code>False None True and as assert break class continue def del elif else except finally for from global if import in is lambda nonlocal not or pass raise return try while with yield</code>。注意 <code>input</code>、<code>print</code>、<code>eval</code> <b>不是</b>保留字，它们是内置函数名（能改但强烈不建议）。","fx":["常用保留字：if elif else for while def return import class try except with global lambda"],"key":"查保留字：import keyword; keyword.kwlist。"},
  "input函数": {"tag":"第1章 初识Python","sub":"读取一行用户输入","def":"<code>input(提示语)</code> 在命令行等待用户输入，回车后返回<b>字符串</b>（不管你输入的是不是数字）。提示语可省略。要得到数字必须自己转换：<code>eval(input())</code> 或 <code>int(input())</code> / <code>float(input())</code>。","fx":["name = input(\"请输入姓名: \")        → 字符串","n = eval(input(\"请输入整数: \"))     → 数值","n = int(input(\"请输入整数: \"))      → 整数"],"key":"input 永远返回字符串，这是初学者最常见的类型错误来源。"},
  "eval函数": {"tag":"第1章 初识Python","sub":"把字符串当表达式求值","def":"<code>eval(s)</code> 去掉字符串最外层的引号，把里面当成一个 Python 表达式计算并返回结果。所以 <code>eval(\"1+2\")</code> 得 3，<code>eval(\"3.14\")</code> 得浮点数 3.14。常与 input 搭配完成\"文字转数字\"。风险：它会执行任意表达式，处理不可信输入时不要用。","fx":["eval(\"1+2\")      → 3","eval(\"3.14\")     → 3.14（float）","eval(input(\"数字: \"))  等价于按输入内容求值"],"key":"eval 是\"脱字符串的外套再算\"，不是简单的类型转换。"},
  "print函数": {"tag":"第1章 初识Python","sub":"向屏幕输出","def":"<code>print()</code> 输出字符信息或以字符串形式输出变量，可一次输出多个对象（默认空格分隔，<code>sep</code> 可改分隔符，<code>end</code> 可改结束符，默认换行）。格式控制有两条路：<code>\"{:.2f}\".format(x)</code> 与老式 <code>\"%.2f\" % x</code>。","fx":["print(\"a\", \"b\", sep=\"-\")        → a-b","print(\"x\", end=\"\")              → 不换行","print(\"{:.2f}\".format(3.14159))  → 3.14"],"key":"print 默认换行，想不换行就 end=\"\"。"},
  "赋值语句": {"tag":"第1章 初识Python","sub":"等号是\"放进去\"不是\"相等\"","def":"赋值语句 <code>变量 = 表达式</code>：先算右边，再把结果放进左边的变量，会<b>覆盖</b>变量原来的值。它与数学里的\"等于\"完全不同——数学上 x = x+1 无解，程序里它是\"把 x 加 1 后放回 x\"，是计数器的标准写法。比较是否相等用 <code>==</code>。","fx":["n = 1","n = n + 1      # 右边算出 2，再放回 n，所以 n 变 2","n += 1         # 等价写法"],"key":"= 是赋值，== 是比较，两者绝不能混。"},
  "同步赋值": {"tag":"第1章 初识Python","sub":"一行给多个变量赋值","def":"同步赋值 <code>变量1, …, 变量N = 表达式1, …, 表达式N</code>，右边的表达式<b>先全部算完</b>，再依次赋给左边。好处是省代码，最大用途是<b>交换两个变量的值</b>：<code>a, b = b, a</code> 一行搞定，不必借用临时变量。","fx":["a, b = 12, 13        等价于 a=12; b=13","a, b = b, a          交换，c 语言要三行","x, y, z = 1, 2, 3"],"key":"交换两数：a, b = b, a。这是 Python 的标志性写法。"},
  "turtle库": {"tag":"第1章 初识Python","sub":"海龟绘图标准库","def":"turtle（海龟绘图）是 Python 标准库，用\"一只叼着笔的海龟在画布上爬\"的模型绘图。三组命令：<b>画布</b> <code>setup(w,h,x,y)</code>；<b>画笔</b> <code>penup()</code>/<code>pendown()</code>/<code>pensize()</code>/<code>pencolor()</code>；<b>运动</b> <code>fd(d)</code> 前进、<code>bk(d)</code> 后退、<code>circle(r,extent)</code> 画弧、<code>seth(a)</code> 设绝对朝向、<code>left/right(a)</code> 相对转向。<code>done()</code> 结束并保留窗口。","fx":["t.fd(100)          前进 100 像素","t.circle(40, 80)    画半径 40、圆心角 80° 的弧","t.seth(-40)         绝对朝向 -40°；t.left(30) 相对左转 30°"],"key":"提笔不留痕、落笔才画线，这是 turtle 的第一条纪律。"},
  "range函数": {"tag":"第1章 初识Python","sub":"产生整数序列","def":"<code>range(stop)</code> 产生 <code>0,1,…,stop-1</code>；<code>range(start, stop)</code> 产生 start 到 stop-1；<code>range(start, stop, step)</code> 按步长产生。<b>左闭右开</b>，不含 stop。它返回的是惰性序列对象，常与 for 搭配决定循环次数。","fx":["range(5)        → 0 1 2 3 4","range(1, 6)     → 1 2 3 4 5","range(1, 10, 2) → 1 3 5 7 9","range(5, 0, -1) → 5 4 3 2 1"],"key":"range 右端取不到，想数到 n 就写 range(n+1)。"},
  "import引用": {"tag":"第1章 初识Python","sub":"三种引入库的写法","def":"用库前要先引入。<b>①</b> <code>import turtle</code> 后用 <code>turtle.fd()</code>（带前缀）；<b>②</b> <code>import turtle as t</code> 起别名，用 <code>t.fd()</code>（最常用，短且不冲突）；<b>③</b> <code>from turtle import fd, circle</code> 或 <code>from turtle import *</code> 直接调用函数名（方便但易与自己的变量重名）。","fx":["import math            → math.sqrt(2)","import numpy as np     → np.array([1,2])","from math import sqrt  → sqrt(2)"],"key":"import … as … 是工程里最推荐的引入方式。"},
  "IDE": {"tag":"第1章 初识Python","sub":"集成开发环境","def":"IDE（Integrated Development Environment）把编辑、运行、调试集成在一起。Jupyter Notebook 适合学习实验、边写边看结果，但无法单步跟踪变量、难以管理多文件工程。PyCharm / VSCode 等 IDE 支持<b>断点、单步执行、查看变量</b>：F7 单步进入函数、F8 单步跳过、F9 继续运行。规模稍大的项目必须用 IDE。","fx":["F7 Step Into    进入函数内部","F8 Step Over    执行完当前行不进入函数","F9 Resume       继续运行到下一个断点"],"key":"Jupyter 学语法，IDE 写工程。"},
  "整数类型": {"tag":"第2章 基本数据类型","sub":"int，无精度上限","def":"Python 的 int 与数学整数一致，<b>没有取值范围限制</b>（内部按需扩展，<code>2**1000</code> 也能算），这是与 C 语言 int 的最大区别。支持四种字面量：十进制、<code>0x</code> 十六进制、<code>0b</code> 二进制、<code>0o</code> 八进制。整数之间的 + − * // % ** 运算结果仍是整数。","fx":["10, 0x1a(=26), 0b1010(=10), 0o17(=15)","pow(2, 100) → 1267650600228229401496703205376","type(3) → <class 'int'>"],"key":"Python 整数不会溢出，这在算大数时是福利。"},
  "浮点数类型": {"tag":"第2章 基本数据类型","sub":"float，有范围也有精度","def":"浮点数表示带小数的数，可用科学计数法 <code>aEb = a×10^b</code>（如 <code>9.6e4</code>）。两个固有局限：<b>取值范围有限</b>（太大上溢 overflow，如 <code>1e400</code> 变成 inf）；<b>精度有限</b>（太小下溢 underflow 变 0，且二进制无法精确表示多数十进制小数）。所以 <code>0.1+0.2 == 0.30000000000000004</code>，判断浮点相等要用差值小于容差。","fx":["9.6e4  → 96000.0","0.1 + 0.2 → 0.30000000000000004","abs(a-b) < 1e-9   判断浮点相等"],"key":"浮点数不要用 == 比较，用 |a−b| < ε。"},
  "复数类型": {"tag":"第2章 基本数据类型","sub":"complex，a+bj","def":"Python 内置复数类型，写作 <code>a + bj</code>（j 是虚数单位）。<code>z.real</code> 取实部、<code>z.imag</code> 取虚部（都是浮点数），<code>z.conjugate()</code> 取共轭。运算规则：(a+bj)+(c+dj)=(a+c)+(b+d)j；(a+bj)(c+dj)=(ac−bd)+(bc+ad)j。工程计算多用 numpy 的复数数组。","fx":["z = 1 + 5j","z.real → 1.0 ; z.imag → 5.0","(1+2j) * (3+4j) → (-5+10j)"],"key":"虚部单位是 j 不是 i，且系数不能省（写 1j 不写 j）。"},
  "类型混合运算": {"tag":"第2章 基本数据类型","sub":"结果取\"最宽\"的类型","def":"整数、浮点、复数混合运算时，结果自动向<b>更宽</b>的类型靠拢，宽度顺序：<b>整数 → 浮点数 → 复数</b>。所以 123+4.0 得 127.0（浮点），1+2j+3 得 (4+2j)（复数）。另有一条常被忽略：<b>除法 <code>/</code> 的结果一定是浮点数</b>，即使能整除（4/2 = 2.0）；要整数结果用整除 <code>//</code>。","fx":["123 + 4.0   → 127.0（整数+浮点=浮点）","1 + 2j + 3  → (4+2j)","7 / 2 → 3.5   7 // 2 → 3   7 % 2 → 1"],"key":"只要出现 / ，结果就是 float。"},
  "math库": {"tag":"第2章 基本数据类型","sub":"标准数学库","def":"math 是 Python 标准库，提供 <b>4 个常数 + 44 个函数</b>。常数：<code>pi</code>、<code>e</code>、<code>inf</code>、<code>nan</code>。函数分四类：数值表示（ceil/floor/trunc/fabs/fmod…）、幂对数（pow/exp/log/log10/sqrt…）、三角函数（sin/cos/tan/asin…/degrees/radians）、高等特殊（gamma 等）。用法：<code>import math</code> 后 <code>math.sqrt(2)</code>。注意它只处理实数，且返回浮点近似值有精度损失。","fx":["math.pi → 3.141592653589793","math.sqrt(2) → 1.4142135623730951","math.log(math.e) → 1.0","math.floor(2.7)=2, math.ceil(2.1)=3"],"key":"要用三角函数先确认角度还是弧度——math 默认弧度。"},
  "运算符优先级": {"tag":"第2章 基本数据类型","sub":"谁先算","def":"由高到低：<b>括号 ( )</b> → 一元 + − → 幂 <code>**</code> → <code>* / % //</code> → <code>+ −</code> → 比较 <code>&lt; &lt;= &gt; &gt;= == !=</code> → <code>not</code> → <code>and</code> → <code>or</code> → 赋值。两个反直觉点：<b>幂运算右结合</b>，<code>2**3**2 = 2**(3**2) = 512</code>；<b>not 高于 and 高于 or</b>，所以 <code>a or b and c</code> 等于 <code>a or (b and c)</code>。","fx":["2**3**2  → 512（不是 64）","2*3+4    → 10","not True and False → False（not 先结合 True）"],"key":"拿不准就加括号，可读性比炫技重要。"},
  "类型转换函数": {"tag":"第2章 基本数据类型","sub":"int / float / str / round","def":"<code>int(x)</code> 转整数，对浮点是<b>直接截断小数</b>（不是四舍五入，int(-5.6) 得 -5）；<code>float(x)</code> 转浮点；<code>str(x)</code> 转字符串；<code>round(x, n)</code> 四舍五入到 n 位小数（注意银行家舍入：round(2.5) 得 2）；<code>complex(x)</code> 转复数。<code>type(x)</code> 查类型，<code>eval()</code> 按内容求值。","fx":["int(5.9) → 5      int(-5.9) → -5","round(3.14159, 2) → 3.14","round(2.5) → 2（银行家舍入）","str(123) + \"abc\" → \"123abc\""],"key":"int 是截断不是四舍五入，别搞混。"},
  "字符串索引": {"tag":"第2章 基本数据类型","sub":"正向下标与反向下标","def":"字符串是字符序列，每个字符有<b>两套序号</b>：<b>正向</b>从左到右 0,1,…,L−1；<b>反向</b>从右到左 −1,−2,…，−1 是最后一个。<code>s[i]</code> 取单个字符，下标越界抛 <code>IndexError</code>。这是所有序列类型（字符串、列表、元组）的通用规则。","fx":["s = \"Python\"","s[0]=\"P\"  s[2]=\"t\"  s[5]=\"n\"","s[-1]=\"n\"  s[-6]=\"P\""],"key":"−1 就是最后一个字符，取末位不用 len(s)-1。"},
  "字符串切片": {"tag":"第2章 基本数据类型","sub":"s[start:end:step]","def":"切片 <code>s[start:end]</code> 取从 start 到 <b>end 之前</b>（左闭右开，不含 end）的子串；<code>s[start:end:step]</code> 按步长取，步长为负则从右往左。三个参数都可省略：<code>s[:]</code> 全串、<code>s[:3]</code> 前三个、<code>s[2:]</code> 从第 2 位到末尾、<code>s[::-1]</code> 反转。切片越界<b>不报错</b>，只会截到边界。","fx":["s=\"Python\"","s[0:2]   → \"Py\"","s[2:]    → \"thon\"","s[-3:]   → \"hon\"","s[::-1]  → \"nohtyP\""],"key":"切片不含右端，s[0:2] 只取两个字符。"},
  "字符串格式化format": {"tag":"第2章 基本数据类型","sub":"\"{:格式说明}\".format(x)","def":"<code>\"{序号:填充对齐宽度.精度类型}\".format(值)</code> 是 Python 最常用的输出格式控制。格式说明六部分：<b>[填充字符][对齐 &lt;^&gt;][符号][宽度][,千分位][.精度][类型]</b>，类型有 d 整数、f 浮点、e 科学、s 字符串、% 百分比。注意 <code>{:.2f}</code> 的 .2 是<b>小数位数</b>，不是总宽度。","fx":["\"{:.2f}\".format(3.14159)      → 3.14","\"{:>8.2f}\".format(3.14)      → \"    3.14\"","\"{:*^10}\".format(\"ab\")       → \"****ab****\"","\"{:,.2f}\".format(1234567.891) → 1,234,567.89"],"key":"精度写在类型前，f 的类型位不能少。"},
  "字符串不可变性": {"tag":"第2章 基本数据类型","sub":"所有\"修改\"都产生新串","def":"字符串是<b>不可变对象</b>：创建后里面的字符不能改，<code>s[0]=\"x\"</code> 会抛 <code>TypeError</code>。所有看起来在修改的方法（<code>upper()</code>、<code>replace()</code>、<code>strip()</code>、<code>+</code> 拼接）都是<b>返回一个新字符串</b>，原串不变。所以必须接收返回值：<code>s = s.upper()</code>。不可变带来一个好处——字符串可作字典的键。","fx":["s = \"abc\"","s.upper()      → \"ABC\"，但 s 仍是 \"abc\"","s = s.upper()  → 必须赋值才生效","s[0] = \"x\"     → TypeError"],"key":"不可变 = 任何修改都返回新串，别忘接收返回值。"},
  "关系运算符": {"tag":"第2章 基本数据类型","sub":"== != > < >= <=","def":"关系运算比较两个值的大小或相等，结果一定是布尔值 <code>True</code>/<code>False</code>。六种：<code>==</code> 等于（两个等号！）、<code>!=</code> 不等于、<code>&gt;</code>、<code>&lt;</code>、<code>&gt;=</code>、<code>&lt;=</code>。可连续比较：<code>0 &lt; x &lt; 10</code> 等价于 <code>0 &lt; x and x &lt; 10</code>，这是 Python 特有的便利写法。字符串按字符编码逐位比较。","fx":["10 == 20 → False      10 != 20 → True","0 < x < 10   等价 0<x and x<10","\"abc\" < \"abd\" → True（按编码比）"],"key":"相等是两个等号，一个等号是赋值。"},
  "逻辑运算符": {"tag":"第2章 基本数据类型","sub":"and / or / not","def":"<code>and</code>（与）：全真才真，有一个假就是假；<code>or</code>（或）：全假才假，有一个真就是真；<code>not</code>（非）：取反。优先级 <code>not &gt; and &gt; or</code>。运算对象不必是布尔值——Python 把 0、空串、空列表、None 视为假，其余为真；并且 <code>and/or</code> 返回的是<b>参与运算的具体值</b>，所以可写 <code>name = input() or \"匿名\"</code> 做默认值。","fx":["True and False → False","True or False  → True","not True       → False","\"\" or \"默认\"   → \"默认\""],"key":"and 找第一个假，or 找第一个真。"},
  "短路求值": {"tag":"第2章 基本数据类型","sub":"左侧能定结果就不算右边","def":"<code>and</code> 从左往右算，<b>遇到第一个假值立即返回它，右边不再计算</b>；<code>or</code> 遇到第一个真值立即返回，右边同样不算。这就是\"短路\"。实用价值：把可能出错的操作放在短路之后保护起来，例如 <code>if n != 0 and 10/n &gt; 1:</code>——n 为 0 时右边根本不执行，不会抛 <code>ZeroDivisionError</code>。顺序颠倒就会崩。","fx":["False and (1/0) → False，右边不执行，不报错","True or (1/0)   → True，右边不执行","if n != 0 and 10/n > 1:  ← 保护式写法"],"key":"保护判断写在左边，危险运算写在右边。"},
  "程序流程图": {"tag":"第3章 程序的控制结构","sub":"7 种基本图形","def":"流程图用图形、流程线与文字描述程序的执行流程。基本元素 7 种：<b>起止框</b>（圆角矩形，开始/结束）、<b>处理框</b>（矩形，赋值/计算）、<b>判断框</b>（菱形，条件，有是/否两条出口）、<b>输入输出框</b>（平行四边形）、<b>流程线</b>（带箭头）、<b>连接点</b>（圆圈，跨页连接）、<b>注释框</b>。三种基本结构（顺序、分支、循环）都能用它画出来。","fx":["圆角矩形 = 起止    矩形 = 处理","菱形 = 判断（是/否两支）","平行四边形 = 输入输出"],"key":"看到菱形就要想到\"两条出路\"。"},
  "顺序结构": {"tag":"第3章 程序的控制结构","sub":"从上到下逐句执行","def":"顺序结构是最基础的结构：语句按书写的先后顺序<b>一条接一条</b>执行，没有跳转、没有分支。它是程序的主干，分支与循环都嵌在顺序结构之中。注意：顺序结构里前一句的效果会影响后一句（如先赋值后使用），所以语句顺序不能随意调换。","fx":["a = 1","b = a + 1     # 必须在 a 之后","print(b)      # 2"],"key":"顺序结构里，语句的先后就是因果。"},
  "单分支if": {"tag":"第3章 程序的控制结构","sub":"if 条件: 语句块","def":"<code>if &lt;条件&gt;:</code> 后跟缩进的语句块。条件为 <code>True</code> 时执行语句块，然后继续执行 if 之后的语句；为 <code>False</code> 时<b>整块跳过</b>。条件可以是任意表达式，Python 会按真假规则判定（0、空串、空列表、None 为假）。冒号和缩进都不能少。","fx":["if x > 0:","····print(\"正数\")","print(\"结束\")   # 无论真假都执行"],"key":"if 只管到缩进结束为止。"},
  "二分支if-else": {"tag":"第3章 程序的控制结构","sub":"True 走 if，False 走 else","def":"<code>if &lt;条件&gt;: &lt;块1&gt; else: &lt;块2&gt;</code>，两条路<b>必走其一且只走其一</b>。适合\"非此即彼\"的判断（及格/不及格、奇/偶）。else 后面不写条件、但要写冒号。注意 else 与 if 必须<b>同缩进</b>对齐，缩进错位会导致语法错误或逻辑错误。","fx":["if n % 2 == 0:","····print(\"偶数\")","else:","····print(\"奇数\")"],"key":"二分支是\"二选一\"，不会两条都走。"},
  "多分支if-elif-else": {"tag":"第3章 程序的控制结构","sub":"依次判断，命中即跳出","def":"<code>if c1: … elif c2: … elif c3: … else: …</code>。<b>自上而下依次判断，命中第一个 True 就执行对应块，然后跳过整个结构</b>；全部不成立才走 else（else 可省）。关键性质：各分支<b>互斥</b>，所以条件顺序很重要——把宽条件写在前面会\"截胡\"后面的窄条件。若需要多个条件都独立判断，要用多个独立的 if。","fx":["if s >= 90: 等级=\"A\"","elif s >= 80: 等级=\"B\"","elif s >= 70: 等级=\"C\"","else: 等级=\"D\""],"key":"elif 是互斥的，顺序写反就出错。"},
  "条件表达式": {"tag":"第3章 程序的控制结构","sub":"a if cond else b","def":"紧凑的二分支取值形式：<code>&lt;值1&gt; if &lt;条件&gt; else &lt;值2&gt;</code>，条件真取前面、假取后面，整个表达式直接得到一个值，可以放在赋值右边或函数实参里。它只适合<b>简单二选一</b>，逻辑一复杂就应改回 if 语句，否则可读性崩坏。","fx":["level = \"污染\" if pm >= 75 else \"正常\"","abs_x = x if x >= 0 else -x","判定不能用 elif 分支，只能二选一"],"key":"它返回的是值，不是语句，所以能塞进赋值里。"},
  "异常处理try-except": {"tag":"第3章 程序的控制结构","sub":"try / except / else / finally","def":"<code>try</code> 块放可能出错的代码；发生异常时<b>立即跳到匹配的 except</b> 块执行，程序不中断。可写多个 except 分别捕获不同异常类型，<code>except:</code>（不带类型）捕获所有。<code>else</code> 在未发生异常时执行，<code>finally</code> 无论如何都执行（常用于关闭文件、释放资源）。","fx":["try:","····n = eval(input())","except NameError:","····print(\"请输入数字\")","finally:","····print(\"结束\")"],"key":"try 里出错的语句之后的部分不会执行，直接跳 except。"},
  "异常类型": {"tag":"第3章 程序的控制结构","sub":"NameError / ValueError / ZeroDivisionError…","def":"异常由\"类型 + 提示\"两部分组成，如 <code>NameError: name 'a' is not defined</code>。常见类型：<code>NameError</code> 用了未定义的名字（eval 输入字母时常见）；<code>ValueError</code> 值不合法（int(\"abc\")）；<code>ZeroDivisionError</code> 除零；<code>IndexError</code> 下标越界；<code>KeyError</code> 字典键不存在；<code>TypeError</code> 类型不匹配；<code>FileNotFoundError</code> 文件不存在；<code>IndentationError</code> 缩进错误。","fx":["int(\"abc\")       → ValueError","1/0              → ZeroDivisionError","[1,2][5]          → IndexError","{\"a\":1}[\"b\"]      → KeyError"],"key":"读报错先看最后一行的异常类型。"},
  "遍历循环for": {"tag":"第3章 程序的控制结构","sub":"for x in 结构","def":"<code>for &lt;变量&gt; in &lt;遍历结构&gt;:</code>，遍历结构可以是<b>字符串、range()、列表、元组、字典、文件</b>等任何可迭代对象。<b>循环次数由遍历结构的长度决定</b>，属于\"有限循环\"。每轮把当前元素赋给变量再执行循环体，遍历完自动结束。<code>for i in range(n)</code> 是最常见的计数式写法。","fx":["for ch in \"abc\":        → 循环 3 次","for i in range(1, 101):  → 循环 100 次","for k, v in d.items():   → 遍历字典键值"],"key":"for 的次数由序列长度定，不是由条件定。"},
  "条件循环while": {"tag":"第3章 程序的控制结构","sub":"while 条件: 反复执行","def":"<code>while &lt;条件&gt;:</code> 每轮开始前判断条件，为真就执行循环体，再回来判断……直到条件为假退出。适合<b>事先不知道要循环多少次</b>的场景（如\"直到误差小于 1e-6\"）。写 while 必须保证循环变量在循环体内被改变，否则条件永远为真 → <b>死循环</b>。","fx":["i = 0","while i < 5:","····i += 1     # 忘了这句就死循环"],"key":"while 里一定要有让条件变化的东西。"},
  "break语句": {"tag":"第3章 程序的控制结构","sub":"跳出最内层整个循环","def":"<code>break</code> 立即终止它所在的<b>最内层</b>循环，循环体剩余语句不执行，直接跳到该循环<b>之后</b>的代码。循环嵌套时 break 只跳出一层，不会跳出全部。常与 while True 搭配实现\"中途退出\"（如密码输错三次、找到目标就停）。","fx":["for i in range(10):","····if i == 3: break","····print(i)      → 只输出 0 1 2"],"key":"break 只跳一层，嵌套循环要跳多层得用标志或函数返回。"},
  "continue语句": {"tag":"第3章 程序的控制结构","sub":"只结束本次循环","def":"<code>continue</code> 跳过<b>本轮剩余</b>的循环体语句，直接进入下一轮：for 循环取下一个元素，while 循环回到条件判断。它不终止循环。常用来\"过滤\"不需要处理的情况，如跳过偶数只处理奇数。注意 while 里 continue 之前要更新循环变量，否则会卡在同一轮死循环。","fx":["for i in range(5):","····if i % 2 == 0: continue","····print(i)    → 只输出 1 3"],"key":"break 是\"不干了\"，continue 是\"这轮不算，下一轮\"。"},
  "循环嵌套": {"tag":"第3章 程序的控制结构","sub":"外层走一次，内层走一轮","def":"循环体里再写一个循环就是嵌套。<b>外层每执行一次，内层都要完整执行一轮</b>，所以总执行次数约为外层次数 × 内层次数。典型应用：九九乘法表、二维表格遍历、打印图形。注意区分哪条语句属于内层、哪条属于外层——靠缩进判断，缩进位置不同结果天差地别。","fx":["for i in range(1, 10):","····for j in range(1, i+1):","········print(i*j, end=\" \")","····print()      # 每行结束换行"],"key":"内层跑完一轮，外层才前进一格。"},
  "函数定义def": {"tag":"第4章 函数与代码复用","sub":"def 名字(参数): 函数体","def":"<code>def &lt;函数名&gt;(&lt;参数列表&gt;):</code> 后跟缩进的函数体，可选择 <code>return &lt;返回值&gt;</code>。定义时<b>只登记不执行</b>，只有被调用才运行。函数名遵循标识符规则，参数列表可为空。函数的意义：<b>问题分解</b>（把大问题拆小）与<b>代码复用</b>（写一次到处用），本质是一种\"黑盒\"抽象——调用者只需知道输入输出，不必关心内部。","fx":["def area(r):","····return 3.14159 * r * r","","s = area(2)    # 调用才执行"],"key":"def 是\"造工具\"，调用才是\"用工具\"。"},
  "函数调用过程": {"tag":"第4章 函数与代码复用","sub":"四步：暂停→传参→执行→返回","def":"① 调用程序在调用处<b>暂停</b>；② 把实参的值<b>复制</b>给形参；③ <b>执行</b>函数体语句；④ 遇到 return 或函数体结束，<b>返回</b>到调用前的暂停处继续执行。理解\"复制\"很关键：函数内改形参不影响外部的不可变实参（数值、字符串），但可变对象（列表）传的是引用，原地修改会影响到外部。","fx":["def f(x):","····x = x + 1     # 只改形参副本","a = 1; f(a); print(a)   → 仍是 1"],"key":"实参传给形参是\"复制一份\"，不是共享同一个盒子。"},
  "返回值return": {"tag":"第4章 函数与代码复用","sub":"退出函数并带回结果","def":"<code>return</code> 有两个作用：<b>立即结束函数</b>并<b>把结果返回</b>给调用处。可以返回 0 个（只写 return 或不写）、1 个、多个值——<b>多个值自动打包成元组</b>，可用 <code>a, b = f()</code> 解包。函数没有 return 时默认返回 <code>None</code>。注意：return 之后的语句永远不会执行。","fx":["def f(x):","····return x, x*2","a, b = f(3)    → a=3, b=6（返回元组）","def g(): pass  → g() 返回 None"],"key":"没有 return 就是返回 None，不是返回 0。"},
  "lambda函数": {"tag":"第4章 函数与代码复用","sub":"一行定义的匿名函数","def":"<code>&lt;函数名&gt; = lambda &lt;参数列表&gt;: &lt;表达式&gt;</code>，等价于只含一个 return 的 def——表达式的结果就是返回值。适合定义<b>简单、一行能写完</b>的小函数，最常见用途是作为参数传给 <code>map</code>、<code>filter</code>、<code>sorted(key=…)</code>。不能写多条语句，也不能包含赋值。","fx":["f = lambda x, y: x + y      f(1,2) → 3","sorted(ls, key=lambda x: -x)","list(map(lambda x: x*2, [1,2,3])) → [2,4,6]"],"key":"lambda 就是\"只返回一个表达式的迷你 def\"。"},
  "可选参数": {"tag":"第4章 函数与代码复用","sub":"带默认值的参数","def":"定义函数时给参数指定默认值（<code>def f(a, b=2)</code>），调用时若不传该参数就用默认值。<b>硬性规则：带默认值的参数必须写在无默认值参数之后</b>，否则语法错误——因为位置传参从左往右匹配，若默认参数在前会引起歧义。默认值只在定义时求值一次，所以别用可变对象（如 <code>[]</code>）当默认值。","fx":["def f(a, b=2): return a+b","f(1)    → 3（用默认）","f(1, 5) → 6","def g(a=1, b): ...   ← SyntaxError"],"key":"默认参数往后放，默认值别用可变对象。"},
  "可变数量参数": {"tag":"第4章 函数与代码复用","sub":"*args 打包成元组","def":"参数名前加星号 <code>*args</code>，可以让函数接收<b>任意个</b>实参；多余的实参被打包成一个<b>元组</b>传进函数，用 for 遍历即可。<b>它只能放在参数列表最后</b>。若加两个星号 <code>**kwargs</code>，则把多余的关键字实参打包成<b>字典</b>。常用于写求和、拼接这类参数个数不定的工具函数。","fx":["def s(*args): return sum(args)","s(1,2,3)      → 6","s()           → 0","def f(a, *rest): ...   # rest 必须最后"],"key":"* 收成元组，** 收成字典，且都在最后。"},
  "位置传参与名称传参": {"tag":"第4章 函数与代码复用","sub":"按顺序传 or 按名字传","def":"<b>位置传参</b>：实参按<b>顺序</b>依次对应形参，<code>f(1, 2, 3)</code> 最常用。<b>名称传参</b>（关键字传参）：调用时写 <code>f(z=3, x=1, y=2)</code>，按形参名字匹配，<b>顺序可以任意</b>，可读性更好。两种可以混用，但<b>位置实参必须写在关键字实参之前</b>。","fx":["def f(x, y, z): ...","f(1, 2, 3)          位置传参","f(z=3, x=1, y=2)    名称传参，顺序随意","f(1, y=2, z=3)      混用，位置在前"],"key":"名称传参让调用点自解释，参数多时优先用它。"},
  "全局变量与局部变量": {"tag":"第4章 函数与代码复用","sub":"作用域与查找顺序","def":"<b>全局变量</b>在函数外定义、无缩进，全程有效；<b>局部变量</b>在函数内使用，函数退出即销毁。查找顺序：<b>先局部 → 再外层嵌套函数 → 最后全局</b>。两条关键规则：① 函数内一旦对某变量<b>赋值</b>，Python 就把它当局部变量（哪怕外部有同名全局变量）；② 只读取而不赋值时，用的是全局变量。","fx":["n = 1","def f():","····print(n)   # 读，用的是全局 n","f()  → 1"],"key":"函数内\"赋值\"就变局部，\"只读\"才用全局。"},
  "global声明": {"tag":"第4章 函数与代码复用","sub":"函数内改全局变量必须声明","def":"默认情况下函数内给变量赋值会创建局部变量。若想在函数内<b>修改全局变量</b>，必须在赋值前用 <code>global 变量名</code> 显式声明，告诉 Python \"这个名字指的是外面的那个\"。若既在函数内赋值又不声明，却在赋值前读取它，Python 会抛 <code>UnboundLocalError</code>（因为它已被判定为局部但还没值）。","fx":["n = 1","def f():","····global n","····n = 5      # 改的是全局","f(); print(n)  → 5"],"key":"要改全局先 global，否则你改的只是局部副本。"},
  "可变对象的原地修改": {"tag":"第4章 函数与代码复用","sub":"列表方法会改到全局","def":"这一条是 global 的\"例外\"：函数内对<b>组合数据类型</b>调用<b>原地修改方法</b>（<code>ls.append()</code>、<code>ls.sort()</code>、<code>d[k]=v</code>）时，并<b>没有发生赋值</b>，所以不需要 global，改的就是外部那个对象。反之若在函数内写 <code>ls = [...]</code>，那是重新赋值，会创建新的局部列表，外部原列表不受影响。","fx":["ls = [1, 2]","def f():","····ls.append(3)    # 原地改，影响全局","def g():","····ls = [9]        # 重新赋值，只改局部"],"key":"append 是原地改，= 是新造一个——这条差别决定了全局会不会变。"},
  "递归": {"tag":"第4章 函数与代码复用","sub":"函数自己调用自己","def":"函数定义中<b>调用自身</b>的方式叫递归。它能把复杂问题用极简代码表达（阶乘、斐波那契、汉诺塔、树的遍历、科赫曲线）。运行时每次调用都会在内存里压一层调用栈，所以<b>递归深度有限</b>——Python 默认最大深度约 1000 层，超过抛 <code>RecursionError</code>。递归的可读性优势明显，但性能通常不如循环。","fx":["def fact(n):","····if n == 0: return 1     # 基例","····return n * fact(n-1)    # 递归链"],"key":"递归 = 基例 + 向基例靠近的递归链。"},
  "递归基例": {"tag":"第4章 函数与代码复用","sub":"递归的出口，缺了就无限递归","def":"基例（base case）是递归中<b>不再调用自身、直接给出确定答案</b>的分支，例如 <code>0! = 1</code>、<code>h(1) = 1</code>。递归的第二个要素是<b>递归链</b>：每次调用都要让问题规模<b>变小并最终触到基例</b>。缺基例或规模不收敛 → 无限递归 → <code>RecursionError: maximum recursion depth exceeded</code>。","fx":["def fact(n):","····if n == 0: return 1    ← 基例，必须有","····return n * fact(n-1)   ← 规模每次减 1，必然到达 0"],"key":"递归写不出结果，先检查有没有基例、规模有没有变小。"},
  "模块化设计": {"tag":"第4章 函数与代码复用","sub":"紧耦合 + 松耦合","def":"把程序划分成若干功能模块、基于模块设计程序，叫模块化设计。两条基本要求：<b>紧耦合</b>——单个功能块内部各部分联系紧密；<b>松耦合</b>——模块之间关系尽可能简单、依赖少。用函数只是模块化的<b>必要非充分条件</b>：关键是把\"完成特定功能、经常被复用\"的一组语句封装成函数，并尽量减少函数之间的参数与返回值数量。","fx":["紧耦合：一个函数内部逻辑自洽、职责单一","松耦合：函数之间少传参、少共享全局变量"],"key":"函数内部抱紧，函数之间松手。"},
  "序列类型": {"tag":"第5章 组合数据类型（一）","sub":"字符串 / 元组 / 列表","def":"序列是<b>元素有序排列、可按序号访问</b>的数据类型，Python 三大序列：<b>字符串 str</b>（不可变）、<b>元组 tuple</b>（不可变）、<b>列表 list</b>（可变）。它们共享同一套通用操作：<code>x in s</code>、<code>s+t</code>、<code>s*n</code>、<code>s[i]</code>、<code>s[i:j]</code>、<code>len(s)</code>、<code>min(s)</code>、<code>max(s)</code>、<code>s.index(x)</code>、<code>s.count(x)</code>。掌握一个就基本会用另外两个。","fx":["通用：x in s / s+t / s*n / s[i] / s[i:j] / len(s) / min / max","s.index(x) 首次出现位置；s.count(x) 出现次数","s[::-1] 反转，s[-1] 末元素"],"key":"有序 + 可切片 = 序列，str/tuple/list 都是。"},
  "集合类型": {"tag":"第5章 组合数据类型（一）","sub":"set，无序不重复","def":"集合用 <code>{}</code> 创建，元素<b>无序、不重复</b>，因此<b>不能用下标访问</b>（没有 s[0]）。主要用途：<b>去重</b>、<b>成员判断</b>（哈希实现，比列表快得多）、<b>集合运算</b>。元素必须是<b>可哈希</b>的不可变对象，所以列表、字典不能放进集合。<b>空集合必须写 <code>set()</code></b>，因为 <code>{}</code> 是空字典。","fx":["s = {1, 2, 2, 3}   → {1,2,3}，自动去重","set(\"hello\")       → 不重复字符集合","type({})           → dict（不是 set！）"],"key":"{} 是空字典，空集合得写 set()。"},
  "映射类型": {"tag":"第5章 组合数据类型（一）","sub":"dict，键值对","def":"映射类型即<b>字典 dict</b>，存的是\"<b>键 → 值</b>\"的对应关系，按<b>键</b>而不是位置取值。键必须唯一且可哈希，值任意。它的价值在于\"用名字找东西\"——比列表按位置找更贴近真实问题（学号找成绩、单词找释义）。第六章详细展开。","fx":["d = {\"Tom\": 92, \"Amy\": 88}","d[\"Tom\"] → 92   按键取值","len(d)   → 键值对个数"],"key":"序列按位置找，字典按键找。"},
  "元组tuple": {"tag":"第5章 组合数据类型（一）","sub":"() 创建，不可变","def":"元组用圆括号（或直接逗号分隔）创建，<b>创建后不可增删改</b>，试图 <code>t[0]=9</code> 会抛 <code>TypeError</code>。适合表达\"一组固定不变的数据\"（坐标、日期、RGB 颜色、函数返回的多值）。<b>单元素元组必须带逗号</b>写 <code>(1,)</code>，否则 <code>(1)</code> 只是整数 1。元组可作字典的键（因为不可变可哈希）。","fx":["t = (1, 2, 3)     t[0] → 1","t[0] = 9          → TypeError","one = (1,)        ← 单元素必须带逗号","t = 1, 2, 3       ← 括号可省"],"key":"元组不可变，所以能当字典键。"},
  "列表list": {"tag":"第5章 组合数据类型（一）","sub":"[] 创建，可增删改","def":"列表用方括号创建，是<b>可变</b>序列，Python 中最常用的组合类型。创建方式：<code>[]</code>、<code>list()</code>、<code>list(range(5))</code>、<code>\"a,b\".split(\",\")</code>、列表推导式。核心方法：<code>append(x)</code> 末尾追加、<code>insert(i,x)</code> 第 i 位插入、<code>pop(i)</code> 取出并删除、<code>remove(x)</code> 删第一个 x、<code>sort()</code> 原地排序、<code>reverse()</code> 反转、<code>copy()</code> 浅拷贝、<code>clear()</code> 清空。","fx":["ls.append(4)      末尾加","ls.insert(0, 9)   头插","ls.pop()          取末尾并删除","ls.sort(reverse=True)   降序原地排"],"key":"append/insert/pop/sort 都是原地改，不返回新列表。"},
  "列表的别名与浅拷贝": {"tag":"第5章 组合数据类型（一）","sub":"b = a 与 b = a.copy() 的差别","def":"<code>b = a</code> 只是给同一个列表对象起了第二个名字（<b>别名</b>），改 b 就是改 a。<code>b = a.copy()</code>（或 <code>a[:]</code>、<code>list(a)</code>）创建<b>新的列表容器</b>（<b>浅拷贝</b>），改 b 的增删不影响 a——但若元素本身是列表，里层仍共享（这叫浅）。深拷贝需 <code>import copy; copy.deepcopy(a)</code>。","fx":["a = [1,2]; b = a; b.append(3)   → a 也变 [1,2,3]","a = [1,2]; b = a.copy(); b.append(3) → a 不变","a = [[1]]; b = a.copy(); b[0].append(2) → a 也变（浅）"],"key":"= 是起外号，copy() 才是造新箱子。"},
  "列表推导式": {"tag":"第5章 组合数据类型（一）","sub":"[表达式 for x in 序列 if 条件]","def":"列表推导式用一行生成列表：<code>[&lt;表达式&gt; for &lt;变量&gt; in &lt;序列&gt; if &lt;条件&gt;]</code>。它等价于\"建空列表 + for 循环 + append\"，但更短更快更 Pythonic。if 过滤可省；可嵌套多层 for（相当于双重循环）。注意：只为副作用时不该用它（应写普通 for），推导式的目的是<b>造列表</b>。","fx":["[x**2 for x in range(1, 6)]          → [1,4,9,16,25]","[x for x in range(10) if x % 2 == 0]  → [0,2,4,6,8]","[i*j for i in range(1,3) for j in range(1,3)] → [1,2,2,4]"],"key":"中括号 + for = 造列表，条件写在最后。"},
  "集合set": {"tag":"第5章 组合数据类型（一）","sub":"{} 创建，无序不重复","def":"集合是无序不重复的元素集，底层是哈希表，所以<b>成员判断平均 O(1)</b>（列表是 O(n)）。创建：<code>{1,2,3}</code>、<code>set(序列)</code>、<code>set()</code>。方法：<code>add(x)</code>、<code>remove(x)</code>（不存在报错）、<code>discard(x)</code>（不存在不报错）、<code>pop()</code> 随机取、<code>clear()</code>。注意集合不能索引、不能切片，输出顺序不保证。","fx":["s = set([1,2,2,3])   → {1,2,3}","2 in s   → True，快","s.add(4); s.discard(99)"],"key":"要判断\"在不在\"，用集合远比列表快。"},
  "集合去重": {"tag":"第5章 组合数据类型（一）","sub":"set() 去重再 list() 转回","def":"把列表传进 <code>set()</code> 就能去掉重复元素（顺序不保留），需要列表时再 <code>list()</code> 转回。<b>注意这会丢掉原始顺序</b>——若必须保留首次出现的顺序，要用 <code>dict.fromkeys(ls)</code>（字典键有序）或手写遍历 + 判断。这是数据处理中最常用的两行代码之一。","fx":["ls = [1,2,2,3,3,3]","list(set(ls))            → [1,2,3]（顺序不定）","list(dict.fromkeys(ls))  → [1,2,3]（保序）"],"key":"set 去重不保序，要保序用 dict.fromkeys。"},
  "集合运算": {"tag":"第5章 组合数据类型（一）","sub":"差 交 并 补 子集","def":"四个运算符对应四种集合运算：<code>S − T</code> <b>差集</b>（在 S 不在 T）、<code>S &amp; T</code> <b>交集</b>、<code>S | T</code> <b>并集</b>、<code>S ^ T</code> <b>补集/对称差</b>（只属于其中一个）。关系运算：<code>S &lt;= T</code> 子集、<code>S &lt; T</code> 真子集、<code>S &gt;= T</code> 超集。也有同名方法 <code>difference()</code>、<code>intersection()</code>、<code>union()</code>。","fx":["A={1,2,3}  B={3,4,5}","A-B → {1,2}    A&B → {3}","A|B → {1,2,3,4,5}    A^B → {1,2,4,5}","A <= B → False"],"key":"交并差补对应 & | − ^，和数学一致。"},
  "jieba分词": {"tag":"第5章 组合数据类型（一）","sub":"中文分词的三种模式","def":"jieba 是第三方中文分词库（<code>pip install jieba</code>）。中文没有空格分隔，必须切词。三种模式：<b>精确模式</b> <code>jieba.lcut(s)</code> 最常用、无冗余；<b>全模式</b> <code>jieba.lcut(s, cut_all=True)</code> 把所有可能成词都切出（有冗余）；<b>搜索引擎模式</b> <code>jieba.lcut_for_search(s)</code> 在精确模式基础上再切长词，适合索引。返回的是<b>列表</b>。<code>jieba.add_word(w)</code> 可加自定义词。","fx":["jieba.lcut(\"人工智能\")     → [\"人工智能\"]","jieba.lcut(s, cut_all=True) → 全模式，有冗余","jieba.lcut_for_search(s)    → 搜索引擎模式","jieba.add_word(\"深度学习\")"],"key":"lcut 返回列表，cut 返回生成器。"},
  "词频统计": {"tag":"第5章 组合数据类型（一）","sub":"分词 → 计数字典 → 排序","def":"标准四步：① <code>words = jieba.lcut(txt)</code> 分词；② 建字典 <code>counts</code>，遍历词执行 <code>counts[w] = counts.get(w,0)+1</code>；③ <code>items = list(counts.items())</code> 转列表；④ <code>items.sort(key=lambda x: x[1], reverse=True)</code> 按次数降序，取前 N 项。<b>关键点：字典本身无序不能直接排序，必须先转成 list。</b>","fx":["counts = {}","for w in words: counts[w] = counts.get(w,0)+1","items = sorted(counts.items(), key=lambda x:-x[1])[:10]"],"key":"字典不能排序，items() 转 list 才能 sort。"},
  "分词库安装": {"tag":"第5章 组合数据类型（一）","sub":"pip install jieba","def":"jieba 不是标准库，需先安装：在命令行（Anaconda Prompt）执行 <code>pip install jieba</code>。国内网络慢时加镜像：<code>pip install jieba -i https://pypi.tuna.tsinghua.edu.cn/simple</code>。安装后 <code>import jieba</code> 即可用。注意：标准库（math、random、os、csv、datetime、turtle）<b>不需要装</b>，第三方库（jieba、numpy、pandas、requests）才需要。","fx":["pip install jieba","pip install jieba -i https://pypi.tuna.tsinghua.edu.cn/simple","import jieba   # 装完才能 import"],"key":"报 ModuleNotFoundError 八成是没 pip install。"},
  "字典dict": {"tag":"第6章 组合数据类型（二）","sub":"键值对集合，O(1) 查找","def":"字典是键值对集合，<code>d = {\"name\":\"Tom\", \"age\":18}</code>。<b>键唯一且必须可哈希</b>（str/int/tuple），值任意。底层是哈希表，<b>查找平均 O(1)</b>，与大小基本无关，这是它相对列表的最大优势。基本操作：<code>d[k]</code> 取值（键不存在 <code>KeyError</code>）、<code>d[k]=v</code> 新增或改、<code>del d[k]</code> 删、<code>k in d</code> 判断键、<code>len(d)</code> 个数。","fx":["d = {\"a\":1, \"b\":2}","d[\"a\"] → 1       d[\"c\"]=3 新增","del d[\"a\"]       \"a\" in d → False"],"key":"字典按键查，键必须唯一且可哈希。"},
  "键值对": {"tag":"第6章 组合数据类型（二）","sub":"key: value 的映射","def":"字典的每个元素是\"键 : 值\"一对，写法 <code>{键: 值}</code>。键是\"名字\"，值是\"内容\"，通过键找到值。<b>键不可重复</b>——重复赋值会覆盖旧值（不会报错，只保留后者）。键必须可哈希（不可变），值可以是任意类型，包括列表、字典、函数。在遍历时用 <code>d.items()</code> 同时拿到键和值。","fx":["d = {\"x\": 1, \"x\": 2}   → {\"x\": 2}，后者覆盖","d = {\"ls\": [1,2], \"f\": len}   值可为任意类型","for k, v in d.items(): ..."],"key":"键是唯一的索引，值才是内容。"},
  "字典get方法": {"tag":"第6章 组合数据类型（二）","sub":"d.get(k, 默认值)","def":"<code>d.get(k)</code> 取键 k 的值，<b>键不存在时返回 None 而不报错</b>；<code>d.get(k, 默认值)</code> 键不存在时返回指定的默认值。这与 <code>d[k]</code> 的关键差别：后者键不存在会抛 <code>KeyError</code>。所以计数、配置读取等\"键可能不存在\"的场景一律用 get。计数惯用法 <code>d[k] = d.get(k,0)+1</code> 就靠它给初值。","fx":["d = {\"a\": 1}","d[\"b\"]          → KeyError","d.get(\"b\")      → None","d.get(\"b\", 0)   → 0","d[\"b\"] = d.get(\"b\",0)+1   → 计数标准写法"],"key":"拿不准键在不在，就用 get 加默认值。"},
  "字典视图keys-values-items": {"tag":"第6章 组合数据类型（二）","sub":"三个视图对象","def":"<code>d.keys()</code> 返回所有键、<code>d.values()</code> 返回所有值、<code>d.items()</code> 返回 (键,值) 元组。它们返回的是<b>视图 view</b>而非列表——是动态的（字典一变视图也变），且可以用 <code>list()</code> 转成列表。注意 <code>values()</code> 不能直接转 set 去重求\"不同值的个数\"时要注意值可能不可哈希。","fx":["list(d.keys())    → [\"a\",\"b\"]","list(d.values())  → [1,2]","list(d.items())   → [(\"a\",1),(\"b\",2)]"],"key":"视图是动态的，要固定内容就 list() 一下。"},
  "字典遍历": {"tag":"第6章 组合数据类型（二）","sub":"三种遍历方式","def":"① <code>for k in d:</code> 遍历<b>键</b>（最常用）；② <code>for k in d.keys():</code> 同上，等价；③ <code>for v in d.values():</code> 只遍历值；④ <code>for k, v in d.items():</code> 同时拿键和值（最实用）。遍历过程中<b>不要增删字典元素</b>，会抛 <code>RuntimeError: dictionary changed size during iteration</code>；要先 <code>list(d.items())</code> 固定下来再改。","fx":["for k in d: print(k)              遍历键","for v in d.values(): print(v)      遍历值","for k, v in d.items(): print(k, v) 键值都拿"],"key":"边遍历边改字典会崩，先 list 一份。"},
  "函数作为字典的值": {"tag":"第6章 组合数据类型（二）","sub":"用字典做分支分派","def":"因为字典的<b>值可以是任意对象</b>，包括函数，所以可以把\"运算符 → 函数\"存成字典：<code>ops = {\"+\": add, \"-\": sub}</code>，然后 <code>ops[符号](x, y)</code> 直接调用。这叫<b>分派表</b>，用它替代一长串 if-elif，代码更短更好扩展——加减一个新运算只需往字典加一项，不必改判断逻辑。<b>注意写 <code>add</code> 不加括号</b>（存函数本身），加括号就变成存调用结果了。","fx":["def add(x,y): return x+y","ops = {\"+\": add, \"-\": lambda x,y: x-y}","ops[\"+\"](3, 4)   → 7"],"key":"存函数不写括号，写了就是存结果。"},
  "哈希表": {"tag":"第6章 组合数据类型（二）","sub":"字典为什么快","def":"字典/集合底层是<b>哈希表</b>：先用 <code>hash(键)</code> 算出一个整数，再对表长取模得到\"桶\"下标，直接在那一格找值——所以<b>平均 O(1)</b>，与元素个数几乎无关。代价：① 元素无序（位置由哈希决定）；② 需要额外内存；③ 哈希冲突时要探测（最坏退化为 O(n)）。列表按键值线性查找是 O(n)，一万条数据就是一万次比较，这就是字典快的原因。","fx":["hash(\"a\") → 某个固定整数","字典查找：hash → 取模 → 定位桶，平均 O(1)","列表 x in ls：逐个比较，O(n)"],"key":"哈希把\"查找\"变成\"计算地址\"。"},
  "可哈希对象": {"tag":"第6章 组合数据类型（二）","sub":"能当键的前提","def":"一个对象\"可哈希\"需满足：实现了 <code>__hash__()</code>，且在其生命周期内哈希值不变（实际上要求<b>不可变</b>），相等判断用 <code>__eq__()</code>。只有可哈希对象才能做<b>字典的键</b>或<b>集合的元素</b>。<code>hash(obj)</code> 可测试，不可哈希会抛 <code>TypeError: unhashable type</code>。自定义类默认按 id 哈希（可哈希）；若重写了 <code>__eq__</code> 而没重写 <code>__hash__</code>，实例会变成不可哈希。","fx":["hash(\"abc\")   → 整数","hash([1,2])   → TypeError（不可哈希）","hash((1,2))   → 整数（元组可哈希）"],"key":"能不能当键，先问它可不可哈希。"},
  "不可变对象": {"tag":"第6章 组合数据类型（二）","sub":"不可变才可哈希","def":"<b>不可变对象</b>：创建后内部状态不能改——数值 int/float/complex、字符串 str、元组 tuple、布尔值、frozenset。它们可哈希，能当字典键。<b>可变对象</b>：列表 list、字典 dict、集合 set，内容能改所以哈希值会变，<b>不可哈希</b>。<b>注意元组的例外</b>：只含不可变元素的元组可哈希；若元组里含列表，整个元组也不可哈希（<code>(1,[2])</code> 就不行）。","fx":["可哈希：int, float, str, tuple(元素都不可变), bool, frozenset","不可哈希：list, dict, set","hash((1, [2])) → TypeError"],"key":"不可变 → 可哈希 → 能当键，链条不能断。"},
  "filter函数": {"tag":"第6章 组合数据类型（二）","sub":"filter(f, seq) 过滤","def":"<code>filter(函数, 序列)</code> 把序列每个元素传给函数，<b>保留返回真</b>的元素，返回一个<b>迭代器</b>（惰性，需 <code>list()</code> 才看到内容）。函数可为 None（此时直接滤掉假值）。常与 lambda 搭配：<code>filter(lambda x: x&gt;0, ls)</code>。等价的推导式写法 <code>[x for x in ls if x&gt;0]</code> 通常更易读。","fx":["list(filter(lambda x: x%2==1, [1,2,3,4]))  → [1,3]","list(filter(None, [0,1,\"\",2]))            → [1,2]","[x for x in ls if x>0]   等价推导式"],"key":"filter 返回迭代器，要看得见就 list()。"},
  "map函数": {"tag":"第6章 组合数据类型（二）","sub":"map(f, seq) 逐元素变换","def":"<code>map(函数, 序列)</code> 把函数应用到每个元素上，返回<b>迭代器</b>。<code>map(lambda x: x*2, ls)</code> 得每个元素翻倍。可传多个序列（按位置配对）：<code>map(lambda a,b: a+b, l1, l2)</code>。常用来批量类型转换，如 <code>list(map(int, input().split()))</code> 一次读入一行整数——这是竞赛和数据处理的高频写法。","fx":["list(map(lambda x: x*2, [1,2,3]))       → [2,4,6]","list(map(int, \"1 2 3\".split()))         → [1,2,3]","list(map(lambda a,b:a+b, [1,2],[10,20])) → [11,22]"],"key":"读一行整数：list(map(int, input().split()))。"},
  "reduce函数": {"tag":"第6章 组合数据类型（二）","sub":"把序列折叠成一个值","def":"<code>reduce(函数, 序列[, 初值])</code> 用\"两两合并\"的方式把序列折叠成<b>一个值</b>：先取前两个算，结果再与第三个算……最终得单值。<b>它不在内置函数里</b>，必须 <code>from functools import reduce</code>。典型用途：连乘、最大公约数累积、字符串拼接。<code>sum()</code> 其实就是 reduce 的特例。","fx":["from functools import reduce","reduce(lambda a,b: a+b, [1,2,3,4])   → 10","reduce(lambda a,b: a*b, [1,2,3,4])   → 24"],"key":"reduce 要 import functools，结果是单个值。"},
  "deque": {"tag":"第6章 组合数据类型（二）","sub":"双端队列","def":"<code>collections.deque</code> 是双端队列，两端增删都是 <b>O(1)</b>（列表的 <code>insert(0,x)</code> 是 O(n)）。方法：<code>append(x)</code>/<code>appendleft(x)</code>、<code>pop()</code>/<code>popleft()</code>、<code>extend</code>、<code>rotate(n)</code>。还可 <code>deque(maxlen=n)</code> 固定长度（满了自动从另一端丢）。典型用途：<b>队列（BFS）</b>、<b>栈</b>、滑动窗口、保留最近 N 条记录。","fx":["from collections import deque","q = deque([1,2,3])","q.append(4); q.popleft() → 1","deque(maxlen=3)  只保留最近 3 个"],"key":"头尾都要动就用 deque，别用 list.insert(0)。"},
  "Counter": {"tag":"第6章 组合数据类型（二）","sub":"计数器，直接统计频次","def":"<code>collections.Counter</code> 是 dict 的子类，专门计数：<code>Counter(可迭代对象)</code> 自动统计每个元素出现次数。<code>most_common(n)</code> 返回次数最多的前 n 项（列表 of 元组）；<code>update()</code> 累加；支持 <code>+ − &amp; |</code> 运算合并计数。用它做词频统计，比自己写 for 循环 + get 少一半代码。键不存在时返回 0（不报错）。","fx":["from collections import Counter","Counter(\"abracadabra\")  → Counter({\"a\":5,\"b\":2,\"r\":2,...})",".most_common(3)  → [(\"a\",5),(\"b\",2),(\"r\",2)]"],"key":"统计频次先想 Counter，别手写循环。"},
  "defaultdict": {"tag":"第6章 组合数据类型（二）","sub":"缺键自动建默认值","def":"<code>collections.defaultdict(工厂函数)</code> 是 dict 的子类：访问<b>不存在的键时自动用工厂函数创建默认值</b>而不抛 KeyError。常用 <code>defaultdict(int)</code>（默认 0，适合计数）、<code>defaultdict(list)</code>（默认空列表，适合分组）、<code>defaultdict(set)</code>。它把 <code>d[k] = d.get(k,0)+1</code> 简化为 <code>d[k] += 1</code>。","fx":["from collections import defaultdict","dd = defaultdict(int)","dd[\"new\"] += 1     → 1，不报错","dd = defaultdict(list); dd[\"a\"].append(1)"],"key":"defaultdict(list) 是\"分组\"的最快写法。"},
  "列表推导式与生成器": {"tag":"第6章 组合数据类型（二）","sub":"[] 立即生成，( ) 惰性生成","def":"<code>[x for x in …]</code> 是<b>列表推导式</b>，立即把全部元素算出来放进内存。<code>(x for x in …)</code> 是<b>生成器表达式</b>，只产生一个迭代器，<b>惰性求值</b>——用到才算，只能遍历一次，但几乎不占内存。数据量大或只需遍历一次时用生成器；要反复访问、要 len/索引时用列表。<code>sum(x for x in …)</code> 就省掉了中间的列表。","fx":["[x*x for x in range(1000000)]   → 立即占大量内存","(x*x for x in range(1000000))   → 迭代器，几乎不占","sum(x for x in range(100))      → 无需建列表"],"key":"方括号要内存，圆括号要时间。"},
  "文本文件": {"tag":"第7章 IO编程","sub":"有统一字符编码，可读","def":"文本文件由<b>单一特定编码</b>（如 UTF-8）组成的字符序列存储，打开能直接看懂内容，如 .txt、.py、.csv、.html。读写时 Python 会在<b>字节 ↔ 字符</b>之间做编码解码，所以要显式指定 <code>encoding</code>。与之相对的是二进制文件。","fx":["open(\"a.txt\",\"r\",encoding=\"utf-8\")","常见文本文件：.txt .py .csv .json .html"],"key":"文本文件是\"字符\"，二进制文件是\"字节\"。"},
  "二进制文件": {"tag":"第7章 IO编程","sub":"无统一编码，需专用软件","def":"二进制文件直接由<b>比特 0/1</b> 组成，<b>没有统一的字符编码</b>，必须用对应的软件解析（图片要用看图软件、音频要用播放器）。如 .jpg、.exe、.docx、.mp3。打开时模式加 <code>b</code>（如 <code>\"rb\"</code>），读出的是 <code>bytes</code> 对象，写入要用 <code>b\"...\"</code>。文本文件与二进制文件的本质差别就在<b>是否有统一编码</b>。","fx":["open(\"a.jpg\",\"rb\")   读 bytes","f.read()  → b\"\\x89PNG...\"","不能用记事本正确打开 .exe"],"key":"b 模式读写字节，不加 b 读写字符。"},
  "字符编码UTF-8": {"tag":"第7章 IO编程","sub":"可变长，中文 3 字节","def":"UTF-8 是 Unicode 的<b>可变长度</b>实现：英文 1 字节、中文（常用汉字）<b>3 字节</b>、少数生僻字 4 字节。它兼容 ASCII，是互联网最通用的编码。Python 3 源码默认 UTF-8，读写文本文件时<b>务必写 <code>encoding=\"utf-8\"</code></b>——Windows 中文环境默认是 GBK，不指定就会 <code>UnicodeDecodeError</code> 或乱码。","fx":["open(\"a.txt\",\"r\",encoding=\"utf-8\")","\"中\".encode(\"utf-8\")  → b\"\\xe4\\xb8\\xad\"（3 字节）","\"a\".encode(\"utf-8\")   → 1 字节"],"key":"读写文本一律显式 utf-8，跨平台才不出乱码。"},
  "ASCII与Unicode": {"tag":"第7章 IO编程","sub":"从 7 位到统一码点","def":"<b>ASCII</b>：7 位二进制，共 128 个编码，只覆盖英文字母、数字、标点与控制符，中文无法表示。<b>Unicode</b>：统一字符集，为世界上每个字符分配一个唯一<b>码点</b>（如\"中\"是 U+4E2D），理论容量超百万。<b>UTF-8/UTF-16/UTF-32</b> 是把码点落到字节的具体实现方案（编码方式）。记法：Unicode 是\"给字符编号\"，UTF-8 是\"把编号写成字节\"。","fx":["ord(\"A\") → 65     ord(\"中\") → 20013 (0x4E2D)","chr(20013) → \"中\"","ASCII 只 128 个，中文必须用 Unicode"],"key":"Unicode 是编号表，UTF-8 是存储格式。"},
  "open函数": {"tag":"第7章 IO编程","sub":"open(path, mode, encoding)","def":"<code>open(文件路径, 打开模式, encoding=None)</code> 返回文件对象。<b>文本模式</b>必须给 encoding（推荐 utf-8）；<b>二进制模式</b>不写 encoding。文件名可用相对路径（相对当前工作目录）或绝对路径，跨平台拼接用 <code>os.path.join</code>。打开后<b>必须 close()</b>，否则数据可能没写入磁盘/句柄泄漏——规范做法是用 <code>with</code>。","fx":["f = open(\"d.txt\", \"r\", encoding=\"utf-8\")","... 操作 ...","f.close()","# 推荐：with open(...) as f:"],"key":"open 了就必须 close，with 帮你自动关。"},
  "文件打开模式": {"tag":"第7章 IO编程","sub":"r w a x b t +","def":"七种模式：<code>\"r\"</code> 只读（默认，文件不存在报错）；<code>\"w\"</code> 只写，<b>会清空原内容</b>，不存在则创建；<code>\"x\"</code> 创建新文件，已存在报错；<code>\"a\"</code> 追加，不清空、指针在末尾；<code>\"b\"</code> 二进制（与上面组合如 \"rb\"）；<code>\"t\"</code> 文本（默认）；<code>\"+\"</code> 增加读写能力（如 \"r+\"）。<b>最危险的是 \"w\"</b>——误用会瞬间清空重要文件。","fx":["\"r\"  只读，不存在报错（默认）","\"w\"  清空重写！","\"a\"  追加，不清空","\"r+\" 可读可写，指针在开头"],"key":"\"w\" 会清空文件，改文件优先考虑 \"a\" 或 \"r+\"。"},
  "read-readline-readlines": {"tag":"第7章 IO编程","sub":"三种读法","def":"<code>f.read(size)</code> 一次读全部（或 size 个字符），返回<b>字符串</b>；<code>f.readline()</code> 读<b>一行</b>，返回字符串（含换行符）；<code>f.readlines()</code> 读所有行，返回<b>列表</b>（每项含 <code>\\n</code>）。大文件不要用 read()/readlines() 一次全读进内存，应<b>直接 for 遍历文件对象</b>逐行处理，或 <code>for line in f:</code>。","fx":["f.read()        → 整串","f.readline()    → 一行（带 \\n）","f.readlines()   → [\"行1\\n\",\"行2\\n\"]","for line in f: 逐行，省内存"],"key":"大文件别 readlines，直接 for line in f。"},
  "write与writelines": {"tag":"第7章 IO编程","sub":"写入不自动加换行","def":"<code>f.write(s)</code> 写入<b>字符串</b>，<b>只接受 str</b>——写数字必须先 <code>str()</code> 转换，否则 <code>TypeError: write() argument must be str</code>。<code>f.writelines(列表)</code> 写入字符串列表，<b>同样不会自动在元素间加换行</b>，需要换行得自己给每个元素末尾加 <code>\\n</code>。返回值是写入的字符数。写完后 close 才会真正落盘。","fx":["f.write(\"abc\\n\")","f.write(123)              → TypeError，要先 str(123)","f.writelines([\"a\\n\",\"b\\n\"])   换行要自己加"],"key":"write 只吃字符串，且不自动换行。"},
  "seek与tell": {"tag":"第7章 IO编程","sub":"文件指针定位","def":"<code>f.tell()</code> 返回当前指针位置（文本模式按<b>字符</b>计，二进制按<b>字节</b>计）；<code>f.seek(offset, whence)</code> 移动指针，whence 默认 0 表示从文件头算（1 从当前位置、2 从末尾，<b>文本模式下 1/2 通常不支持</b>）。<code>f.seek(0)</code> 回到开头——想在同一个文件对象上再读一遍就必须先 seek(0)，否则读到的是空。","fx":["f.tell()     → 当前位置","f.seek(0)    → 回到开头，可重复读","f.seek(10)   → 跳到第 10 个字符/字节"],"key":"同一个文件对象读第二遍，先 seek(0)。"},
  "with-as上下文管理器": {"tag":"第7章 IO编程","sub":"块结束自动关闭文件","def":"<code>with open(...) as f:</code> 把文件对象交给 with 管理，<b>代码块结束（包括异常退出）时自动调用 close()</b>。好处：不会忘记关闭、异常时也能正确释放资源、代码更短。这是读写文件的<b>规范写法</b>，工程与考试都推荐。等价于 try-finally 但简洁得多。也可一次打开多个：<code>with open(a) as f1, open(b) as f2:</code>。","fx":["with open(\"a.txt\",\"r\",encoding=\"utf-8\") as f:","····data = f.read()","# 出块即自动 close"],"key":"凡是 open，都套 with。"},
  "CSV格式": {"tag":"第7章 IO编程","sub":"逗号分隔值","def":"CSV（Comma-Separated Values）是存储一二维数据最通用的格式，规则三条：① 以<b>英文逗号</b>分隔字段；② 以<b>换行</b>表示不同行/记录；③ 若字段内容本身含逗号、换行或引号，需用<b>引号包裹转义</b>（内部引号写两个）。后缀 .csv，可用 Excel、文本编辑器直接打开。它是数据库与表格软件之间交换数据的\"普通话\"。","fx":["姓名,成绩","张三,92","李四,88","\"Smith, John\",95   ← 内容含逗号要加引号"],"key":"逗号分隔、换行分行，含逗号的字段要加引号。"},
  "一维数据": {"tag":"第7章 IO编程","sub":"线性排列","def":"一维数据是<b>线性排列</b>、只有一个维度的数据，如一串成绩、一行名单。Python 中对应<b>列表</b>（有顺序、可重复）或<b>集合</b>（无序、去重）。存储到文件通常每行一个值，或用逗号连成一行。读取时 <code>readlines()</code> + <code>strip()</code> 得到列表，或 <code>split(\",\")</code> 切分。","fx":["ls = [92, 88, 95]      → 列表形式","set(ls)                → 集合形式，去重","文件存储：每行一个值"],"key":"一维数据 = 一串数，对应 list 或 set。"},
  "二维数据": {"tag":"第7章 IO编程","sub":"表格形态","def":"二维数据是由一维数据组合而成的<b>表格形态</b>：有行也有列，如成绩单（每行一个学生，每列一门课）。Python 中对应<b>\"列表的列表\"</b>：<code>[[姓名,成绩],[张三,92],[李四,88]]</code>。遍历要双层 for：外层走行，内层走列。CSV 是二维数据最自然的存储格式。","fx":["data = [[\"姓名\",\"成绩\"], [\"张三\",92], [\"李四\",88]]","for row in data:","····for cell in row: ..."],"key":"二维数据 = 列表的列表，双层 for 遍历。"},
  "csv模块": {"tag":"第7章 IO编程","sub":"csv.reader / csv.writer","def":"标准库 csv 负责读写 CSV 并自动处理引号转义：<code>csv.reader(f)</code> 逐行返回<b>字段列表</b>；<code>csv.writer(f)</code> 用 <code>writerow(列表)</code> 写一行、<code>writerows(二维列表)</code> 写多行。两个要点：写文件时 open 要加 <b><code>newline=\"\"</code></b>（否则 Windows 下会多空行）；读出的字段<b>都是字符串</b>，数字要自己 <code>int()</code> 转换。","fx":["import csv","with open(\"t.csv\",\"w\",newline=\"\",encoding=\"utf-8\") as f:","····csv.writer(f).writerow([\"姓名\",\"成绩\"])","for row in csv.reader(f): print(row)"],"key":"写 CSV 记得 newline=\"\"，否则多空行。"},
  "os模块": {"tag":"第7章 IO编程","sub":"操作系统接口","def":"os 是标准库，提供与操作系统交互的函数：<code>os.getcwd()</code> 当前目录、<code>os.chdir(p)</code> 切换目录、<code>os.listdir(p)</code> 列出目录内容、<code>os.mkdir(p)</code> 建单级目录、<code>os.makedirs(p)</code> 建多级目录、<code>os.remove(p)</code> 删文件、<code>os.rmdir(p)</code> 删空目录、<code>os.rename(a,b)</code> 重命名。操作文件系统前先判断存在性更安全。","fx":["import os","os.getcwd()       当前工作目录","os.listdir(\".\")   当前目录下所有名字","os.makedirs(\"a/b/c\")  建多级目录"],"key":"os 管目录与文件，os.path 管路径字符串。"},
  "os.path": {"tag":"第7章 IO编程","sub":"路径的拆分与判断","def":"os.path 专门处理路径字符串：<code>exists(p)</code> 是否存在、<code>isfile/isdir</code> 是文件/目录、<code>join(a,b)</code> <b>跨平台安全拼接</b>（Windows 用 \\、Linux 用 /，它会自动选对）、<code>basename(p)</code> 取文件名、<code>dirname(p)</code> 取目录、<code>splitext(p)</code> 拆成 (主名, 扩展名)、<code>getsize(p)</code> 字节大小、<code>abspath(p)</code> 绝对路径。<b>别手工拼 \"/\"</b>，用 join。","fx":["os.path.join(\"data\", \"a.txt\")   → data\\a.txt（Win）","os.path.splitext(\"a.txt\")      → (\"a\", \".txt\")","os.path.exists(\"a.txt\")        → True/False"],"key":"拼路径一律 os.path.join，别手写斜杠。"},
  "os.listdir": {"tag":"第7章 IO编程","sub":"列出目录内容","def":"<code>os.listdir(path)</code> 返回指定目录下<b>所有文件和子目录的名字列表</b>（只名字，不含父路径；含隐藏文件；顺序不保证）。常配合 <code>os.path.splitext</code> 筛选特定后缀，如只处理 .txt 文件；配合 <code>os.path.join</code> 拼成完整路径。<b>不会递归</b>进子目录，要递归用 <code>os.walk()</code>。","fx":["for name in os.listdir(\".\"):","····if name.endswith(\".txt\"): print(name)","os.walk(\".\")   递归遍历（dirpath, dirs, files）"],"key":"listdir 只列一层，要递归用 os.walk。"},
  "面向对象编程OOP": {"tag":"第8章 面向对象编程（一）","sub":"以对象为基本单位","def":"OOP 把程序组织成一个个<b>对象</b>，每个对象 = <b>数据（属性）+ 操作数据的方法</b>。它以\"名词/实体\"为中心建模（学生、账户、按钮），更贴近真实世界，适合大型、多人协作、需要长期演进的系统。三大特性：<b>封装</b>（数据方法打包、隐藏细节）、<b>继承</b>（复用父类）、<b>多态</b>（同一接口不同实现）。","fx":["对象 = 属性 + 方法","class Student:  def __init__(self,name): self.name = name"],"key":"OOP 用\"对象\"建模，POP 用\"步骤\"建模。"},
  "面向过程编程POP": {"tag":"第8章 面向对象编程（一）","sub":"以函数和步骤为单位","def":"POP（面向过程）把问题拆成一串<b>函数/过程</b>，数据与操作<b>分离</b>——函数读入数据、处理、返回结果。优点是直观、简单、开销小，适合算法题、小脚本、一次性任务。缺点：数据没有保护（谁都能改）、规模一大函数层层调用难维护、复用只能靠函数。Python 同时支持两种范式，实际项目常混用。","fx":["POP：data = [...]; def process(data): ...","OOP：class Data:  def process(self): ..."],"key":"小脚本 POP 够用，系统大了就上 OOP。"},
  "封装与继承与多态": {"tag":"第8章 面向对象编程（一）","sub":"OOP 三大特性","def":"<b>封装</b>：把属性与方法打包进类，对外只暴露必要接口，内部实现可自由修改（用双下划线实现私有）。<b>继承</b>：<code>class B(A)</code> 让 B 拥有 A 的全部属性与方法，可覆写，实现代码复用与\"is-a\"关系。<b>多态</b>：不同类实现同名方法，调用同一接口时各自表现不同（如各种 Shape 都有自己的 area()）。本章（一）重点是封装，继承与多态在第（二）部分展开。","fx":["封装：self.__bal 私有 + deposit() 公开接口","继承：class Dog(Animal): ...","多态：不同类的 area() 各算各的"],"key":"封装藏细节，继承少写代码，多态一个接口多种行为。"},
  "类class": {"tag":"第8章 面向对象编程（一）","sub":"模板 / 蓝图","def":"类是创建对象的<b>模板</b>，用 <code>class 类名:</code> 定义，类名习惯<b>首字母大写</b>（驼峰命名）。类体里可定义属性与方法。类本身不占\"实例内存\"，它描述\"这类对象长什么样、能做什么\"。一个类可以创建任意多个实例。类里的代码在<b>定义时就会执行一次</b>（用于建类属性）。","fx":["class Student:","····school = \"某某大学\"      # 类属性","····def __init__(self, name):","········self.name = name  # 实例属性"],"key":"类是模具，实例是压出来的零件。"},
  "实例instance": {"tag":"第8章 面向对象编程（一）","sub":"按类创建的具体对象","def":"实例是按类创建出来的<b>具体对象</b>，创建语法 <code>对象名 = 类名(实参)</code>，会自动调用 <code>__init__</code>。每个实例有自己独立的一份<b>实例属性</b>，互不干扰（Tom 的 age 和 Lily 的 age 是两个变量）。用 <code>isinstance(obj, 类)</code> 判断类型，<code>type(obj)</code> 查类型。","fx":["s1 = Student(\"Tom\", 18)","s2 = Student(\"Lily\", 19)","s1.age = 20   不影响 s2.age"],"key":"一个类可造无数实例，每个实例属性独立。"},
  "构造函数__init__": {"tag":"第8章 面向对象编程（一）","sub":"创建实例时自动调用","def":"<code>__init__(self, 参数…)</code> 是<b>构造方法</b>，在 <code>类名(...)</code> 创建实例时<b>自动执行</b>，用来初始化实例属性。<b>它不是\"新建对象\"的方法</b>（新建是 <code>__new__</code>），而是\"对象造好后给它填初值\"。它<b>不能有返回值</b>（返回非 None 会报错）。参数在创建实例时传入。","fx":["class S:","····def __init__(self, name, age):","········self.name = name","········self.age = age","s = S(\"Tom\", 18)   # 自动调用 __init__"],"key":"__init__ 只负责初始化，不负责创建。"},
  "self": {"tag":"第8章 面向对象编程（一）","sub":"指向实例自身","def":"<code>self</code> 代表<b>当前实例对象本身</b>，是实例方法的<b>第一个参数</b>。<b>定义时必须写，调用时不用传</b>——<code>s.intro()</code> 时 Python 自动把 s 作为 self 传进去。通过 <code>self.属性</code> 访问/创建该实例的属性。<code>self</code> 只是约定俗成的名字（写 this 也行），但请遵循惯例，否则别人读不懂。","fx":["def intro(self):          # 定义要写 self","····return self.name","s.intro()                # 调用不传 self"],"key":"self 就是\"我自己\"，定义要写、调用不传。"},
  "数据封装": {"tag":"第8章 面向对象编程（一）","sub":"属性与方法绑定，暴露接口","def":"封装的落地做法：把数据（属性）和对数据的操作（方法）<b>打包在同一个类里</b>，外部<b>只通过方法</b>访问数据，不直接改。这样校验规则集中在类内部——比如取款必须先判断余额，外部就绕不过这条规则；将来改内部实现（如加日志、加手续费）也不必改调用方。<b>封装 = 黑盒思想</b>，是 OOP 最实用的一条。","fx":["class Account:","····def withdraw(self, x):","········if x > self.__bal: return \"余额不足\"","········self.__bal -= x"],"key":"封装的意义：规则写在类里，谁都不能绕过去。"},
  "类属性与实例属性": {"tag":"第8章 面向对象编程（一）","sub":"共享一份 vs 各有一份","def":"<b>类属性</b>在类体中直接定义（不在方法里），<b>所有实例共享一份</b>，通过 <code>类名.属性</code> 访问，适合存常量、计数器。<b>实例属性</b>在 <code>__init__</code> 里用 <code>self.x</code> 定义，<b>每个实例各一份</b>。<b>陷阱</b>：通过实例给\"类属性同名\"赋值（<code>s.bank = \"x\"</code>）不会改类属性，而是在实例上<b>新建了一个同名实例属性</b>，从此该实例屏蔽类属性，其他实例不受影响。","fx":["class A:","····cnt = 0            # 类属性，共享","····def __init__(self):","········self.x = 1   # 实例属性，独立"],"key":"类属性共享、实例属性独立；别用实例去改类属性。"},
  "方法Method": {"tag":"第8章 面向对象编程（一）","sub":"类内的函数","def":"定义在类内部、<b>第一个参数为 self</b> 的函数叫实例方法，通过 <code>对象.方法名()</code> 调用。它与普通函数差别就在这个 self。还有两类：<b>类方法</b> <code>@classmethod</code>（第一个参数是 cls，操作类）、<b>静态方法</b> <code>@staticmethod</code>（没有 self/cls，就是个放在类命名空间里的普通函数）。方法是对象\"能做什么\"的封装。","fx":["def intro(self):          # 实例方法","@classmethod","def create(cls): ...      # 类方法","@staticmethod","def util(): ...           # 静态方法"],"key":"方法 = 类里的函数，实例方法必带 self。"},
  "私有变量": {"tag":"第8章 面向对象编程（一）","sub":"双下划线开头，外部不能直接访问","def":"属性名以<b>两个下划线</b>开头（不以两个下划线结尾）即视为私有，如 <code>self.__bal</code>。Python 会把它<b>改名</b>成 <code>_类名__bal</code>，所以外部写 <code>obj.__bal</code> 会抛 <code>AttributeError</code>。私有属性只能在类内部（方法里）访问，外部要读就提供公开方法（如 <code>get_balance()</code>）。这是\"约定 + 机制\"双重保护，但并非绝对安全（知道改名规则仍能拿到）。","fx":["class Account:","····def __init__(self):","········self.__bal = 0      # 私有","a.__bal         → AttributeError","a.get_balance() → 通过方法读"],"key":"双下划线开头就是私有，出不了这个类。"},
  "名称改写name-mangling": {"tag":"第8章 面向对象编程（一）","sub":"__x 变成 _类名__x","def":"Python 没有真正的 private 关键字，靠<b>名称改写</b>实现：类中以双下划线开头（且不由双下划线结尾）的名字，编译时会被自动改成 <code>_类名__原名</code>。所以 <code>class A: self.__x</code> 实际存为 <code>_A__x</code>。作用：① 挡住外部随意访问；② 避免子类无意覆盖父类的同名属性。注意 <code>__init__</code>、<code>__str__</code> 这类<b>前后都有双下划线</b>的名字<b>不会被改写</b>（它们是魔术方法）。","fx":["class A: self.__x → 实际属性名 _A__x","a._A__x   能访问（但不建议）","__init__ 前后双下划线 → 不改写"],"key":"改写只针对\"前双下划线、后不加\"的名字。"},
  "公有变量": {"tag":"第8章 面向对象编程（一）","sub":"不加或单下划线","def":"<b>公有成员</b>：名字不加下划线（<code>self.name</code>），外部可自由读写。<b>约定内部用</b>：<b>一个下划线</b>开头（<code>self._cache</code>），Python <b>不会</b>做任何限制，只是一个\"请别碰我\"的礼貌提示（也给 IDE 和 from … import * 提供暗示）。三种命名的取舍：真需要保护用双下划线，只是内部实现细节用单下划线，对外接口正常命名。","fx":["self.name   公有，随便用","self._tmp   约定内部用，无强制","self.__pwd  私有，有机制保护"],"key":"单下划线是礼貌，双下划线是机制。"},
  "特殊方法魔术方法": {"tag":"第8章 面向对象编程（一）","sub":"__init__ / __str__ 等","def":"<b>魔术方法</b>（dunder method）是名字<b>前后都有双下划线</b>的特殊方法，由 Python 在特定时机自动调用，用来让自定义类支持内置语法。常见：<code>__init__</code> 初始化、<code>__str__</code> print 时的可读字符串、<code>__repr__</code> 调试表示、<code>__len__</code> 支持 len()、<code>__eq__</code> 支持 ==、<code>__add__</code> 支持 +、<code>__getitem__</code> 支持下标、<code>__iter__</code> 支持 for。<b>不要自创这种双下划线名字</b>，那是 Python 的保留命名空间。","fx":["def __str__(self): return \"Student:\" + self.name","print(s)      → 自动调用 __str__","def __len__(self): ...   → len(obj) 可用"],"key":"前后双下划线是 Python 的，别自己发明。"}
};
